import re, json, sys, os

W = 88

def unwrap(lines, avail):
    """lines: list of strings (already de-indented). Return raw text with soft breaks joined."""
    out = []
    for i, l in enumerate(lines):
        if i == 0:
            out.append(l)
            continue
        prev = lines[i-1]
        if prev.strip() == '' or l.strip() == '':
            out.append('\n' + l)
            continue
        first = l.split(' ')[0] if not l.startswith(' ') else None
        if first is not None and len(prev) + 1 + len(first) > avail and not l.startswith(' '):
            out.append(' ' + l)
        else:
            out.append('\n' + l)
    return ''.join(out)

def parse(text, is_long):
    lines = text.split('\n')
    if lines and lines[-1] == '':
        lines = lines[:-1]
    # about until "Usage:"
    i = 0
    about = []
    while i < len(lines) and not lines[i].startswith('Usage: '):
        about.append(lines[i]); i += 1
    while about and about[-1] == '':
        about.pop()
    usage = [lines[i][len('Usage: '):]]
    i += 1
    while i < len(lines) and lines[i].startswith('       '):
        usage.append(lines[i][7:]); i += 1
    sections = []
    after = []
    while i < len(lines):
        if lines[i] == '':
            i += 1; continue
        m = re.match(r'^([A-Z][A-Za-z ]*):$', lines[i])
        if not m:
            after = lines[i:]
            break
        heading = m.group(1)
        i += 1
        body = []
        while i < len(lines):
            if lines[i] == '' and (i+1 >= len(lines) or re.match(r'^[A-Z][A-Za-z ]*:$', lines[i+1]) or not lines[i+1].startswith(' ')):
                break
            body.append(lines[i]); i += 1
        sections.append((heading, body))
    res = {'about': unwrap(about, W), 'usage': '\n'.join(usage), 'sections': []}
    for heading, body in sections:
        entries = []
        if is_long and heading != 'Commands':
            # entries: spec line at indent 2 (or 6), help at indent 10
            cur = None
            for l in body:
                if l.startswith('          ') or (l == '' and cur):
                    if cur is not None:
                        cur['help_lines'].append(l[10:])
                elif l.startswith('  '):
                    cur = {'spec': l.strip(), 'help_lines': []}
                    entries.append(cur)
            for e in entries:
                hl = e.pop('help_lines')
                while hl and hl[-1] == '':
                    hl.pop()
                e['help'] = unwrap(hl, W - 10)
        else:
            # short: "  spec  help" columns; also handle next-line style
            cur = None
            for l in body:
                if l.startswith('          ') and cur is not None and (cur['help'] == '' or True) and not re.match(r'^  \S', l):
                    # continuation or next-line help
                    cur['help_lines'].append(l.strip())
                    continue
                m = re.match(r'^  (\S.*?)(?:  +(\S.*))?$', l)
                if l.startswith('      --') or l.startswith('  -') or l.startswith('  [') or l.startswith('  <') or l.startswith('  ') :
                    m = re.match(r'^(  (?:    )?\S.*?)(?:  +(\S.*))?$', l)
                    cur = {'spec': m.group(1).strip(), 'help_lines': [m.group(2)] if m.group(2) else [], 'col': (len(l) - len(m.group(2))) if m.group(2) else None}
                    entries.append(cur)
            for e in entries:
                hl = e.pop('help_lines')
                col = e.pop('col')
                e['help'] = ' '.join(hl)  # approximate
        res['sections'].append({'heading': heading, 'entries': entries})
    if after:
        res['after'] = '\n'.join(after)
    return res

out = {}
d = sys.argv[1]
for f in sorted(os.listdir(d)):
    name, ext = f.rsplit('.', 1)
    with open(os.path.join(d, f)) as fh:
        txt = fh.read()
    if txt.startswith('error:'):
        continue
    out.setdefault(name, {})[ext] = parse(txt, ext == 'long')
