import json, re, sys
spec = json.load(open('/tmp/gen/spec.json'))

def rs(s):
    # rust string literal
    return json.dumps(s, ensure_ascii=False)

def parse_spec(sp):
    # returns dict
    d = {'short': None, 'long': None, 'value': None, 'optval': False, 'positional': False, 'required': False, 'multi': False}
    m = re.match(r'^(?:-(\w),?\s*)?(?:--([\w-]+))?(.*)$', sp)
    if sp.startswith('[') or sp.startswith('<'):
        d['positional'] = True
        m2 = re.match(r'^([\[<])([^\]>]+)[\]>](\.\.\.)?$', sp)
        d['name'] = m2.group(2)
        d['required'] = m2.group(1) == '<'
        d['multi'] = bool(m2.group(3))
        return d
    d['short'] = m.group(1)
    d['long'] = m.group(2)
    rest = m.group(3).strip()
    if rest.startswith('[=<'):
        d['optval'] = True
        d['value'] = rest[3:rest.index('>')]
    elif rest.startswith('<'):
        d['value'] = rest[1:rest.index('>')]
        if rest.endswith('...'):
            d['multi'] = True
    return d

def gen_cmd(key, name):
    s = spec[key]
    lg = s['long']; sh = s['short']
    out = []
    out.append(f'pub fn cmd_{key.replace("-", "_")}() -> Command {{')
    out.append(f'    Command::new({rs(name)})')
    out.append(f'        .about({rs(sh["about"])})')
    if lg['about'] != sh['about']:
        out.append(f'        .long_about({rs(lg["about"])})')
    out.append(f'        .override_usage({rs(lg["usage"])})')
    # map short helps by spec
    shorthelp = {}
    for sec in sh['sections']:
        for e in sec['entries']:
            shorthelp[e['spec']] = e['help']
    for sec in lg['sections']:
        heading = sec['heading']
        if heading == 'Commands':
            out.append(f'        // Commands: ' + ', '.join(e['spec'] for e in sec['entries']))
            continue
        for e in sec['entries']:
            spc = e['spec']
            if spc in ('-h, --help', '--color <when>'):
                continue
            d = parse_spec(spc)
            sh_help = shorthelp.get(spc, '???')
            lh = e['help']
            if d['positional']:
                line = f'        .arg(Arg::new({rs(d["name"])}).value_name({rs(d["name"])})'
                if d['required']: line += '.required(true)'
                if d['multi']: line += '.num_args(1..)'
            else:
                aid = d['long'] or d['short']
                line = f'        .arg(Arg::new({rs(aid)})'
                if d['short']: line += f".short('{d['short']}')"
                if d['long']: line += f'.long({rs(d["long"])})'
                if d['value']:
                    line += f'.value_name({rs(d["value"])})'
                    if d['optval']:
                        line += '.num_args(0..=1).require_equals(true)'
                    line += '.action(ArgAction::Set)'
                else:
                    line += '.action(ArgAction::SetTrue)'
            line += f'.help({rs(sh_help)})'
            if lh != sh_help:
                line += f'.long_help({rs(lh)})'
            if heading not in ('Options', 'Arguments'):
                line += f'.help_heading({rs(heading)})'
            line += ')'
            out.append(line)
    if 'after' in lg:
        out.append(f'        // AFTER: {rs(lg["after"])}')
    out[-1] = out[-1]
    out.append('}')
    return '\n'.join(out)

keys = sys.argv[1:] or [k for k in spec.keys()]
for k in keys:
    name = k.split('-')[-1] if not k.startswith('branch--') else k[len('branch'):]
    if k.startswith('completion-list-'):
        name = k[len('completion-list-'):]
    print(gen_cmd(k, name))
    print()
