//! Minimal terminal size detection used for help text wrapping.

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Width(pub u16);

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub struct Height(pub u16);

#[repr(C)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: u64, ...) -> i32;
    fn isatty(fd: i32) -> i32;
}

const TIOCGWINSZ: u64 = 0x5413;

fn size_of_fd(fd: i32) -> Option<(Width, Height)> {
    unsafe {
        if isatty(fd) != 1 {
            return None;
        }
        let mut ws = WinSize { ws_row: 0, ws_col: 0, ws_xpixel: 0, ws_ypixel: 0 };
        if ioctl(fd, TIOCGWINSZ, &mut ws as *mut WinSize) == -1 {
            return None;
        }
        if ws.ws_col > 0 && ws.ws_row > 0 {
            Some((Width(ws.ws_col), Height(ws.ws_row)))
        } else {
            None
        }
    }
}

/// Returns the size of the terminal attached to stdout, stderr, or stdin.
pub fn terminal_size() -> Option<(Width, Height)> {
    size_of_fd(1).or_else(|| size_of_fd(2)).or_else(|| size_of_fd(0))
}
EOF
