use clap::{Arg, ArgAction, Command};
use crate::cli::*;

pub struct AliasInfo {
    pub name: String,
    pub command: String,
    pub is_shell: bool,
}

const COLOR_LONG_HELP: &str = "Specify when to colorize the output.\n\n`auto` (the default) enables colored output only when outputting to a terminal or TTY. The `NO_COLOR` environment variable is respected.\n\n`always` and `never` unconditionlly enable/disable colored output, respectively.\n\n`ansi` forces color to be output using ANSI escape sequences, even in a Windows console.";

const C_LONG_HELP: &str = "Run as if stg was started in '<path>' instead of the current working directory. When multiple `-C` options are given, each subsequent non-absolute `-C <path>` is interpreted relative to the preceding `-C <path>`.\n\nThis option affects arguments that expect path names or path specs in that their interpretations of the path names would be made relative to the working directory caused by the `-C` option.";

pub fn command_categories() -> Vec<(&'static str, Vec<Command>)> {
    vec![
        ("Patch inspection commands", vec![cmd_diff(), cmd_files(), cmd_id(), cmd_log(), cmd_name(), cmd_show()]),
        ("Patch manipulation commands", vec![cmd_edit(), cmd_fold(), cmd_new(), cmd_refresh(), cmd_rename(), cmd_spill(), cmd_sync()]),
        ("Stack inspection commands", vec![cmd_email(), cmd_export(), cmd_next(), cmd_patches(), cmd_prev(), cmd_series(), cmd_top()]),
        ("Stack manipulation commands", vec![
            cmd_branch(), cmd_clean(), cmd_commit(), cmd_delete(), cmd_float(), cmd_goto(), cmd_hide(),
            cmd_import(), cmd_init(), cmd_pick(), cmd_pop(), cmd_pull(), cmd_push(), cmd_rebase(),
            cmd_redo(), cmd_repair(), cmd_reset(), cmd_sink(), cmd_squash(), cmd_uncommit(), cmd_undo(), cmd_unhide(),
        ]),
        ("Administration commands", vec![cmd_completion(), cmd_version()]),
    ]
}

fn section(heading: &str, items: &[(String, String)]) -> String {
    let width = items.iter().map(|(n, _)| n.chars().count()).max().unwrap_or(0);
    let mut s = format!("{heading}:\n");
    for (i, (name, about)) in items.iter().enumerate() {
        if i > 0 {
            s.push('\n');
        }
        let pad = width - name.chars().count();
        s.push_str(&format!("  {name}{}  {about}", " ".repeat(pad)));
    }
    s
}

pub fn alias_about(a: &AliasInfo) -> String {
    if a.is_shell {
        format!("Alias for shell command `{}`", a.command)
    } else {
        format!("Alias for `stg {}`", a.command)
    }
}

pub fn build_cli(aliases: &[AliasInfo]) -> Command {
    let cats = command_categories();
    let mut template = String::from("{about-with-newline}\n{usage-heading} {usage}\n\n");
    let mut sections = Vec::new();
    for (heading, cmds) in &cats {
        let items: Vec<(String, String)> = cmds
            .iter()
            .map(|c| (c.get_name().to_string(), c.get_about().map(|a| a.to_string()).unwrap_or_default()))
            .collect();
        sections.push(section(heading, &items));
    }
    if !aliases.is_empty() {
        let items: Vec<(String, String)> = aliases.iter().map(|a| (a.name.clone(), alias_about(a))).collect();
        sections.push(section("Aliases", &items));
    }
    sections.push(section(
        "Help",
        &[("help".to_string(), "Print this message or the help of the given subcommand(s)".to_string())],
    ));
    template.push_str(&sections.join("\n\n"));
    template.push_str("\n\nOptions:\n{options}");

    let mut cmd = Command::new("stg")
        .about("Maintain a stack of patches on top of a Git branch.")
        .override_usage("stg [OPTIONS] <command> [...]\n       stg [OPTIONS] <-h|--help>\n       stg --version")
        .help_template(template)
        .max_term_width(88)
        .disable_version_flag(true)
        .subcommand_required(false)
        .arg_required_else_help(true)
        .arg(Arg::new("version").long("version").action(ArgAction::SetTrue).help("Print version information"))
        .arg(
            Arg::new("C")
                .short('C')
                .value_name("path")
                .action(ArgAction::Append)
                .value_parser(clap::builder::NonEmptyStringValueParser::new())
                .help("Run as if started in <path>")
                .long_help(C_LONG_HELP),
        )
        .arg(
            Arg::new("color")
                .long("color")
                .value_name("when")
                .global(true)
                .action(ArgAction::Set)
                .value_parser(["auto", "always", "ansi", "never"])
                .hide_possible_values(true)
                .help("When to colorize output: auto, always, ansi, never")
                .long_help(COLOR_LONG_HELP),
        );
    for (_, cmds) in cats {
        for c in cmds {
            cmd = cmd.subcommand(c);
        }
    }
    for a in aliases {
        cmd = cmd.subcommand(
            Command::new(a.name.clone())
                .about(alias_about(a))
                .disable_help_flag(true)
                .arg(Arg::new("args").num_args(0..).allow_hyphen_values(true).trailing_var_arg(true)),
        );
    }
    cmd
}
EOF
