//! Error type used throughout the program.

use std::fmt;

#[derive(Debug, Clone)]
pub struct Error {
    pub msg: String,
    pub code: i32,
    /// When true, the message has already been printed (or should not be printed).
    pub silent: bool,
}

impl Error {
    pub fn new<S: Into<String>>(msg: S) -> Self {
        Error { msg: msg.into(), code: 2, silent: false }
    }
    pub fn with_code<S: Into<String>>(msg: S, code: i32) -> Self {
        Error { msg: msg.into(), code, silent: false }
    }
    pub fn silent(code: i32) -> Self {
        Error { msg: String::new(), code, silent: true }
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.msg)
    }
}

impl From<std::io::Error> for Error {
    fn from(e: std::io::Error) -> Self {
        Error::new(io_err_string(&e))
    }
}

/// Format an io::Error the way Rust's Display does (e.g. "No such file or directory (os error 2)").
pub fn io_err_string(e: &std::io::Error) -> String {
    format!("{e}")
}

pub type Result<T> = std::result::Result<T, Error>;

#[macro_export]
macro_rules! bail {
    ($($t:tt)*) => {
        return Err($crate::error::Error::new(format!($($t)*)))
    };
}

#[macro_export]
macro_rules! err {
    ($($t:tt)*) => {
        $crate::error::Error::new(format!($($t)*))
    };
}
EOF
echo ok"}

