//! Thin wrapper around the git command line tool.

use crate::error::{Error, Result};
use std::cell::RefCell;
use std::collections::HashMap;
use std::io::{BufRead, BufReader, Read, Write};
use std::path::{Path, PathBuf};
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};
use std::rc::Rc;

pub type Oid = String;

pub const EMPTY_TREE: &str = "4b825dc642cb6eb9a060e54bf8d69288fbee4904";

pub struct GitOutput {
    pub status: i32,
    pub stdout: Vec<u8>,
    pub stderr: Vec<u8>,
}

impl GitOutput {
    pub fn ok(&self) -> bool {
        self.status == 0
    }
    pub fn stdout_str(&self) -> String {
        String::from_utf8_lossy(&self.stdout).into_owned()
    }
    pub fn stderr_str(&self) -> String {
        String::from_utf8_lossy(&self.stderr).into_owned()
    }
}

#[derive(Default, Clone)]
pub struct GitRun<'a> {
    pub args: Vec<String>,
    pub env: Vec<(String, String)>,
    pub env_remove: Vec<String>,
    pub stdin: Option<&'a [u8]>,
    pub cwd: Option<PathBuf>,
    pub inherit_stdout: bool,
    pub inherit_stderr: bool,
}

impl<'a> GitRun<'a> {
    pub fn new<I, S>(args: I) -> Self
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        GitRun { args: args.into_iter().map(|s| s.as_ref().to_string()).collect(), ..Default::default() }
    }
    pub fn env(mut self, k: &str, v: &str) -> Self {
        self.env.push((k.to_string(), v.to_string()));
        self
    }
    pub fn env_remove(mut self, k: &str) -> Self {
        self.env_remove.push(k.to_string());
        self
    }
    pub fn index(self, path: Option<&Path>) -> Self {
        match path {
            Some(p) => self.env("GIT_INDEX_FILE", &p.to_string_lossy()),
            None => self,
        }
    }
    pub fn stdin(mut self, data: &'a [u8]) -> Self {
        self.stdin = Some(data);
        self
    }
    pub fn cwd(mut self, p: &Path) -> Self {
        self.cwd = Some(p.to_path_buf());
        self
    }
    pub fn inherit_stdout(mut self) -> Self {
        self.inherit_stdout = true;
        self
    }
    pub fn inherit_stderr(mut self) -> Self {
        self.inherit_stderr = true;
        self
    }

    pub fn run(&self) -> Result<GitOutput> {
        let mut cmd = Command::new("git");
        cmd.args(&self.args);
        for (k, v) in &self.env {
            cmd.env(k, v);
        }
        for k in &self.env_remove {
            cmd.env_remove(k);
        }
        if let Some(c) = &self.cwd {
            cmd.current_dir(c);
        }
        cmd.stdin(if self.stdin.is_some() { Stdio::piped() } else { Stdio::null() });
        cmd.stdout(if self.inherit_stdout { Stdio::inherit() } else { Stdio::piped() });
        cmd.stderr(if self.inherit_stderr { Stdio::inherit() } else { Stdio::piped() });
        let mut child = cmd.spawn().map_err(|e| Error::new(format!("could not execute `git`: {e}")))?;
        let writer = if let Some(data) = self.stdin {
            let mut stdin = child.stdin.take().unwrap();
            let data = data.to_vec();
            Some(std::thread::spawn(move || {
                let _ = stdin.write_all(&data);
            }))
        } else {
            None
        };
        let out = child.wait_with_output().map_err(|e| Error::new(format!("git: {e}")))?;
        if let Some(w) = writer {
            let _ = w.join();
        }
        Ok(GitOutput { status: out.status.code().unwrap_or(-1), stdout: out.stdout, stderr: out.stderr })
    }

    /// Run and require success. The error message mimics StGit's: "`git <sub>`: <stderr>".
    pub fn run_ok(&self) -> Result<GitOutput> {
        let out = self.run()?;
        if !out.ok() {
            return Err(self.failure(&out));
        }
        Ok(out)
    }

    pub fn failure(&self, out: &GitOutput) -> Error {
        let sub = self.args.iter().find(|a| !a.starts_with('-')).cloned().unwrap_or_default();
        let msg = out.stderr_str();
        let msg = msg.trim_end();
        if msg.is_empty() {
            Error::new(format!("`git {sub}` failed with code {}", out.status))
        } else {
            Error::new(format!("`git {sub}`: {msg}"))
        }
    }

    pub fn output(&self) -> Result<String> {
        Ok(self.run_ok()?.stdout_str())
    }
}

pub fn git<I, S>(args: I) -> GitRun<'static>
where
    I: IntoIterator<Item = S>,
    S: AsRef<str>,
{
    GitRun::new(args)
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Signature {
    pub name: String,
    pub email: String,
    pub time: i64,
    /// Offset in minutes east of UTC.
    pub offset: i32,
}

impl Signature {
    pub fn to_raw(&self) -> String {
        format!("{} <{}> {} {}", self.name, self.email, self.time, format_offset(self.offset))
    }

    pub fn parse(s: &str) -> Option<Signature> {
        let lt = s.find('<')?;
        let gt = s[lt..].find('>')? + lt;
        let name = s[..lt].trim_end().to_string();
        let email = s[lt + 1..gt].to_string();
        let rest = s[gt + 1..].trim();
        let mut it = rest.split_whitespace();
        let time = it.next().and_then(|t| t.parse::<i64>().ok()).unwrap_or(0);
        let offset = it.next().and_then(parse_offset).unwrap_or(0);
        Some(Signature { name, email, time, offset })
    }

    pub fn name_email(&self) -> String {
        format!("{} <{}>", self.name, self.email)
    }
}

pub fn format_offset(offset: i32) -> String {
    let sign = if offset < 0 { '-' } else { '+' };
    let a = offset.abs();
    format!("{}{:02}{:02}", sign, a / 60, a % 60)
}

pub fn parse_offset(s: &str) -> Option<i32> {
    let b = s.as_bytes();
    if b.len() != 5 || (b[0] != b'+' && b[0] != b'-') || !b[1..].iter().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let h: i32 = s[1..3].parse().ok()?;
    let m: i32 = s[3..5].parse().ok()?;
    let v = h * 60 + m;
    Some(if b[0] == b'-' { -v } else { v })
}

#[derive(Clone, Debug)]
pub struct Commit {
    pub id: Oid,
    pub tree: Oid,
    pub parents: Vec<Oid>,
    pub author: Signature,
    pub committer: Signature,
    pub author_raw: String,
    pub committer_raw: String,
    /// Extra headers (other than tree/parent/author/committer), raw lines in order.
    pub extra_headers: Vec<(String, String)>,
    pub encoding: Option<String>,
    pub message: Vec<u8>,
}

impl Commit {
    pub fn parse(id: &str, data: &[u8]) -> Commit {
        let mut tree = String::new();
        let mut parents = Vec::new();
        let mut author_raw = String::new();
        let mut committer_raw = String::new();
        let mut extra: Vec<(String, String)> = Vec::new();
        let mut encoding = None;
        let mut pos = 0;
        let mut message = Vec::new();
        while pos < data.len() {
            let end = data[pos..].iter().position(|&c| c == b'\n').map(|p| p + pos).unwrap_or(data.len());
            let line = &data[pos..end];
            pos = end + 1;
            if line.is_empty() {
                message = if pos <= data.len() { data[pos.min(data.len())..].to_vec() } else { Vec::new() };
                break;
            }
            let line = String::from_utf8_lossy(line).into_owned();
            if let Some(rest) = line.strip_prefix(' ') {
                if let Some(last) = extra.last_mut() {
                    last.1.push('\n');
                    last.1.push_str(rest);
                }
                continue;
            }
            let (k, v) = match line.find(' ') {
                Some(i) => (line[..i].to_string(), line[i + 1..].to_string()),
                None => (line.clone(), String::new()),
            };
            match k.as_str() {
                "tree" => tree = v,
                "parent" => parents.push(v),
                "author" => author_raw = v,
                "committer" => committer_raw = v,
                "encoding" => {
                    encoding = Some(v.clone());
                    extra.push((k, v));
                }
                _ => extra.push((k, v)),
            }
        }
        let author = Signature::parse(&author_raw).unwrap_or(Signature { name: String::new(), email: String::new(), time: 0, offset: 0 });
        let committer = Signature::parse(&committer_raw).unwrap_or(Signature { name: String::new(), email: String::new(), time: 0, offset: 0 });
        Commit { id: id.to_string(), tree, parents, author, committer, author_raw, committer_raw, extra_headers: extra, encoding, message }
    }

    pub fn message_str(&self) -> String {
        String::from_utf8_lossy(&self.message).into_owned()
    }

    pub fn parent(&self) -> Option<&Oid> {
        self.parents.first()
    }

    /// First line of the message.
    pub fn summary(&self) -> String {
        let m = self.message_str();
        m.lines().next().unwrap_or("").to_string()
    }
}

/// Data for creating a new commit object.
#[derive(Clone, Debug)]
pub struct NewCommit {
    pub tree: Oid,
    pub parents: Vec<Oid>,
    pub author: Signature,
    pub committer: Signature,
    pub extra_headers: Vec<(String, String)>,
    pub message: Vec<u8>,
}

impl NewCommit {
    pub fn serialize(&self) -> Vec<u8> {
        let mut out = Vec::new();
        out.extend_from_slice(format!("tree {}\n", self.tree).as_bytes());
        for p in &self.parents {
            out.extend_from_slice(format!("parent {}\n", p).as_bytes());
        }
        out.extend_from_slice(format!("author {}\n", self.author.to_raw()).as_bytes());
        out.extend_from_slice(format!("committer {}\n", self.committer.to_raw()).as_bytes());
        for (k, v) in &self.extra_headers {
            out.extend_from_slice(k.as_bytes());
            out.push(b' ');
            out.extend_from_slice(v.replace('\n', "\n ").as_bytes());
            out.push(b'\n');
        }
        out.push(b'\n');
        out.extend_from_slice(&self.message);
        out
    }
}

struct CatFile {
    child: Child,
    stdin: ChildStdin,
    stdout: BufReader<ChildStdout>,
}

impl CatFile {
    fn start(cwd: &Path) -> Result<CatFile> {
        let mut child = Command::new("git")
            .args(["cat-file", "--batch"])
            .current_dir(cwd)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::null())
            .spawn()
            .map_err(|e| Error::new(format!("could not execute `git`: {e}")))?;
        let stdin = child.stdin.take().unwrap();
        let stdout = BufReader::new(child.stdout.take().unwrap());
        Ok(CatFile { child, stdin, stdout })
    }

    fn get(&mut self, spec: &str) -> Result<Option<(String, String, Vec<u8>)>> {
        writeln!(self.stdin, "{spec}").map_err(|e| Error::new(format!("cat-file: {e}")))?;
        self.stdin.flush().ok();
        let mut header = String::new();
        self.stdout.read_line(&mut header).map_err(|e| Error::new(format!("cat-file: {e}")))?;
        let header = header.trim_end_matches('\n');
        if header.ends_with(" missing") || header.ends_with(" ambiguous") || header.is_empty() {
            return Ok(None);
        }
        let parts: Vec<&str> = header.split(' ').collect();
        if parts.len() < 3 {
            return Ok(None);
        }
        let size: usize = parts[2].parse().unwrap_or(0);
        let mut buf = vec![0u8; size + 1];
        self.stdout.read_exact(&mut buf).map_err(|e| Error::new(format!("cat-file: {e}")))?;
        buf.pop();
        Ok(Some((parts[0].to_string(), parts[1].to_string(), buf)))
    }
}

impl Drop for CatFile {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

pub struct ObjectDb {
    cwd: PathBuf,
    catfile: RefCell<Option<CatFile>>,
    commits: RefCell<HashMap<Oid, Rc<Commit>>>,
}

impl ObjectDb {
    pub fn new(cwd: &Path) -> ObjectDb {
        ObjectDb { cwd: cwd.to_path_buf(), catfile: RefCell::new(None), commits: RefCell::new(HashMap::new()) }
    }

    /// Read an object (by any spec acceptable to cat-file). Returns (oid, type, data).
    pub fn read(&self, spec: &str) -> Result<Option<(Oid, String, Vec<u8>)>> {
        let mut cf = self.catfile.borrow_mut();
        if cf.is_none() {
            *cf = Some(CatFile::start(&self.cwd)?);
        }
        cf.as_mut().unwrap().get(spec)
    }

    pub fn commit(&self, oid: &str) -> Result<Rc<Commit>> {
        if let Some(c) = self.commits.borrow().get(oid) {
            return Ok(c.clone());
        }
        match self.read(oid)? {
            Some((id, t, data)) if t == "commit" => {
                let c = Rc::new(Commit::parse(&id, &data));
                self.commits.borrow_mut().insert(id.clone(), c.clone());
                if id != oid {
                    self.commits.borrow_mut().insert(oid.to_string(), c.clone());
                }
                Ok(c)
            }
            _ => Err(Error::new(format!("object `{oid}` is not a commit"))),
        }
    }

    pub fn blob(&self, spec: &str) -> Result<Option<Vec<u8>>> {
        match self.read(spec)? {
            Some((_, t, data)) if t == "blob" => Ok(Some(data)),
            _ => Ok(None),
        }
    }

    pub fn object_type(&self, spec: &str) -> Result<Option<(Oid, String)>> {
        Ok(self.read(spec)?.map(|(o, t, _)| (o, t)))
    }

    pub fn write_blob(&self, data: &[u8]) -> Result<Oid> {
        let out = git(["hash-object", "-w", "--stdin", "--no-filters"]).cwd(&self.cwd).stdin(data).run_ok()?;
        Ok(out.stdout_str().trim().to_string())
    }

    pub fn write_commit(&self, c: &NewCommit) -> Result<Oid> {
        let data = c.serialize();
        let out = git(["hash-object", "-t", "commit", "-w", "--stdin", "--literally"]).cwd(&self.cwd).stdin(&data).run_ok()?;
        let oid = out.stdout_str().trim().to_string();
        Ok(oid)
    }

    /// Write a tree from entries (mode, type, oid, name).
    pub fn write_tree(&self, entries: &[(String, String, Oid, String)]) -> Result<Oid> {
        let mut input = Vec::new();
        for (mode, typ, oid, name) in entries {
            input.extend_from_slice(format!("{mode} {typ} {oid}\t{name}").as_bytes());
            input.push(0);
        }
        let out = git(["mktree", "-z"]).cwd(&self.cwd).stdin(&input).run_ok()?;
        Ok(out.stdout_str().trim().to_string())
    }

    /// Write many blobs at once. Returns oids in order.
    pub fn write_blobs(&self, datas: &[Vec<u8>]) -> Result<Vec<Oid>> {
        if datas.is_empty() {
            return Ok(Vec::new());
        }
        if datas.len() == 1 {
            return Ok(vec![self.write_blob(&datas[0])?]);
        }
        let dir = std::env::temp_dir().join(format!("stg-blobs-{}", std::process::id()));
        std::fs::create_dir_all(&dir)?;
        let mut paths = String::new();
        for (i, d) in datas.iter().enumerate() {
            let p = dir.join(format!("{i}"));
            std::fs::write(&p, d)?;
            paths.push_str(&p.to_string_lossy());
            paths.push('\n');
        }
        let res = git(["hash-object", "-w", "--no-filters", "--stdin-paths"]).cwd(&self.cwd).stdin(paths.as_bytes()).run_ok();
        let _ = std::fs::remove_dir_all(&dir);
        let out = res?;
        Ok(out.stdout_str().lines().map(|l| l.trim().to_string()).collect())
    }
}

pub fn read_to_end<R: Read>(mut r: R) -> Vec<u8> {
    let mut v = Vec::new();
    let _ = r.read_to_end(&mut v);
    v
}
