        let m = self.message_str();
        m.lines().next().unwrap_or("").to_string()
    }
}

/// Data for creating a new commit object.
#[derive(Clone, Debug)]
pub struct NewCommit {
    pub tree: Oid,
    pub parents: Vec<Oid>,
    pub author: Signature,
    pub committer: Signature,
    pub extra_headers: Vec<(String, String)>,
    pub message: Vec<u8>,
}

impl NewCommit {
    pub fn serialize(&self) -> Vec<u8> {
        let mut out = Vec::new();
        out.extend_from_slice(format!("tree {}\n", self.tree).as_bytes());
        for p in &self.parents {
            out.extend_from_slice(format!("parent {}\n", p).as_bytes());
        }
        out.extend_from_slice(format!("author {}\n", self.author.to_raw()).as_bytes());
        out.extend_from_slice(format!("committer {}\n", self.committer.to_raw()).as_bytes());
        for (k, v) in &self.extra_headers {
            out.extend_from_slice(k.as_bytes());
            out.push(b' ');
            out.extend_from_slice(v.replace('\n', "\n ").as_bytes());
            out.push(b'\n');
        }
        out.push(b'\n');
        out.extend_from_slice(&self.message);
        out
    }
}

struct CatFile {
    child: Child,
    stdin: ChildStdin,
    stdout: BufReader<ChildStdout>,
}

impl CatFile {
    fn start(cwd: &Path) -> Result<CatFile> {
        let mut child = Command::new("git")
            .args(["cat-file", "--batch"])
            .current_dir(cwd)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::null())
            .spawn()
            .map_err(|e| Error::new(format!("could not execute `git`: {e}")))?;
        let stdin = child.stdin.take().unwrap();
        let stdout = BufReader::new(child.stdout.take().unwrap());
        Ok(CatFile { child, stdin, stdout })
    }

    fn get(&mut self, spec: &str) -> Result<Option<(String, String, Vec<u8>)>> {
        writeln!(self.stdin, "{spec}").map_err(|e| Error::new(format!("cat-file: {e}")))?;
        self.stdin.flush().ok();
        let mut header = String::new();
        self.stdout.read_line(&mut header).map_err(|e| Error::new(format!("cat-file: {e}")))?;
        let header = header.trim_end_matches('\n');
        if header.ends_with(" missing") || header.ends_with(" ambiguous") || header.is_empty() {
            return Ok(None);
        }
        let parts: Vec<&str> = header.split(' ').collect();
        if parts.len() < 3 {
            return Ok(None);
        }
        let size: usize = parts[2].parse().unwrap_or(0);
        let mut buf = vec![0u8; size + 1];
        self.stdout.read_exact(&mut buf).map_err(|e| Error::new(format!("cat-file: {e}")))?;
        buf.pop();
        Ok(Some((parts[0].to_string(), parts[1].to_string(), buf)))
    }
}

impl Drop for CatFile {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

pub struct ObjectDb {
    cwd: PathBuf,
    catfile: RefCell<Option<CatFile>>,
    commits: RefCell<HashMap<Oid, Rc<Commit>>>,
}

impl ObjectDb {
    pub fn new(cwd: &Path) -> ObjectDb {
        ObjectDb { cwd: cwd.to_path_buf(), catfile: RefCell::new(None), commits: RefCell::new(HashMap::new()) }
    }

    /// Read an object (by any spec acceptable to cat-file). Returns (oid, type, data).
    pub fn read(&self, spec: &str) -> Result<Option<(Oid, String, Vec<u8>)>> {
        let mut cf = self.catfile.borrow_mut();
        if cf.is_none() {
            *cf = Some(CatFile::start(&self.cwd)?);
        }
        cf.as_mut().unwrap().get(spec)
    }

    pub fn commit(&self, oid: &str) -> Result<Rc<Commit>> {
        if let Some(c) = self.commits.borrow().get(oid) {
            return Ok(c.clone());
        }
        match self.read(oid)? {
            Some((id, t, data)) if t == "commit" => {
                let c = Rc::new(Commit::parse(&id, &data));
                self.commits.borrow_mut().insert(id.clone(), c.clone());
                if id != oid {
                    self.commits.borrow_mut().insert(oid.to_string(), c.clone());
                }
                Ok(c)
            }
            _ => Err(Error::new(format!("object `{oid}` is not a commit"))),
        }
    }

    pub fn blob(&self, spec: &str) -> Result<Option<Vec<u8>>> {
        match self.read(spec)? {
            Some((_, t, data)) if t == "blob" => Ok(Some(data)),
            _ => Ok(None),
        }
    }

    pub fn object_type(&self, spec: &str) -> Result<Option<(Oid, String)>> {
        Ok(self.read(spec)?.map(|(o, t, _)| (o, t)))
    }

    pub fn write_blob(&self, data: &[u8]) -> Result<Oid> {
        let out = git(["hash-object", "-w", "--stdin", "--no-filters"]).cwd(&self.cwd).stdin(data).run_ok()?;
        Ok(out.stdout_str().trim().to_string())
    }

    pub fn write_commit(&self, c: &NewCommit) -> Result<Oid> {
        let data = c.serialize();
        let out = git(["hash-object", "-t", "commit", "-w", "--stdin", "--literally"]).cwd(&self.cwd).stdin(&data).run_ok()?;
        let oid = out.stdout_str().trim().to_string();
        Ok(oid)
    }

    /// Write a tree from entries (mode, type, oid, name).
    pub fn write_tree(&self, entries: &[(String, String, Oid, String)]) -> Result<Oid> {
        let mut input = Vec::new();
        for (mode, typ, oid, name) in entries {
            input.extend_from_slice(format!("{mode} {typ} {oid}\t{name}").as_bytes());
            input.push(0);
        }
        let out = git(["mktree", "-z"]).cwd(&self.cwd).stdin(&input).run_ok()?;
        Ok(out.stdout_str().trim().to_string())
    }

    /// Write many blobs at once. Returns oids in order.
    pub fn write_blobs(&self, datas: &[Vec<u8>]) -> Result<Vec<Oid>> {
        if datas.is_empty() {
            return Ok(Vec::new());
        }
        if datas.len() == 1 {
            return Ok(vec![self.write_blob(&datas[0])?]);
        }
        let dir = std::env::temp_dir().join(format!("stg-blobs-{}", std::process::id()));
        std::fs::create_dir_all(&dir)?;
        let mut paths = String::new();
        for (i, d) in datas.iter().enumerate() {
            let p = dir.join(format!("{i}"));
            std::fs::write(&p, d)?;
            paths.push_str(&p.to_string_lossy());
            paths.push('\n');
        }
        let res = git(["hash-object", "-w", "--no-filters", "--stdin-paths"]).cwd(&self.cwd).stdin(paths.as_bytes()).run_ok();
        let _ = std::fs::remove_dir_all(&dir);
        let out = res?;
        Ok(out.stdout_str().lines().map(|l| l.trim().to_string()).collect())
    }
}

pub fn read_to_end<R: Read>(mut r: R) -> Vec<u8> {
    let mut v = Vec::new();
    let _ = r.read_to_end(&mut v);
    v
}
