use crate::git::git;

#[derive(Default, Clone)]
pub struct Config {
    entries: Vec<(String, Option<String>)>,
}

/// Normalize a config key: section and variable name are case-insensitive,
/// subsection is case-sensitive.
pub fn normalize_key(key: &str) -> String {
    let first = key.find('.');
    let last = key.rfind('.');
    match (first, last) {
        (Some(f), Some(l)) if f != l => {
            format!("{}{}{}", key[..f].to_lowercase(), &key[f..l], key[l..].to_lowercase())
        }
        _ => key.to_lowercase(),
    }
}

impl Config {
    pub fn load() -> Config {
        let out = git(["config", "-z", "--list"]).run();
        let mut entries = Vec::new();
        if let Ok(out) = out {
            if out.ok() {
                for item in out.stdout.split(|&b| b == 0) {
                    if item.is_empty() {
                        continue;
                    }
                    let s = String::from_utf8_lossy(item).into_owned();
                    match s.find('\n') {
                        Some(i) => entries.push((normalize_key(&s[..i]), Some(s[i + 1..].to_string()))),
                        None => entries.push((normalize_key(&s), None)),
                    }
                }
            }
        }
        Config { entries }
    }

    pub fn get(&self, key: &str) -> Option<String> {
        let k = normalize_key(key);
        self.entries.iter().rev().find(|(ek, _)| *ek == k).map(|(_, v)| v.clone().unwrap_or_default())
    }

    pub fn get_raw(&self, key: &str) -> Option<Option<String>> {
        let k = normalize_key(key);
        self.entries.iter().rev().find(|(ek, _)| *ek == k).map(|(_, v)| v.clone())
    }

    pub fn get_all(&self, key: &str) -> Vec<String> {
        let k = normalize_key(key);
        self.entries.iter().filter(|(ek, _)| *ek == k).map(|(_, v)| v.clone().unwrap_or_default()).collect()
    }

    pub fn get_bool(&self, key: &str) -> Option<bool> {
        match self.get_raw(key)? {
            None => Some(true),
            Some(v) => parse_bool(&v),
        }
    }

    pub fn get_i64(&self, key: &str) -> Option<i64> {
        let v = self.get(key)?;
        parse_int(&v)
    }

    /// All entries whose key starts with the given (normalized) prefix.
    pub fn entries_with_prefix(&self, prefix: &str) -> Vec<(String, String)> {
        let p = prefix.to_lowercase();
        self.entries
            .iter()
            .filter(|(k, _)| k.to_lowercase().starts_with(&p))
            .map(|(k, v)| (k.clone(), v.clone().unwrap_or_default()))
            .collect()
    }

    pub fn all(&self) -> &[(String, Option<String>)] {
        &self.entries
    }
}

pub fn parse_bool(v: &str) -> Option<bool> {
    match v.to_lowercase().as_str() {
        "true" | "yes" | "on" | "1" => Some(true),
        "false" | "no" | "off" | "0" | "" => Some(false),
        other => parse_int(other).map(|i| i != 0),
    }
}

pub fn parse_int(v: &str) -> Option<i64> {
    let v = v.trim();
    let (num, mult) = match v.chars().last() {
        Some('k') | Some('K') => (&v[..v.len() - 1], 1024),
        Some('m') | Some('M') => (&v[..v.len() - 1], 1024 * 1024),
        Some('g') | Some('G') => (&v[..v.len() - 1], 1024 * 1024 * 1024),
        _ => (v, 1),
    };
    num.parse::<i64>().ok().map(|n| n * mult)
}
