cd /workspace/src && cat > timefmt.rs <<'EOF'
//! Date/time parsing and formatting without external crates.

use std::time::{SystemTime, UNIX_EPOCH};

#[repr(C)]
struct Tm {
    tm_sec: i32,
    tm_min: i32,
    tm_hour: i32,
    tm_mday: i32,
    tm_mon: i32,
    tm_year: i32,
    tm_wday: i32,
    tm_yday: i32,
    tm_isdst: i32,
    tm_gmtoff: i64,
    tm_zone: *const u8,
}

extern "C" {
    fn localtime_r(t: *const i64, tm: *mut Tm) -> *mut Tm;
    fn tzset();
}

pub fn now() -> i64 {
    SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_secs() as i64).unwrap_or(0)
}

/// Local UTC offset in minutes for the given unix time.
pub fn local_offset(t: i64) -> i32 {
    unsafe {
        tzset();
        let mut tm: Tm = std::mem::zeroed();
        if localtime_r(&t, &mut tm).is_null() {
            return 0;
        }
        (tm.tm_gmtoff / 60) as i32
    }
}

pub fn days_from_civil(y: i64, m: i64, d: i64) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = (m + 9) % 12;
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

pub fn civil_from_days(z: i64) -> (i64, i64, i64) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    (if m <= 2 { y + 1 } else { y }, m, d)
}

pub struct Broken {
    pub year: i64,
    pub month: i64,
    pub day: i64,
    pub hour: i64,
    pub min: i64,
    pub sec: i64,
    pub wday: i64,
}

pub fn broken_down(t: i64, offset: i32) -> Broken {
    let lt = t + offset as i64 * 60;
    let days = lt.div_euclid(86400);
    let secs = lt.rem_euclid(86400);
    let (y, m, d) = civil_from_days(days);
    let wday = (days + 4).rem_euclid(7);
    Broken { year: y, month: m, day: d, hour: secs / 3600, min: (secs / 60) % 60, sec: secs % 60, wday }
}

pub const WDAYS: [&str; 7] = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
pub const MONTHS: [&str; 12] = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

pub fn fmt_offset(offset: i32) -> String {
    crate::git::format_offset(offset)
}

/// "2005-04-08 00:14:13 +0200"
pub fn format_iso(t: i64, offset: i32) -> String {
    let b = broken_down(t, offset);
    format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02} {}", b.year, b.month, b.day, b.hour, b.min, b.sec, fmt_offset(offset))
}

/// "Fri, 8 Apr 2005 00:14:13 +0200"
pub fn format_rfc2822(t: i64, offset: i32) -> String {
    let b = broken_down(t, offset);
    format!(
        "{}, {} {} {} {:02}:{:02}:{:02} {}",
        WDAYS[b.wday as usize],
        b.day,
        MONTHS[(b.month - 1) as usize],
        b.year,
        b.hour,
        b.min,
        b.sec,
        fmt_offset(offset)
    )
}

/// git default format: "Fri Apr 8 00:14:13 2005 +0200"
pub fn format_default(t: i64, offset: i32) -> String {
    let b = broken_down(t, offset);
    format!(
        "{} {} {} {:02}:{:02}:{:02} {} {}",
        WDAYS[b.wday as usize],
        MONTHS[(b.month - 1) as usize],
        b.day,
        b.hour,
        b.min,
        b.sec,
        b.year,
        fmt_offset(offset)
    )
}

fn parse_num(s: &str, digits: Option<usize>) -> Option<i64> {
    if s.is_empty() || !s.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    if let Some(d) = digits {
        if s.len() != d {
            return None;
        }
    }
    s.parse().ok()
}

fn parse_hms(s: &str) -> Option<(i64, i64, i64)> {
    let p: Vec<&str> = s.split(':').collect();
    if p.len() != 3 {
        return None;
    }
    let h = parse_num(p[0], None)?;
    let m = parse_num(p[1], None)?;
    let sec = parse_num(p[2], None)?;
    if h > 23 || m > 59 || sec > 60 || p[0].len() > 2 || p[1].len() != 2 || p[2].len() != 2 {
        return None;
    }
    Some((h, m, sec))
}

fn parse_ymd(s: &str) -> Option<(i64, i64, i64)> {
    let p: Vec<&str> = s.split('-').collect();
    if p.len() != 3 {
        return None;
    }
    let y = parse_num(p[0], Some(4))?;
    let m = parse_num(p[1], Some(2))?;
    let d = parse_num(p[2], Some(2))?;
    if !(1..=12).contains(&m) || !(1..=31).contains(&d) {
        return None;
    }
    Some((y, m, d))
}

/// Parse "+HHMM"/"-HHMM" or "+HH:MM" (when colon allowed).
fn parse_tz(s: &str, colon: bool) -> Option<i32> {
    if colon {
        let b = s.as_bytes();
        if b.len() == 6 && b[3] == b':' && (b[0] == b'+' || b[0] == b'-') {
            let h: i32 = parse_num(&s[1..3], Some(2))? as i32;
            let m: i32 = parse_num(&s[4..6], Some(2))? as i32;
            let v = h * 60 + m;
            return Some(if b[0] == b'-' { -v } else { v });
        }
        return None;
    }
    crate::git::parse_offset(s)
}

fn month_from_name(s: &str) -> Option<i64> {
    MONTHS.iter().position(|m| m.eq_ignore_ascii_case(s)).map(|i| i as i64 + 1)
}

fn mk(y: i64, mo: i64, d: i64, h: i64, mi: i64, s: i64, offset: i32) -> (i64, i32) {
    let days = days_from_civil(y, mo, d);
    let t = days * 86400 + h * 3600 + mi * 60 + s - offset as i64 * 60;
    (t, offset)
}

/// Parse a date string the way StGit does. Returns (unix time, offset minutes).
pub fn parse_date(input: &str) -> Option<(i64, i32)> {
    let s = input.trim();
    if s.is_empty() {
        return None;
    }
    if s == "now" {
        let t = now();
        return Some((t, local_offset(t)));
    }
    // raw: "<secs> <tz>" or "<secs>"
    {
        let parts: Vec<&str> = s.split_whitespace().collect();
        if parts.len() == 1 {
            if let Some(t) = parse_num(parts[0], None) {
                if parts[0].len() <= 12 {
                    return Some((t, 0));
                }
            }
        }
        if parts.len() == 2 {
            if let (Some(t), Some(off)) = (parse_num(parts[0], None), parse_tz(parts[1], false)) {
                return Some((t, off));
            }
        }
    }
    // relative: "N unit(s) ago"
    {
        let parts: Vec<&str> = s.split_whitespace().collect();
        if parts.len() == 3 && parts[2] == "ago" {
            if let Some(n) = parse_num(parts[0], None) {
                let unit = parts[1].trim_end_matches('s');
                let t = now();
                let res = match unit {
                    "second" => Some(t - n),
                    "minute" => Some(t - n * 60),
                    "hour" => Some(t - n * 3600),
                    "day" => Some(t - n * 86400),
                    "week" => Some(t - n * 7 * 86400),
                    "month" | "year" => {
                        let off = local_offset(t);
                        let b = broken_down(t, off);
                        let total = b.year * 12 + (b.month - 1) - if unit == "month" { n } else { n * 12 };
                        let y = total.div_euclid(12);
                        let m = total.rem_euclid(12) + 1;
                        let (tt, _) = mk(y, m, b.day, b.hour, b.min, b.sec, off);
                        Some(tt)
                    }
                    _ => None,
                };
                if let Some(rt) = res {
                    return Some((rt, local_offset(rt)));
                }
            }
        }
    }
    // ISO strict: YYYY-MM-DDTHH:MM:SS[+HH:MM]
    if let Some((date, rest)) = s.split_once('T') {
        if let Some((y, m, d)) = parse_ymd(date) {
            if rest.len() >= 8 {
                if let Some((h, mi, se)) = parse_hms(&rest[..8]) {
                    let tz = &rest[8..];
                    if tz.is_empty() {
                        let (t, _) = mk(y, m, d, h, mi, se, 0);
                        let off = local_offset(t);
                        return Some(mk(y, m, d, h, mi, se, off));
                    }
                    if let Some(off) = parse_tz(tz, true) {
                        return Some(mk(y, m, d, h, mi, se, off));
                    }
                }
            }
        }
        return None;
    }
    let parts: Vec<&str> = s.split_whitespace().collect();
    // ISO: YYYY-MM-DD [HH:MM:SS[+HHMM]] [+HHMM]
    if let Some((y, m, d)) = parse_ymd(parts[0]) {
        if parts.len() == 1 {
            return Some(mk(y, m, d, 0, 0, 0, 0));
        }
        let tpart = parts[1];
        let (hms, tzinline) = if tpart.len() > 8 { (&tpart[..8], Some(&tpart[8..])) } else { (tpart, None) };
        let (h, mi, se) = parse_hms(hms)?;
        match (tzinline, parts.len()) {
            (None, 2) => {
                let (t, _) = mk(y, m, d, h, mi, se, 0);
                let off = local_offset(t);
                return Some(mk(y, m, d, h, mi, se, off));
            }
            (None, 3) => {
                let off = parse_tz(parts[2], false)?;
                return Some(mk(y, m, d, h, mi, se, off));
            }
            (Some(tz), 2) => {
                let off = parse_tz(tz, false)?;
                return Some(mk(y, m, d, h, mi, se, off));
            }
            _ => return None,
        }
    }
    // RFC 2822: [Wdy,] DD Mon YYYY HH:MM:SS (+HHMM|GMT)
    {
        let mut p = parts.clone();
        if let Some(first) = p.first() {
            if first.ends_with(',') {
                let wd = &first[..first.len() - 1];
                if WDAYS.iter().any(|w| w.eq_ignore_ascii_case(wd)) {
                    p.remove(0);
                } else {
                    return None;
                }
            }
        }
        if p.len() == 5 || p.len() == 4 {
            if let (Some(d), Some(mo), Some(y)) = (parse_num(p[0], None), month_from_name(p[1]), parse_num(p[2], Some(4))) {
                if p[0].len() <= 2 {
                    if let Some((h, mi, se)) = parse_hms(p[3]) {
                        if p.len() == 4 {
                            return Some(mk(y, mo, d, h, mi, se, 0));
                        }
                        let off = if p[4].eq_ignore_ascii_case("GMT") || p[4].eq_ignore_ascii_case("UT") || p[4].eq_ignore_ascii_case("Z") {
                            Some(0)
                        } else {
                            parse_tz(p[4], false)
                        };
                        if let Some(off) = off {
                            return Some(mk(y, mo, d, h, mi, se, off));
                        }
                    }
                }
            }
        }
    }
    // git default: Wdy Mon DD HH:MM:SS YYYY [+HHMM]
    if parts.len() == 5 || parts.len() == 6 {
        if WDAYS.iter().any(|w| w.eq_ignore_ascii_case(parts[0])) {
            if let (Some(mo), Some(d), Some((h, mi, se)), Some(y)) =
                (month_from_name(parts[1]), parse_num(parts[2], None), parse_hms(parts[3]), parse_num(parts[4], Some(4)))
            {
                if parts.len() == 5 {
                    let (t, _) = mk(y, mo, d, h, mi, se, 0);
                    let off = local_offset(t);
                    return Some(mk(y, mo, d, h, mi, se, off));
                }
                let off = parse_tz(parts[5], false)?;
                return Some(mk(y, mo, d, h, mi, se, off));
            }
        }
    }
    None
}
