//! Repository context: paths, config, objects, refs and index helpers.

use crate::config::Config;
use crate::error::{Error, Result};
use crate::git::{git, Commit, GitRun, NewCommit, ObjectDb, Oid, Signature};
use crate::timefmt;
use std::path::{Path, PathBuf};
use std::rc::Rc;

pub struct Repo {
    pub git_dir: PathBuf,
    pub common_dir: PathBuf,
    pub work_dir: Option<PathBuf>,
    pub prefix: String,
    pub cwd: PathBuf,
    pub config: Config,
    pub odb: ObjectDb,
    pub bare: bool,
}

impl Repo {
    pub fn open() -> Result<Repo> {
        let cwd = std::env::current_dir().map_err(|e| Error::new(format!("{e}")))?;
        let out = git(["rev-parse", "--absolute-git-dir", "--git-common-dir", "--is-bare-repository", "--show-prefix"]).run()?;
        if !out.ok() {
            return Err(Error::new("Could not find a git repository in '.' or in any of its parents"));
        }
        let s = out.stdout_str();
        let lines: Vec<&str> = s.lines().collect();
        let git_dir = PathBuf::from(lines.first().copied().unwrap_or(".git"));
        let common = lines.get(1).copied().unwrap_or(".git");
        let common_dir = if Path::new(common).is_absolute() { PathBuf::from(common) } else { cwd.join(common) };
        let bare = lines.get(2).copied() == Some("true");
        let prefix = lines.get(3).copied().unwrap_or("").to_string();
        let work_dir = if bare {
            None
        } else {
            let o = git(["rev-parse", "--show-toplevel"]).run()?;
            if o.ok() {
                Some(PathBuf::from(o.stdout_str().trim_end_matches('\n')))
            } else {
                None
            }
        };
        let config = Config::load();
        let odb = ObjectDb::new(&cwd);
        Ok(Repo { git_dir, common_dir, work_dir, prefix, cwd, config, odb, bare })
    }

    pub fn work_dir(&self) -> Result<&Path> {
        self.work_dir.as_deref().ok_or_else(|| Error::new("this operation must be run in a work tree"))
    }

    /// Run git from the top of the work tree (or cwd if bare).
    pub fn git<I, S>(&self, args: I) -> GitRun<'static>
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        let g = git(args);
        match &self.work_dir {
            Some(w) => g.cwd(w),
            None => g,
        }
    }

    pub fn commit(&self, oid: &str) -> Result<Rc<Commit>> {
        self.odb.commit(oid)
    }

    pub fn write_commit(&self, c: &NewCommit) -> Result<Oid> {
        self.odb.write_commit(c)
    }

    // ---------------------------------------------------------------- refs

    pub fn resolve_ref(&self, name: &str) -> Option<Oid> {
        let out = git(["rev-parse", "--verify", "-q", name]).run().ok()?;
        if out.ok() {
            Some(out.stdout_str().trim().to_string())
        } else {
            None
        }
    }

    pub fn ref_exists(&self, name: &str) -> bool {
        git(["show-ref", "--verify", "-q", name]).run().map(|o| o.ok()).unwrap_or(false)
    }

    pub fn update_ref(&self, name: &str, oid: &str, msg: &str) -> Result<()> {
        git(["update-ref", "-m", msg, name, oid]).run_ok()?;
        Ok(())
    }

    pub fn update_ref_no_log(&self, name: &str, oid: &str) -> Result<()> {
        git(["update-ref", name, oid]).run_ok()?;
        Ok(())
    }

    pub fn delete_ref(&self, name: &str) -> Result<()> {
        git(["update-ref", "-d", name]).run_ok()?;
        Ok(())
    }

    /// List refs under a prefix: (refname, oid)
    pub fn list_refs(&self, prefix: &str) -> Vec<(String, Oid)> {
        let out = git(["for-each-ref", "--format=%(refname) %(objectname)", prefix]).run();
        let mut v = Vec::new();
        if let Ok(o) = out {
            for l in o.stdout_str().lines() {
                if let Some((r, oid)) = l.split_once(' ') {
                    v.push((r.to_string(), oid.to_string()));
                }
            }
        }
        v
    }

    /// Name of the current branch (without refs/heads/), or None if detached.
    pub fn head_branch(&self) -> Option<String> {
        let out = git(["symbolic-ref", "-q", "HEAD"]).run().ok()?;
        if !out.ok() {
            return None;
        }
        let s = out.stdout_str().trim().to_string();
        s.strip_prefix("refs/heads/").map(|x| x.to_string())
    }

    pub fn head_oid(&self) -> Option<Oid> {
        self.resolve_ref("HEAD")
    }

    /// Resolve a revision spec to a commit oid.
    pub fn rev_parse_commit(&self, spec: &str) -> Option<Oid> {
        let s = format!("{spec}^{{commit}}");
        let out = git(["rev-parse", "--verify", "-q", "--end-of-options", &s]).run().ok()?;
        if out.ok() {
            Some(out.stdout_str().trim().to_string())
        } else {
            None
        }
    }

    pub fn rev_parse(&self, spec: &str) -> Option<Oid> {
        let out = git(["rev-parse", "--verify", "-q", "--end-of-options", spec]).run().ok()?;
        if out.ok() {
            Some(out.stdout_str().trim().to_string())
        } else {
            None
        }
    }

    // ---------------------------------------------------------- signatures

    pub fn author(&self) -> Result<Signature> {
        let name = std::env::var("GIT_AUTHOR_NAME").ok().or_else(|| self.config.get("author.name")).or_else(|| self.config.get("user.name"));
        let email = std::env::var("GIT_AUTHOR_EMAIL")
            .ok()
            .or_else(|| self.config.get("author.email"))
            .or_else(|| self.config.get("user.email"))
            .or_else(|| std::env::var("EMAIL").ok());
        let (name, email) = match (name, email) {
            (Some(n), Some(e)) => (n, e),
            _ => return Err(Error::new("author identity unknown; please configure `user.name` and `user.email`.")),
        };
        let (time, offset) = env_date("GIT_AUTHOR_DATE");
        Ok(Signature { name, email, time, offset })
    }

    pub fn committer(&self) -> Result<Signature> {
        let name = std::env::var("GIT_COMMITTER_NAME")
            .ok()
            .or_else(|| self.config.get("committer.name"))
            .or_else(|| self.config.get("user.name"));
        let email = std::env::var("GIT_COMMITTER_EMAIL")
