    pub fn worktree_differs(&self) -> Result<bool> {
        let out = self.git(["diff-files", "--quiet"]).run()?;
        Ok(!out.ok())
    }

    /// Paths with unmerged (conflict) entries in the index.
    pub fn conflicts(&self) -> Result<Vec<String>> {
