                let mut st = Stack {
                    repo,
                    branch: branch.to_string(),
                    branch_ref,
                    stack_ref,
                    state: StackState::new_empty(&branch_head),
                    branch_head,
                    state_oid: None,
                };
                let state = st.state.clone();
                st.commit_state(state, "initialize")?;
                Ok(st)
            }
        }
    }

    pub fn is_initialized(&self) -> bool {
        self.state_oid.is_some()
    }

    pub fn applied(&self) -> &Vec<String> {
        &self.state.applied
    }
    pub fn unapplied(&self) -> &Vec<String> {
        &self.state.unapplied
    }
    pub fn hidden(&self) -> &Vec<String> {
        &self.state.hidden
    }

    pub fn patch_commit(&self, name: &str) -> Result<Rc<Commit>> {
        let oid = self.state.patches.get(name).ok_or_else(|| Error::new(format!("patch `{name}` does not exist")))?;
        self.repo.commit(oid)
    }

    pub fn patch_oid(&self, name: &str) -> Option<&Oid> {
        self.state.patches.get(name)
    }

    pub fn head_commit(&self) -> Result<Rc<Commit>> {
        self.repo.commit(&self.state.head)
    }

    /// The stack base: parent of the first applied patch, or head if none applied.
    pub fn base(&self) -> Result<Oid> {
        match self.state.applied.first() {
            Some(p) => {
                let c = self.patch_commit(p)?;
                Ok(c.parents.first().cloned().unwrap_or_else(|| c.id.clone()))
            }
            None => Ok(self.state.head.clone()),
        }
    }

    pub fn is_head_top(&self) -> bool {
        self.state.head == self.branch_head
    }

    pub fn check_head_top(&self) -> Result<()> {
        if !self.is_head_top() {
            return Err(Error::new(
                "HEAD and stack top are not the same. This can happen if you modify the branch with git. See `stg repair --help` for next steps to take.",
            ));
        }
        Ok(())
    }

    /// Text of a patch metadata blob in the stack state tree.
    pub fn patch_meta(repo: &Repo, commit: &Commit) -> Result<String> {
        let bottom = match commit.parents.first() {
            Some(p) => repo.commit(p)?.tree.clone(),
            None => commit.tree.clone(),
        };
        let mut s = String::new();
        s.push_str(&format!("Bottom: {}\n", bottom));
        s.push_str(&format!("Top:    {}\n", commit.tree));
        s.push_str(&format!("Author: {}\n", commit.author.name_email()));
        s.push_str(&format!("Date:   {}\n", timefmt::format_iso(commit.committer.time, commit.committer.offset)));
        s.push('\n');
        s.push_str(&commit.message_str());
        Ok(s)
    }

    /// Write a new state commit for `state` with the given message and update the stack ref.
    /// The `prev` field of `state` is set to the current state commit.
    pub fn commit_state(&mut self, mut state: StackState, message: &str) -> Result<Oid> {
        let repo = self.repo;
        state.prev = self.state_oid.clone();
        let prev_state = if self.state_oid.is_some() { Some(self.state.clone()) } else { None };
        let oid = write_state_commit(repo, &state, prev_state.as_ref(), self.state_oid.as_deref(), message)?;
        repo.update_ref_no_log(&self.stack_ref, &oid)?;
        self.state = state;
        self.state_oid = Some(oid.clone());
        Ok(oid)
    }
}

/// Create the state tree and commits. Returns the state commit oid.
pub fn write_state_commit(
    repo: &Repo,
    state: &StackState,
    prev_state: Option<&StackState>,
    prev_oid: Option<&str>,
    message: &str,
) -> Result<Oid> {
    // Build patches subtree
    let names: Vec<&String> = state.patches.keys().collect();
    let mut metas = Vec::new();
    for n in &names {
        let c = repo.commit(&state.patches[*n])?;
        metas.push(Stack::patch_meta(repo, &c)?.into_bytes());
    }
    let mut blobs = repo.odb.write_blobs(&metas)?;
    let json_blob = repo.odb.write_blob(state.to_json().as_bytes())?;
    let mut entries = Vec::new();
    if !names.is_empty() {
        let pentries: Vec<(String, String, Oid, String)> = names
            .iter()
            .zip(blobs.drain(..))
            .map(|(n, b)| ("100644".to_string(), "blob".to_string(), b, n.to_string()))
            .collect();
        let ptree = repo.odb.write_tree(&pentries)?;
        entries.push(("040000".to_string(), "tree".to_string(), ptree, "patches".to_string()));
    }
    entries.push(("100644".to_string(), "blob".to_string(), json_blob, "stack.json".to_string()));
    let tree = repo.odb.write_tree(&entries)?;

    let author = repo.author()?;
    let committer = repo.committer()?;

    let simplified_parent = match prev_oid {
        Some(p) => repo.commit(p)?.parents.first().cloned(),
        None => None,
    };
    let simplified = NewCommit {
        tree: tree.clone(),
        parents: simplified_parent.into_iter().collect(),
        author: author.clone(),
        committer: committer.clone(),
        extra_headers: vec![],
        message: message.as_bytes().to_vec(),
    };
    let simplified_oid = repo.write_commit(&simplified)?;

    let mut parents = vec![simplified_oid];
    let prev_commits: std::collections::HashSet<&String> = match prev_state {
        Some(p) => p.patches.values().collect(),
        None => Default::default(),
    };
    let mut candidates: Vec<&String> = vec![&state.head];
    for n in state.unapplied.iter().chain(state.hidden.iter()) {
        if let Some(o) = state.patches.get(n) {
            candidates.push(o);
        }
    }
    for c in candidates {
        if !prev_commits.contains(c) && !parents.contains(c) {
            parents.push(c.clone());
        }
    }
    if let Some(p) = prev_oid {
        parents.push(p.to_string());
    }
    let commit = NewCommit { tree, parents, author, committer, extra_headers: vec![], message: message.as_bytes().to_vec() };
    repo.write_commit(&commit)
}
