//! Patch name validation and generation.

/// Validate a patch name. Returns Err(reason) on failure.
pub fn check(name: &str) -> Result<(), String> {
    if name.is_empty() {
        return Err("patch name may not be empty".to_string());
    }
    if name == "@" {
        return Err("patch name may not be '@'".to_string());
    }
    if name == "{base}" {
        return Err("patch name may not be '{base}'".to_string());
    }
    if name.starts_with('.') {
        return Err("patch name may not start with '.'".to_string());
    }
    let chars: Vec<char> = name.chars().collect();
    for (i, &c) in chars.iter().enumerate() {
        let next = chars.get(i + 1).copied();
        let reason = match c {
            '/' => Some("patch name may not contain '/'".to_string()),
            c if c.is_whitespace() => Some("patch name may not contain whitespace".to_string()),
            c if c.is_control() => Some("patch name may not contain control characters".to_string()),
            '~' | '^' | ':' | '?' | '*' | '[' | '\\' => Some(format!("patch name may not contain '{c}'")),
            '.' if next == Some('.') => Some("patch name may not contain '..'".to_string()),
            '@' if next == Some('{') => Some("patch name may not contain '@{'".to_string()),
            _ => None,
        };
        if let Some(r) = reason {
            return Err(r);
        }
    }
    if name.ends_with(".lock") {
        return Err("patch name may not end with '.lock'".to_string());
    }
    if name.ends_with('.') {
        return Err("patch name may not end with '.'".to_string());
    }
    Ok(())
}

/// Parse a user-supplied patch name (handles leading backslash escape).
pub fn parse_user(raw: &str) -> Result<String, String> {
    let name = raw.strip_prefix('\\').unwrap_or(raw);
    match check(name) {
        Ok(()) => Ok(name.to_string()),
        Err(reason) => Err(format!("invalid patch name `{name}`: {reason}")),
    }
}

fn collapse(s: &str, ch: char) -> String {
    let mut out = String::with_capacity(s.len());
    let mut prev: Option<char> = None;
    for c in s.chars() {
        if c == ch && prev == Some(ch) {
            continue;
        }
        out.push(c);
        prev = Some(c);
    }
    out
}

fn sanitize_word(w: &str) -> String {
    let w = collapse(w, '.');
    let w = collapse(&w, '-');
    let w = w.replace(".-", ".");
    collapse(&w, '.')
}

fn sanitize(s: &str) -> String {
    let mut s = s.replace("-.", "-");
    s = collapse(&s, '.');
    while let Some(x) = s.strip_suffix(".lock") {
        s = x.to_string();
    }
    let s = s.trim_start_matches('.');
    let mut s = s.trim_end_matches('.').to_string();
    while let Some(x) = s.strip_suffix(".lock") {
        s = x.to_string();
    }
    s
}

/// Generate a candidate patch name from a commit message.
pub fn make_candidate(msg: &str, len_limit: Option<usize>) -> String {
    let trimmed = msg.trim();
    let line = trimmed.lines().next().unwrap_or("").to_lowercase();
    let mut words: Vec<String> = Vec::new();
    for w in line.split_whitespace() {
        let mapped: String = w.chars().map(|c| if c.is_alphanumeric() || c == '_' || c == '.' || c == '-' { c } else { '-' }).collect();
        let s = sanitize_word(&mapped);
        if !s.is_empty() {
            words.push(s);
        }
    }
    let joined = words.join("-");
    let s = sanitize(&joined);
    let s = collapse(&s, '-');
    let s = s.trim_matches('-');
    let parts: Vec<&str> = s.split('-').collect();
    let mut out = parts.first().map(|p| p.to_string()).unwrap_or_default();
    if let Some(limit) = len_limit {
        for p in &parts[1..] {
            if out.chars().count() + 1 + p.chars().count() > limit {
                break;
            }
            out.push('-');
            out.push_str(p);
        }
    } else {
        out = s.to_string();
    }
    let out = sanitize(&out);
    let out = out.trim_matches('-').to_string();
    if out.is_empty() {
        "patch".to_string()
    } else {
        out
    }
}

/// Make a unique patch name not in `taken`.
pub fn uniquify(candidate: &str, taken: &dyn Fn(&str) -> bool) -> String {
    if !taken(candidate) {
        return candidate.to_string();
    }
    let (base, mut n) = match candidate.rfind('-') {
        Some(i) if i + 1 < candidate.len() && candidate[i + 1..].chars().all(|c| c.is_ascii_digit()) => {
            let num: u64 = candidate[i + 1..].parse().unwrap_or(0);
            (candidate[..i].to_string(), num + 1)
        }
        _ => (candidate.to_string(), 1),
    };
    loop {
        let name = format!("{base}-{n}");
        if !taken(&name) {
            return name;
        }
        n += 1;
    }
}

pub fn make(msg: &str, len_limit: Option<usize>, taken: &dyn Fn(&str) -> bool) -> String {
    uniquify(&make_candidate(msg, len_limit), taken)
}

// ------------------------------------------------------------ similarity

pub fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let (la, lb) = (a.len(), b.len());
    if la == 0 && lb == 0 {
        return 1.0;
    }
    if la == 0 || lb == 0 {
        return 0.0;
    }
    if la == 1 && lb == 1 {
        return if a[0] == b[0] { 1.0 } else { 0.0 };
    }
    let w = (la.max(lb) / 2).saturating_sub(1);
    let mut fa = vec![false; la];
    let mut fb = vec![false; lb];
    let mut m = 0usize;
    for (i, c) in a.iter().enumerate() {
        let lo = if i > w { i - w } else { 0 };
        let hi = (i + w + 1).min(lb);
        for j in lo..hi {
            if !fb[j] && b[j] == *c {
                fa[i] = true;
                fb[j] = true;
                m += 1;
                break;
            }
        }
    }
    if m == 0 {
        return 0.0;
    }
    let mut t = 0usize;
    let mut j = 0usize;
    for i in 0..la {
        if fa[i] {
            while !fb[j] {
                j += 1;
            }
            if a[i] != b[j] {
                t += 1;
            }
            j += 1;
        }
    }
    let m = m as f64;
    let t = t as f64 / 2.0;
    (m / la as f64 + m / lb as f64 + (m - t) / m) / 3.0
}

pub fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    let p = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).take(4).count();
    j + 0.1 * p as f64 * (1.0 - j)
}

/// Format a list of names like "`a`, `b`, and `c`".
pub fn conjoin(names: &[String]) -> String {
    let q: Vec<String> = names.iter().map(|n| format!("`{n}`")).collect();
    match q.len() {
        0 => String::new(),
        1 => q[0].clone(),
        2 => format!("{} and {}", q[0], q[1]),
        _ => {
            let (last, rest) = q.split_last().unwrap();
            format!("{}, and {}", rest.join(", "), last)
        }
    }
}

/// Error message for a patch that does not exist, with similar-name suggestions.
pub fn not_found_msg(name: &str, all: &[String]) -> String {
    let similar: Vec<String> = all.iter().filter(|n| jaro_winkler(name, n) > 0.75).cloned().collect();
    if similar.is_empty() {
        format!("patch `{name}` does not exist")
    } else {
        format!("patch `{name}` does not exist, but is similar to {}", conjoin(&similar))
    }
}
