    let mut out = parts.first().map(|p| p.to_string()).unwrap_or_default();
    if let Some(limit) = len_limit {
        for p in &parts[1..] {
            if out.chars().count() + 1 + p.chars().count() > limit {
                break;
            }
            out.push('-');
            out.push_str(p);
        }
    } else {
        out = s.to_string();
    }
    let out = sanitize(&out);
    let out = out.trim_matches('-').to_string();
    if out.is_empty() {
        "patch".to_string()
    } else {
        out
    }
}

/// Make a unique patch name not in `taken`.
pub fn uniquify(candidate: &str, taken: &dyn Fn(&str) -> bool) -> String {
    if !taken(candidate) {
        return candidate.to_string();
    }
    let (base, mut n) = match candidate.rfind('-') {
        Some(i) if i + 1 < candidate.len() && candidate[i + 1..].chars().all(|c| c.is_ascii_digit()) => {
            let num: u64 = candidate[i + 1..].parse().unwrap_or(0);
            (candidate[..i].to_string(), num + 1)
        }
        _ => (candidate.to_string(), 1),
    };
    loop {
        let name = format!("{base}-{n}");
        if !taken(&name) {
            return name;
        }
        n += 1;
    }
}

pub fn make(msg: &str, len_limit: Option<usize>, taken: &dyn Fn(&str) -> bool) -> String {
    uniquify(&make_candidate(msg, len_limit), taken)
}

// ------------------------------------------------------------ similarity

pub fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let (la, lb) = (a.len(), b.len());
    if la == 0 && lb == 0 {
        return 1.0;
    }
    if la == 0 || lb == 0 {
        return 0.0;
    }
    if la == 1 && lb == 1 {
        return if a[0] == b[0] { 1.0 } else { 0.0 };
    }
    let w = (la.max(lb) / 2).saturating_sub(1);
    let mut fa = vec![false; la];
    let mut fb = vec![false; lb];
    let mut m = 0usize;
    for (i, c) in a.iter().enumerate() {
        let lo = if i > w { i - w } else { 0 };
        let hi = (i + w + 1).min(lb);
        for j in lo..hi {
            if !fb[j] && b[j] == *c {
                fa[i] = true;
                fb[j] = true;
                m += 1;
                break;
            }
        }
    }
    if m == 0 {
        return 0.0;
    }
    let mut t = 0usize;
    let mut j = 0usize;
    for i in 0..la {
        if fa[i] {
            while !fb[j] {
                j += 1;
            }
            if a[i] != b[j] {
                t += 1;
            }
            j += 1;
        }
    }
    let m = m as f64;
    let t = t as f64 / 2.0;
    (m / la as f64 + m / lb as f64 + (m - t) / m) / 3.0
}

pub fn jaro_winkler(a: &str, b: &str) -> f64 {
    let j = jaro(a, b);
    let p = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).take(4).count();
    j + 0.1 * p as f64 * (1.0 - j)
}

/// Format a list of names like "`a`, `b`, and `c`".
pub fn conjoin(names: &[String]) -> String {
    let q: Vec<String> = names.iter().map(|n| format!("`{n}`")).collect();
    match q.len() {
        0 => String::new(),
        1 => q[0].clone(),
        2 => format!("{} and {}", q[0], q[1]),
        _ => {
            let (last, rest) = q.split_last().unwrap();
            format!("{}, and {}", rest.join(", "), last)
        }
    }
}

/// Error message for a patch that does not exist, with similar-name suggestions.
pub fn not_found_msg(name: &str, all: &[String]) -> String {
    let similar: Vec<String> = all.iter().filter(|n| jaro_winkler(name, n) > 0.75).cloned().collect();
    if similar.is_empty() {
        format!("patch `{name}` does not exist")
    } else {
        format!("patch `{name}` does not exist, but is similar to {}", conjoin(&similar))
    }
}
