//! Colored terminal output similar to termcolor.

use std::io::Write;
use std::sync::atomic::{AtomicU8, Ordering};

static COLOR_MODE: AtomicU8 = AtomicU8::new(0); // 0 = auto, 1 = always, 2 = never, 3 = ansi

pub fn set_mode(mode: &str) {
    let v = match mode {
        "always" => 1,
        "never" => 2,
        "ansi" => 3,
