    };
    COLOR_MODE.store(v, Ordering::SeqCst);
}

extern "C" {
    fn isatty(fd: i32) -> i32;
}

pub fn is_tty(fd: i32) -> bool {
    unsafe { isatty(fd) == 1 }
}

pub fn use_color(fd: i32) -> bool {
    match COLOR_MODE.load(Ordering::SeqCst) {
        1 | 3 => true,
        2 => false,
        _ => {
            if std::env::var_os("NO_COLOR").map(|v| !v.is_empty()).unwrap_or(false) {
                return false;
            }
            if std::env::var("TERM").map(|t| t == "dumb").unwrap_or(false) {
                return false;
            }
            is_tty(fd)
        }
    }
}

pub fn mode_str() -> &'static str {
    match COLOR_MODE.load(Ordering::SeqCst) {
        1 => "always",
        2 => "never",
        3 => "ansi",
        _ => "auto",
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Color {
    Default,
    Black,
    Red,
    Green,
    Yellow,
    Blue,
    Magenta,
    Cyan,
    White,
}

#[derive(Clone, Copy, Debug)]
pub struct Spec {
    pub fg: Color,
    pub bold: bool,
    pub dimmed: bool,
    pub italic: bool,
}

impl Spec {
    pub const fn plain() -> Spec {
        Spec { fg: Color::Default, bold: false, dimmed: false, italic: false }
    }
    pub const fn fg(c: Color) -> Spec {
        Spec { fg: c, bold: false, dimmed: false, italic: false }
    }
    pub const fn bold(mut self) -> Spec {
        self.bold = true;
        self
    }
    pub const fn dimmed(mut self) -> Spec {
        self.dimmed = true;
        self
    }
    pub const fn italic(mut self) -> Spec {
        self.italic = true;
        self
    }
}

fn spec_codes(s: &Spec) -> String {
    let mut out = String::from("\x1b[0m");
    if s.bold {
        out.push_str("\x1b[1m");
    }
    if s.dimmed {
        out.push_str("\x1b[2m");
    }
    if s.italic {
        out.push_str("\x1b[3m");
    }
    let code = match s.fg {
        Color::Default => None,
        Color::Black => Some(0),
        Color::Red => Some(1),
        Color::Green => Some(2),
        Color::Yellow => Some(3),
        Color::Blue => Some(4),
        Color::Magenta => Some(5),
        Color::Cyan => Some(6),
        Color::White => Some(7),
    };
    if let Some(c) = code {
        out.push_str(&format!("\x1b[3{c}m"));
    }
    out
}

/// A buffered writer for stdout or stderr supporting color specs.
pub struct Out {
    fd: i32,
    color: bool,
    buf: Vec<u8>,
}

impl Out {
    pub fn stdout() -> Out {
        Out { fd: 1, color: use_color(1), buf: Vec::new() }
    }
    pub fn stderr() -> Out {
        Out { fd: 2, color: use_color(2), buf: Vec::new() }
    }
    pub fn color_enabled(&self) -> bool {
        self.color
    }
    pub fn set(&mut self, spec: Spec) {
        if self.color {
            self.buf.extend_from_slice(spec_codes(&spec).as_bytes());
        }
    }
    pub fn reset(&mut self) {
        if self.color {
            self.buf.extend_from_slice(b"\x1b[0m");
        }
    }
    pub fn write(&mut self, s: &str) {
        self.buf.extend_from_slice(s.as_bytes());
    }
    pub fn write_bytes(&mut self, b: &[u8]) {
        self.buf.extend_from_slice(b);
    }
    /// Write text in a color then reset.
    pub fn colored(&mut self, spec: Spec, s: &str) {
        self.set(spec);
        self.write(s);
        self.reset();
    }
    pub fn flush(&mut self) {
        if self.buf.is_empty() {
            return;
        }
        if self.fd == 1 {
            let mut o = std::io::stdout();
            let _ = o.write_all(&self.buf);
            let _ = o.flush();
        } else {
            let mut o = std::io::stderr();
            let _ = o.write_all(&self.buf);
            let _ = o.flush();
        }
        self.buf.clear();
    }
}

impl Drop for Out {
    fn drop(&mut self) {
        self.flush();
    }
}

/// Print "info: ..." style message to stderr.
pub fn info(msg: &str) {
    let mut e = Out::stderr();
    e.colored(Spec::fg(Color::Cyan), "info");
    e.write(&format!(": {msg}\n"));
    e.flush();
}

pub fn warn(msg: &str) {
    let mut e = Out::stderr();
    e.colored(Spec::fg(Color::Yellow), "warning");
    e.write(&format!(": {msg}\n"));
    e.flush();
}

pub fn print_error(msg: &str) {
    let mut e = Out::stderr();
    e.colored(Spec::fg(Color::Red).bold(), "error");
    e.write(&format!(": {msg}\n"));
    e.flush();
}
