//! Stack transactions: sequences of patch operations committed atomically.

use crate::color::{Color, Out, Spec};
use crate::error::{Error, Result};
use crate::git::{Commit, NewCommit, Oid};
use crate::repo::Repo;
use crate::stack::{patch_refname, Stack, StackState};
use std::collections::BTreeMap;
use std::path::PathBuf;
use std::rc::Rc;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum PushStatus {
    None,
    New,
    Empty,
    Conflict,
    Modified,
    Unmodified,
}

impl PushStatus {
    fn suffix(&self) -> &'static str {
        match self {
            PushStatus::None => "",
            PushStatus::New => " (new)",
            PushStatus::Empty => " (empty)",
            PushStatus::Conflict => " (conflict)",
            PushStatus::Modified => " (modified)",
            PushStatus::Unmodified => " (unmodified)",
        }
    }
}

#[derive(Clone, Debug)]
enum Pending {
    None,
    Pop(String),
    Push(String, PushStatus),
}

#[derive(Clone, Debug, Default)]
pub struct TransOpts {
    /// Discard local changes (`--hard`).
    pub discard_changes: bool,
    /// Allow local changes; they will be merged during checkout.
    pub keep: bool,
    /// Allow the transaction even if HEAD is not the stack top.
    pub allow_bad_head: bool,
    /// Whether to allow pushes that result in conflicts.
    pub allow_conflicts: bool,
    pub committer_date_is_author_date: bool,
    /// Do not touch index/worktree at all.
    pub no_checkout: bool,
    /// Skip the clean index/worktree check.
    pub no_clean_check: bool,
    /// Skip the outstanding-conflicts check.
    pub allow_existing_conflicts: bool,
}

pub struct Transaction<'r> {
    pub repo: &'r Repo,
    pub stack: Stack<'r>,
    pub opts: TransOpts,
    pub applied: Vec<String>,
    pub unapplied: Vec<String>,
    pub hidden: Vec<String>,
    pub patches: BTreeMap<String, Oid>,
    pub base: Oid,
    /// Tree currently reflected by the index/worktree.
    current_tree: Oid,
    orig_head_tree: Oid,
    pending: Pending,
    pub out: Out,
    deferred: Vec<String>,
    pub conflict: Option<Vec<String>>,
    /// Set when execution should stop (e.g. conflicts).
    pub halted: bool,
    temp_index: Option<PathBuf>,
}

pub fn range_str(names: &[String]) -> String {
    match names.len() {
        0 => String::new(),
        1 => names[0].clone(),
        _ => format!("{}..{}", names[0], names[names.len() - 1]),
    }
}

impl<'r> Transaction<'r> {
    pub fn new(stack: Stack<'r>, opts: TransOpts) -> Result<Transaction<'r>> {
        let repo = stack.repo;
        if !opts.allow_bad_head {
            stack.check_head_top()?;
        }
        let base = stack.base()?;
        let head_tree = repo.commit(&stack.branch_head)?.tree.clone();
        let st = stack.state.clone();
        Ok(Transaction {
            repo,
            opts,
            applied: st.applied,
            unapplied: st.unapplied,
            hidden: st.hidden,
            patches: st.patches,
            base,
            current_tree: head_tree.clone(),
            orig_head_tree: head_tree,
            pending: Pending::None,
            out: Out::stdout(),
            deferred: Vec::new(),
            conflict: None,
            halted: false,
            temp_index: None,
            stack,
        })
    }

    /// Check for outstanding conflicts and (optionally) a clean index/worktree.
    pub fn check_worktree(&self) -> Result<()> {
        check_worktree(self.repo, &self.orig_head_tree, &self.opts)
    }

    pub fn all_patches(&self) -> Vec<String> {
        self.applied.iter().chain(self.unapplied.iter()).chain(self.hidden.iter()).cloned().collect()
    }

    pub fn has_patch(&self, name: &str) -> bool {
        self.patches.contains_key(name)
    }

    pub fn patch_commit(&self, name: &str) -> Result<Rc<Commit>> {
        let oid = self.patches.get(name).ok_or_else(|| Error::new(format!("patch `{name}` does not exist")))?;
        self.repo.commit(oid)
    }

    pub fn top_oid(&self) -> Oid {
        match self.applied.last() {
            Some(p) => self.patches[p].clone(),
            None => self.base.clone(),
        }
    }

    pub fn head_oid(&self) -> Oid {
        self.top_oid()
    }

    // ------------------------------------------------------------ output

    fn print_line(&mut self, marker: &str, spec: Spec, name: &str, suffix: &str, name_spec: Spec) {
        self.out.colored(spec, &format!("{marker} "));
        self.out.colored(name_spec, name);
        self.out.write(suffix);
        self.out.write("\n");
        self.out.flush();
    }

    fn print_top(&mut self, name: &str, status: PushStatus) {
        let st = status;
        self.print_line(">", Spec::fg(Color::Blue), name, st.suffix(), Spec::plain().bold());
    }

    fn print_pushed(&mut self, name: &str, status: PushStatus) {
        self.print_line("+", Spec::fg(Color::Green), name, status.suffix(), Spec::plain());
    }

    fn flush_push_pending(&mut self, as_top: bool) {
        if let Pending::Push(name, st) = self.pending.clone() {
            if as_top {
                self.print_top(&name, st);
            } else {
                self.print_pushed(&name, st);
            }
            self.pending = Pending::None;
        }
    }

    pub fn print_popped(&mut self, names: &[String]) {
        if names.is_empty() {
            return;
        }
        let s = range_str(names);
        self.print_line("-", Spec::fg(Color::Magenta), &s, "", Spec::plain());
    }

    pub fn print_deleted(&mut self, names: &[String]) {
        if names.is_empty() {
            return;
        }
        let s = range_str(names);
        self.print_line("#", Spec::fg(Color::Yellow), &s, "", Spec::plain());
    }

    pub fn print_updated(&mut self, name: &str) {
        self.flush_push_pending(true);
        self.print_line("&", Spec::fg(Color::Cyan), name, "", Spec::plain());
    }

    pub fn print_committed(&mut self, names: &[String]) {
        if names.is_empty() {
            return;
        }
        self.flush_push_pending(true);
        let s = range_str(names);
        self.print_line("$", Spec::fg(Color::Magenta), &s, "", Spec::plain());
    }

    pub fn defer_line(&mut self, marker: &str, names: &[String]) {
        if names.is_empty() {
            return;
        }
        self.deferred.push(format!("{marker} {}", range_str(names)));
    }

    // ------------------------------------------------------------ patch ops

    fn signature_for_rebase(&self, orig: &Commit) -> Result<crate::git::Signature> {
        let mut c = self.repo.committer()?;
        if self.opts.committer_date_is_author_date {
            c.time = orig.author.time;
            c.offset = orig.author.offset;
        }
        Ok(c)
    }

    fn keep_headers(orig: &Commit) -> Vec<(String, String)> {
        orig.extra_headers.iter().filter(|(k, _)| k == "encoding").cloned().collect()
    }

    /// Create a copy of `orig` with a new tree and parent.
    pub fn rebuild_commit(&self, orig: &Commit, tree: &str, parent: &str) -> Result<Oid> {
        let nc = NewCommit {
            tree: tree.to_string(),
            parents: vec![parent.to_string()],
            author: orig.author.clone(),
            committer: self.signature_for_rebase(orig)?,
            extra_headers: Self::keep_headers(orig),
            message: orig.message.clone(),
        };
        self.repo.write_commit(&nc)
    }

    fn temp_index_path(&mut self) -> PathBuf {
        if let Some(p) = &self.temp_index {
            return p.clone();
        }
        let p = self.repo.git_dir.join(format!("index.stg-tmp-{}", std::process::id()));
        self.temp_index = Some(p.clone());
        p
    }

    /// Try to apply the diff base..theirs onto ours using a temporary index.
    fn apply_in_temp_index(&mut self, base: &str, ours: &str, theirs: &str) -> Result<Option<Oid>> {
        let idx = self.temp_index_path();
        let repo = self.repo;
        repo.read_tree_into(ours, Some(&idx))?;
        let diff = repo
            .git(["diff-tree", "--full-index", "--binary", "--no-color", "--no-ext-diff", "--no-textconv", "-p", base, theirs, "--"])
            .run_ok()?;
        if diff.stdout.is_empty() {
            return Ok(Some(ours.to_string()));
        }
        let out = repo.git(["apply", "--cached"]).index(Some(&idx)).stdin(&diff.stdout).run()?;
        if !out.ok() {
            return Ok(None);
        }
        Ok(Some(repo.write_index_tree(Some(&idx))?))
    }

    /// Check out `tree` into the index and worktree, from the current tree.
    pub fn checkout(&mut self, tree: &str) -> Result<()> {
        if self.opts.no_checkout {
            self.current_tree = tree.to_string();
            return Ok(());
        }
        if self.current_tree == tree && !self.opts.discard_changes {
            return Ok(());
        }
        let repo = self.repo;
        let out = if self.opts.discard_changes {
            repo.git(["read-tree", "--reset", "-u", tree]).run()?
        } else {
            repo.git(["read-tree", "-m", "-u", &self.current_tree.clone(), tree]).run()?
        };
        if !out.ok() {
            let label = if self.opts.discard_changes { "`git read-tree --reset -u`" } else { "`git read-tree -m -u`" };
            return Err(Error::new(format!("{label}: {}", out.stderr_str().trim_end())));
        }
        self.current_tree = tree.to_string();
        Ok(())
    }

    /// Run a recursive merge in the worktree. Returns Ok(true) if clean.
    fn merge_in_worktree(&mut self, base: &str, ours: &str, theirs: &str) -> Result<bool> {
        self.checkout(ours)?;
        let repo = self.repo;
        let out = repo
            .git(["merge-recursive", base, "--", ours, theirs])
            .env(&format!("GITHEAD_{ours}"), "current")
            .env(&format!("GITHEAD_{theirs}"), "patched")
            .run()?;
        if out.status == 0 {
            let t = repo.write_index_tree(None)?;
            self.current_tree = t;
            Ok(true)
        } else if out.status == 1 {
            Ok(false)
        } else {
            Err(Error::new(format!("`git merge-recursive`: {}", out.stderr_str().trim_end())))
        }
    }

    /// Push an unapplied (or hidden) patch onto the stack.
    pub fn push_patch(&mut self, name: &str, set_tree: bool) -> Result<PushStatus> {
        if self.halted {
            return Ok(PushStatus::None);
        }
        let repo = self.repo;
        let commit = self.patch_commit(name)?;
        let parent = commit.parents.first().cloned().unwrap_or_default();
        let new_parent = self.top_oid();
        let mut status = PushStatus::None;
        let mut new_oid = commit.id.clone();
        if set_tree {
            if parent != new_parent {
                new_oid = self.rebuild_commit(&commit, &commit.tree, &new_parent)?;
            }
            let ptree = repo.commit(&new_parent)?.tree.clone();
            status = if ptree == commit.tree { PushStatus::Empty } else { PushStatus::Modified };
        } else if parent != new_parent {
            let base_tree = repo.commit(&parent)?.tree.clone();
            let ours = repo.commit(&new_parent)?.tree.clone();
            let theirs = commit.tree.clone();
            let mut conflict = false;
            let new_tree = if base_tree == ours {
                theirs.clone()
            } else if base_tree == theirs || ours == theirs {
                ours.clone()
            } else {
                match self.apply_in_temp_index(&base_tree, &ours, &theirs)? {
                    Some(t) => t,
                    None => {
                        if self.merge_in_worktree(&base_tree, &ours, &theirs)? {
                            self.current_tree.clone()
                        } else {
                            conflict = true;
                            ours.clone()
                        }
                    }
                }
            };
            new_oid = self.rebuild_commit(&commit, &new_tree, &new_parent)?;
            if conflict {
                status = PushStatus::Conflict;
            } else if new_tree == ours {
                status = PushStatus::Empty;
            }
            if conflict {
                self.halted = true;
                self.conflict = Some(repo.conflicts()?);
            }
        }
        self.unapplied.retain(|n| n != name);
        self.hidden.retain(|n| n != name);
        self.applied.push(name.to_string());
        self.patches.insert(name.to_string(), new_oid);
        // output
        if let Pending::Push(..) = self.pending {
            self.flush_push_pending(false);
        }
        self.pending = Pending::Push(name.to_string(), status);
        Ok(status)
    }

    /// Push several patches, stopping on conflicts.
    pub fn push_patches(&mut self, names: &[String], set_tree: bool) -> Result<()> {
        for n in names {
            if self.halted {
                break;
            }
            self.push_patch(n, set_tree)?;
        }
        Ok(())
    }

    /// Pop patches from the top down to (and including) the lowest applied patch for
    /// which `pred` is true. Returns the popped patches for which `pred` is false
    /// (in stack order), which callers typically push back.
    pub fn pop_patches<F: Fn(&str) -> bool>(&mut self, pred: F) -> Vec<String> {
        let idx = match self.applied.iter().position(|n| pred(n)) {
            Some(i) => i,
            None => return Vec::new(),
        };
        let popped: Vec<String> = self.applied.split_off(idx);
        let mut new_unapplied = popped.clone();
        new_unapplied.extend(self.unapplied.drain(..));
        self.unapplied = new_unapplied;
        // output
        self.flush_push_pending(true);
        self.print_popped(&popped);
        self.pending = match self.applied.last() {
            Some(t) => Pending::Pop(t.clone()),
            None => Pending::None,
        };
        popped.into_iter().filter(|n| !pred(n)).collect()
    }

    /// Delete patches (popping applied ones first). Returns patches to be pushed back.
    pub fn delete_patches<F: Fn(&str) -> bool>(&mut self, pred: F) -> Result<Vec<String>> {
        let to_push = self.pop_patches(&pred);
        let mut deleted = Vec::new();
        for n in self.all_patches() {
            if pred(&n) {
                deleted.push(n);
            }
        }
        // order: stack order
        let order = self.all_patches();
        deleted.sort_by_key(|n| order.iter().position(|x| x == n));
        for n in &deleted {
            self.unapplied.retain(|x| x != n);
            self.hidden.retain(|x| x != n);
            self.applied.retain(|x| x != n);
            self.patches.remove(n);
        }
        if let Pending::Pop(_) = self.pending {
            self.pending = Pending::None;
        }
        self.flush_push_pending(true);
        self.print_deleted(&deleted);
        Ok(to_push)
    }

    /// Add a new applied patch on top.
    pub fn new_applied(&mut self, name: &str, oid: &str) {
        self.patches.insert(name.to_string(), oid.to_string());
        self.applied.push(name.to_string());
        if let Pending::Push(..) = self.pending {
            self.flush_push_pending(false);
        }
        self.pending = Pending::Push(name.to_string(), PushStatus::New);
    }

    pub fn new_unapplied(&mut self, name: &str, oid: &str, pos: usize) {
        self.patches.insert(name.to_string(), oid.to_string());
        let pos = pos.min(self.unapplied.len());
        self.unapplied.insert(pos, name.to_string());
    }

    /// Update a patch's commit.
    pub fn update_patch(&mut self, name: &str, oid: &str) {
        let old = self.patches.insert(name.to_string(), oid.to_string());
        if old.as_deref() != Some(oid) {
            self.print_updated(name);
        }
    }

    /// Replace a patch commit silently.
    pub fn set_patch_commit(&mut self, name: &str, oid: &str) {
        self.patches.insert(name.to_string(), oid.to_string());
    }

    pub fn hide_patches(&mut self, names: &[String]) -> Result<()> {
        let set: Vec<String> = names.to_vec();
        let to_push = self.pop_patches(|n| set.contains(&n.to_string()));
        self.push_patches(&to_push, false)?;
        let order = self.all_patches();
        let mut hidden: Vec<String> = names.to_vec();
        hidden.sort_by_key(|n| order.iter().position(|x| x == n));
        for n in &hidden {
            self.unapplied.retain(|x| x != n);
            self.applied.retain(|x| x != n);
            if !self.hidden.contains(n) {
                self.hidden.push(n.clone());
            }
        }
        self.defer_line("!", &hidden);
        Ok(())
    }

    pub fn unhide_patches(&mut self, names: &[String]) {
        let order = self.all_patches();
        let mut v: Vec<String> = names.to_vec();
        v.sort_by_key(|n| order.iter().position(|x| x == n));
        for n in &v {
            self.hidden.retain(|x| x != n);
            self.unapplied.push(n.clone());
        }
        self.defer_line("-", &v);
    }

    pub fn rename_patch(&mut self, old: &str, new: &str) {
        for list in [&mut self.applied, &mut self.unapplied, &mut self.hidden] {
            for n in list.iter_mut() {
                if n == old {
                    *n = new.to_string();
                }
            }
        }
        if let Some(o) = self.patches.remove(old) {
            self.patches.insert(new.to_string(), o);
        }
        if let Pending::Push(n, st) = &self.pending {
            if n == old {
                self.pending = Pending::Push(new.to_string(), *st);
            }
        }
        if let Pending::Pop(n) = &self.pending {
            if n == old {
                self.pending = Pending::Pop(new.to_string());
            }
        }
    }

    /// Reorder patches. All patches must be accounted for.
    pub fn reorder(&mut self, applied: Vec<String>, unapplied: Vec<String>, hidden: Vec<String>) -> Result<()> {
        // Find the common prefix of currently applied and the new applied list.
        let common = self.applied.iter().zip(applied.iter()).take_while(|(a, b)| a == b).count();
        let to_pop: Vec<String> = self.applied[common..].to_vec();
        if !to_pop.is_empty() {
            let first = to_pop[0].clone();
            self.pop_patches(|n| n == first);
        }
        let to_push: Vec<String> = applied[common..].to_vec();
        self.push_patches(&to_push, false)?;
        if self.halted {
            return Ok(());
        }
        self.unapplied = unapplied;
        self.hidden = hidden;
        Ok(())
    }

    // ------------------------------------------------------------ execute

    /// Commit the transaction. `msg` is the stack log message.
    pub fn execute(mut self, msg: &str) -> Result<()> {
        let repo = self.repo;
        let new_head = self.head_oid();
        let new_tree = repo.commit(&new_head)?.tree.clone();
        let mut top_printed = false;
        if let Pending::Pop(t) | Pending::Push(t, _) = self.pending.clone() {
            let st = if let Pending::Push(_, s) = &self.pending { *s } else { PushStatus::None };
            self.print_top(&t, st);
            self.pending = Pending::None;
            top_printed = true;
        }
        if !self.halted {
            if let Err(e) = self.checkout(&new_tree) {
                if let Some(orig_top) = self.stack.state.applied.last().cloned() {
                    self.print_line("@", Spec::fg(Color::Yellow), &orig_top, " (rolled back)", Spec::plain());
                }
                self.cleanup();
                return Err(Error::new(format!("{};\ncommand aborted (all changes rolled back)", e.msg)));
            }
        }
        if !top_printed {
            if let Some(t) = self.applied.last().cloned() {
                self.print_top(&t, PushStatus::None);
            }
        }
        self.cleanup();

        // Update refs
        let stack = &mut self.stack;
        let branch_ref = stack.branch_ref.clone();
        let full_msg = if self.halted && self.conflict.is_some() { format!("{msg} (CONFLICT)") } else { msg.to_string() };
        if new_head != stack.branch_head {
            repo.update_ref(&branch_ref, &new_head, &full_msg)?;
            stack.branch_head = new_head.clone();
        }
        let old = stack.state.patches.clone();
        for (name, oid) in &self.patches {
            if old.get(name) != Some(oid) {
                repo.update_ref_no_log(&patch_refname(&stack.branch, name), oid)?;
            }
        }
        for name in old.keys() {
            if !self.patches.contains_key(name) {
                let _ = repo.delete_ref(&patch_refname(&stack.branch, name));
            }
        }
        let state = StackState {
            prev: None,
            head: new_head,
            applied: self.applied.clone(),
            unapplied: self.unapplied.clone(),
            hidden: self.hidden.clone(),
            patches: self.patches.clone(),
        };
        stack.commit_state(state, &full_msg)?;

        for line in std::mem::take(&mut self.deferred) {
            let (marker, rest) = line.split_at(1);
            let spec = if marker == "!" { Spec::fg(Color::Red) } else { Spec::fg(Color::Magenta) };
            self.out.colored(spec, &format!("{marker} "));
            self.out.write(rest.trim_start());
            self.out.write("\n");
        }
        self.out.flush();

        if self.halted {
            if let Some(conflicts) = &self.conflict {
                let mut o = Out::stdout();
                for c in conflicts {
                    o.write(&format!("UU {c}\n"));
                }
                o.flush();
                return Err(Error::with_code(
                    "merge conflicts; resolve conflicts manually then refresh or undo the operation with `stg undo --hard`.",
                    3,
                ));
            }
        }
        Ok(())
    }

    fn cleanup(&mut self) {
        if let Some(p) = self.temp_index.take() {
            let _ = std::fs::remove_file(p);
        }
    }
}

impl<'r> Drop for Transaction<'r> {
    fn drop(&mut self) {
        self.cleanup();
    }
}

/// Check for conflicts and clean index/worktree as required by `opts`.
pub fn check_worktree(repo: &Repo, head_tree: &str, opts: &TransOpts) -> Result<()> {
    if !opts.allow_existing_conflicts && !repo.conflicts()?.is_empty() {
        return Err(Error::new("resolve outstanding conflicts first"));
    }
    if opts.keep || opts.discard_changes || opts.no_clean_check {
        return Ok(());
    }
    repo.update_index_refresh();
    let index_dirty = repo.index_differs_from(head_tree)?;
    let wt_dirty = repo.worktree_differs()?;
    match (index_dirty, wt_dirty) {
        (true, true) => Err(Error::new("index and worktree not clean; use `refresh` or `reset --hard`")),
        (true, false) => Err(Error::new("index not clean; use `refresh` or `reset --hard`")),
        (false, true) => Err(Error::new("worktree not clean; use `refresh` or `reset --hard`")),
        _ => Ok(()),
    }
}
