fn builtin_aliases() -> BTreeMap<String, String> {
    let mut m = BTreeMap::new();
    m.insert("add".to_string(), "!git -C \"$GIT_PREFIX\" add".to_string());
    m.insert("mv".to_string(), "!git -C \"$GIT_PREFIX\" mv".to_string());
    m.insert("resolved".to_string(), "!git -C \"$GIT_PREFIX\" add".to_string());
    m.insert("rm".to_string(), "!git -C \"$GIT_PREFIX\" rm".to_string());
    m.insert("status".to_string(), "!git status -s".to_string());
    m
}

fn load_aliases(config: &config::Config) -> Vec<AliasInfo> {
    let mut m = builtin_aliases();
    for (k, v) in config.entries_with_prefix("stgit.alias.") {
        let name = k["stgit.alias.".len()..].to_string();
        m.insert(name, v);
    }
    let builtins: Vec<String> = cli_top::command_categories()
        .into_iter()
        .flat_map(|(_, cmds)| cmds.into_iter().map(|c| c.get_name().to_string()))
        .collect();
    m.into_iter()
        .filter(|(n, _)| !builtins.contains(n) && n != "help")
        .map(|(name, v)| {
            if let Some(c) = v.strip_prefix('!') {
                AliasInfo { name, command: c.to_string(), is_shell: true }
            } else {
                AliasInfo { name, command: v, is_shell: false }
            }
        })
        .collect()
}

/// Process leading `-C <path>` options before full argument parsing.
fn process_dash_c(args: &[String]) -> Result<()> {
    let mut i = 1;
    while i < args.len() {
        let a = &args[i];
        if a == "-C" {
            if i + 1 < args.len() {
                let p = &args[i + 1];
                if !p.is_empty() {
                    std::env::set_current_dir(p).map_err(|e| Error::new(format!("cannot change to `{p}`: {e}")))?;
                }
                i += 2;
                continue;
            }
            break;
        } else if let Some(p) = a.strip_prefix("-C") {
            let p = p.strip_prefix('=').unwrap_or(p);
            std::env::set_current_dir(p).map_err(|e| Error::new(format!("cannot change to `{p}`: {e}")))?;
            i += 1;
            continue;
        } else if a == "--color" {
            i += 2;
            continue;
        } else if a.starts_with("--color=") {
            i += 1;
            continue;
        } else {
            break;
        }
    }
    Ok(())
}

/// Split a string into words like a POSIX shell (quotes and backslashes).
pub fn shell_split(s: &str) -> Vec<String> {
    let mut words = Vec::new();
    let mut cur = String::new();
    let mut in_word = false;
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '\'' => {
                in_word = true;
                for c2 in chars.by_ref() {
                    if c2 == '\'' {
                        break;
                    }
                    cur.push(c2);
                }
            }
            '"' => {
                in_word = true;
                while let Some(c2) = chars.next() {
                    if c2 == '"' {
                        break;
                    }
                    if c2 == '\\' {
                        if let Some(&n) = chars.peek() {
                            if n == '"' || n == '\\' || n == '$' || n == '`' {
                                cur.push(n);
                                chars.next();
                                continue;
                            }
                        }
                    }
                    cur.push(c2);
                }
            }
            '\\' => {
                in_word = true;
                if let Some(n) = chars.next() {
                    cur.push(n);
                }
            }
            c if c.is_whitespace() => {
                if in_word {
                    words.push(std::mem::take(&mut cur));
                    in_word = false;
                }
            }
            c => {
                in_word = true;
                cur.push(c);
            }
        }
    }
    if in_word {
        words.push(cur);
    }
    words
}

fn run_shell_alias(alias: &AliasInfo, args: &[String]) -> Result<i32> {
    let mut cmd = std::process::Command::new("sh");
    let script = format!("{} \"$@\"", alias.command);
    cmd.arg("-c").arg(&script).arg(&alias.command).args(args);
    // Run from the top of the work tree with GIT_PREFIX set.
    let out = git::git(["rev-parse", "--show-prefix"]).run();
    if let Ok(o) = &out {
        if o.ok() {
            cmd.env("GIT_PREFIX", o.stdout_str().trim_end_matches('\n'));
            if let Ok(top) = git::git(["rev-parse", "--show-toplevel"]).run() {
                if top.ok() {
                    cmd.current_dir(top.stdout_str().trim_end_matches('\n'));
                }
            }
        }
    }
    let status = cmd.status().map_err(|e| Error::new(format!("{e}")))?;
    Ok(status.code().unwrap_or(1))
}

fn print_clap_error(e: &clap::Error) -> i32 {
    let _ = e.print();
    if e.use_stderr() {
        1
    } else {
        0
    }
}

fn real_main() -> i32 {
    let mut args: Vec<String> = std::env::args().collect();
    if let Err(e) = process_dash_c(&args) {
        color::print_error(&e.msg);
        return e.code;
    }
    let config = config::Config::load();
    let aliases = load_aliases(&config);

    let mut depth = 0;
    loop {
        let cli = cli_top::build_cli(&aliases);
        let matches = match cli.try_get_matches_from(&args) {
            Ok(m) => m,
            Err(e) => return print_clap_error(&e),
        };
        if let Some(c) = matches.get_one::<String>("color") {
            color::set_mode(c);
        }
        if matches.get_flag("version") {
            return match cmd::version::print_full() {
                Ok(()) => 0,
                Err(e) => {
                    color::print_error(&e.msg);
                    e.code
                }
            };
        }
        let (name, sub) = match matches.subcommand() {
            Some((n, s)) => (n.to_string(), s.clone()),
            None => {
                let mut cli = cli_top::build_cli(&aliases);
                let _ = cli.print_help();
                return 1;
            }
        };
        if let Some(alias) = aliases.iter().find(|a| a.name == name) {
            let rest: Vec<String> = sub.get_many::<String>("args").map(|v| v.cloned().collect()).unwrap_or_default();
            if rest.iter().any(|a| a == "-h" || a == "--help") {
                let shown = if alias.is_shell { format!("!{}", alias.command) } else { alias.command.clone() };
                eprintln!("'{}' is aliased to '{}'", alias.name, shown);
            }
            if alias.is_shell {
                return match run_shell_alias(alias, &rest) {
                    Ok(c) => c,
                    Err(e) => {
                        color::print_error(&e.msg);
                        e.code
                    }
                };
            }
            depth += 1;
            if depth > 10 {
                color::print_error(&format!("recursive alias `{}`", alias.name));
                return 1;
            }
            // Re-parse with the alias expanded.
            let pos = args.iter().position(|a| *a == name).unwrap_or(1);
            let mut new_args: Vec<String> = args[..pos].to_vec();
            new_args.extend(shell_split(&alias.command));
            new_args.extend(args[pos + 1..].iter().cloned());
            args = new_args;
            continue;
        }
        return match dispatch(&name, &sub) {
            Ok(()) => 0,
            Err(e) => {
                if !e.silent {
                    color::print_error(&e.msg);
                }
                e.code
            }
        };
    }
}

fn dispatch(name: &str, m: &ArgMatches) -> Result<()> {
    cmd::dispatch(name, m)
}

fn main() {
    let code = real_main();
    std::process::exit(code);
}
