//! Patch description editing: messages, trailers, authors, and editor invocation.

use crate::error::{Error, Result};
use crate::git::Signature;
use crate::repo::Repo;
use clap::ArgMatches;
use std::path::PathBuf;

/// Clean up a commit message: strip trailing whitespace, collapse blank lines,
/// optionally drop comment lines, ensure trailing newline. Empty stays empty.
pub fn cleanup_message(msg: &str, strip_comments: bool) -> String {
    let mut lines: Vec<String> = Vec::new();
    for line in msg.split('\n') {
        if strip_comments && line.starts_with('#') {
            continue;
        }
        lines.push(line.trim_end().to_string());
    }
    let mut out: Vec<String> = Vec::new();
    let mut blank_pending = false;
    for l in lines {
        if l.is_empty() {
            blank_pending = !out.is_empty();
            continue;
        }
        if blank_pending {
            out.push(String::new());
            blank_pending = false;
        }
        out.push(l);
    }
    if out.is_empty() {
        return String::new();
    }
    let mut s = out.join("\n");
    s.push('\n');
    s
}

pub fn editor_command(repo: &Repo) -> String {
    if let Ok(e) = std::env::var("GIT_EDITOR") {
        return e;
    }
    if let Some(e) = repo.config.get("stgit.editor") {
        return e;
    }
    if let Some(e) = repo.config.get("core.editor") {
        return e;
    }
    if let Ok(e) = std::env::var("VISUAL") {
        return e;
    }
    if let Ok(e) = std::env::var("EDITOR") {
        return e;
    }
    "vi".to_string()
}

const SHELL_META: &[char] = &['|', '&', ';', '<', '>', '(', ')', '$', '`', '\\', '"', '\'', '*', '?', '[', '#', '~', '=', '%', '\n'];

/// Invoke the editor on `path` (relative to cwd).
pub fn run_editor(repo: &Repo, path: &str) -> Result<()> {
    let editor = editor_command(repo);
    eprintln!("hint: Waiting for your editor to close the file...");
    let status = if editor.contains(SHELL_META) {
        std::process::Command::new("sh").arg("-c").arg(format!("{editor} \"$@\"")).arg(&editor).arg(path).status()
    } else {
        let parts: Vec<&str> = editor.split_whitespace().collect();
        if parts.is_empty() {
            return Err(Error::new(format!("running editor: {editor}: No such file or directory (os error 2)")));
        }
        std::process::Command::new(parts[0]).args(&parts[1..]).arg(path).status()
    };
    match status {
        Err(e) => Err(Error::new(format!("running editor: {editor}: {e}"))),
        Ok(st) if !st.success() => Err(Error::new(format!("problem with the editor `{editor}`"))),
        Ok(_) => Ok(()),
    }
}

/// Edit the given text with the user's editor; returns edited text.
pub fn edit_text(repo: &Repo, text: &str) -> Result<String> {
    let path = PathBuf::from(".stgit-edit.txt");
    std::fs::write(&path, text).map_err(|e| Error::new(format!("{e}")))?;
    let res = run_editor(repo, ".stgit-edit.txt");
    if let Err(e) = res {
        return Err(e);
    }
    let data = std::fs::read(&path).map_err(|e| Error::new(format!("{e}")))?;
    let _ = std::fs::remove_file(&path);
    Ok(String::from_utf8_lossy(&data).into_owned())
}

pub const INSTRUCTIONS: &str = "# Please enter the message for your patch. Lines starting with\n# '#' will be ignored. An empty message aborts the new patch.\n# The patch name and author information may also be modified.\n";
pub const DIFF_INSTRUCTIONS: &str = "# The diff below may be edited.\n# ------------------------ >8 ------------------------\n# Do not modify or remove the line above.\n";
pub const SCISSORS: &str = "# ------------------------ >8 ------------------------";

pub fn make_template(name: &str, author: &Signature, message: &str, diff: Option<&[u8]>) -> Vec<u8> {
    let mut s = String::new();
    s.push_str(&format!("Patch:  {name}\n"));
    s.push_str(&format!("Author: {}\n", author.name_email()));
    s.push_str(&format!("Date:   {}\n", crate::timefmt::format_iso(author.time, author.offset)));
    s.push('\n');
    s.push_str(message.trim_end_matches('\n'));
    s.push_str("\n\n");
    s.push_str(INSTRUCTIONS);
    let mut out = s.into_bytes();
    if let Some(d) = diff {
        out.extend_from_slice(DIFF_INSTRUCTIONS.as_bytes());
        out.extend_from_slice(d);
    }
    out
}

pub struct Parsed {
    pub name: Option<String>,
    pub author_name_email: Option<(String, String)>,
    pub date: Option<(i64, i32)>,
    pub date_given: bool,
    pub message: String,
    pub diff: Option<Vec<u8>>,
}

pub fn parse_name_email(s: &str) -> Option<(String, String)> {
    let s = s.trim();
    let lt = s.find('<')?;
    let gt = s.rfind('>')?;
    if gt < lt || gt != s.len() - 1 {
        return None;
    }
    let name = s[..lt].trim().to_string();
    let email = s[lt + 1..gt].trim().to_string();
    Some((name, email))
}

pub fn parse_edited(text: &str) -> Result<Parsed> {
    let (body, diff) = match text.find(SCISSORS) {
        Some(i) => {
            let after = &text[i + SCISSORS.len()..];
            let after = after.strip_prefix('\n').unwrap_or(after);
            // skip the "Do not modify" line
            let after = match after.find('\n') {
                Some(j) if after.starts_with('#') => &after[j + 1..],
                _ => after,
            };
            (&text[..i], Some(after.as_bytes().to_vec()))
        }
        None => (text, None),
    };
    let lines: Vec<&str> = body.split('\n').collect();
    let mut idx = 0;
    let mut name = None;
    let mut author = None;
    let mut date = None;
    let mut date_given = false;
    if let Some(l) = lines.first() {
        if let Some(rest) = l.strip_prefix("Patch:") {
            let n = rest.trim();
            name = Some(n.to_string());
            idx = 1;
            if let Some(l) = lines.get(idx) {
                if let Some(rest) = l.strip_prefix("Author:") {
                    let a = rest.trim();
                    match parse_name_email(a) {
                        Some(ne) => author = Some(ne),
                        None => return Err(Error::new(format!("invalid name and email `{a}`"))),
                    }
                    idx += 1;
                    if let Some(l) = lines.get(idx) {
                        if let Some(rest) = l.strip_prefix("Date:") {
                            let d = rest.trim();
                            date_given = true;
                            match crate::timefmt::parse_date(d) {
                                Some(v) => date = Some(v),
                                None => return Err(Error::new(format!("invalid date `{d}`"))),
                            }
                            idx += 1;
                        }
                    }
                }
            }
        }
    }
    let msg = lines[idx..].join("\n");
    let message = cleanup_message(&msg, true);
    Ok(Parsed { name, author_name_email: author, date, date_given, message, diff })
}

// ------------------------------------------------------------ trailers

fn is_trailer_line(l: &str) -> bool {
    match l.find(':') {
        Some(i) if i > 0 => {
            let tok = &l[..i];
            tok.chars().all(|c| c.is_ascii_alphanumeric() || c == '-')
        }
        _ => false,
    }
}

pub fn add_trailer(msg: &str, key: &str, value: &str) -> String {
    let trailer = format!("{key}: {value}");
    let body = msg.trim_end_matches('\n');
    let paras: Vec<&str> = body.split("\n\n").collect();
    if paras.len() > 1 {
        let last = paras[paras.len() - 1];
        let lines: Vec<&str> = last.split('\n').collect();
        if !lines.is_empty() && lines.iter().all(|l| is_trailer_line(l) || l.starts_with(' ') || l.starts_with('\t')) {
            if lines.last().map(|l| l.trim() == trailer).unwrap_or(false) {
                return format!("{body}\n");
            }
            return format!("{body}\n{trailer}\n");
        }
    }
    if body.is_empty() {
        return format!("\n{trailer}\n");
    }
    format!("{body}\n\n{trailer}\n")
}

// ------------------------------------------------------------ options

#[derive(Default, Clone)]
pub struct EditOpts {
    pub edit: bool,
    pub diff: bool,
    pub message: Option<String>,
    pub file: Option<String>,
    pub no_verify: bool,
    pub trailers: Vec<(String, Option<String>)>,
    pub author: Option<String>,
    pub authname: Option<String>,
    pub authemail: Option<String>,
    pub authdate: Option<String>,
    pub committer_date_is_author_date: bool,
    pub save_template: Option<String>,
}

fn get_str(m: &ArgMatches, id: &str) -> Option<String> {
    match m.try_get_one::<String>(id) {
        Ok(v) => v.cloned(),
        Err(_) => None,
    }
}

fn get_flag(m: &ArgMatches, id: &str) -> bool {
    m.try_get_one::<bool>(id).ok().flatten().copied().unwrap_or(false)
}

impl EditOpts {
    pub fn from_matches(m: &ArgMatches) -> EditOpts {
        let mut trailers: Vec<(usize, String, Option<String>)> = Vec::new();
        for (id, key) in [("signoff", "Signed-off-by"), ("ack", "Acked-by"), ("review", "Reviewed-by")] {
            if let Ok(Some(vals)) = m.try_get_raw_occurrences(id) {
                let idxs: Vec<usize> = m.indices_of(id).map(|i| i.collect()).unwrap_or_default();
                let mut k = 0;
                for occ in vals {
                    let v: Vec<String> = occ.map(|s| s.to_string_lossy().into_owned()).collect();
                    let idx = idxs.get(k).copied().unwrap_or(0);
                    k += 1;
                    trailers.push((idx, key.to_string(), v.into_iter().next()));
                }
            }
        }
        trailers.sort_by_key(|t| t.0);
        EditOpts {
            edit: get_flag(m, "edit"),
            diff: get_flag(m, "diff"),
            message: get_str(m, "message"),
            file: get_str(m, "file"),
            no_verify: get_flag(m, "no-verify"),
            trailers: trailers.into_iter().map(|(_, k, v)| (k, v)).collect(),
            author: get_str(m, "author"),
            authname: get_str(m, "authname"),
            authemail: get_str(m, "authemail"),
            authdate: get_str(m, "authdate"),
            committer_date_is_author_date: get_flag(m, "committer-date-is-author-date"),
            save_template: get_str(m, "save-template"),
        }
    }

    /// Read the message from -m or -f.
    pub fn read_message(&self) -> Result<Option<String>> {
        if let Some(m) = &self.message {
            return Ok(Some(m.clone()));
        }
        if let Some(f) = &self.file {
            let data = if f == "-" {
                let mut v = Vec::new();
                use std::io::Read;
                std::io::stdin().read_to_end(&mut v)?;
                v
            } else {
                std::fs::read(f).map_err(|e| Error::new(format!("{f}: {e}")))?
            };
            return Ok(Some(String::from_utf8_lossy(&data).into_owned()));
        }
        Ok(None)
    }

    pub fn apply_author(&self, author: &mut Signature) -> Result<()> {
        if let Some(a) = &self.author {
            let (n, e) = parse_name_email(a).ok_or_else(|| Error::new(format!("invalid name and email `{a}`")))?;
            author.name = n;
            author.email = e;
        }
        if let Some(n) = &self.authname {
            author.name = n.clone();
        }
        if let Some(e) = &self.authemail {
            author.email = e.clone();
        }
        if let Some(d) = &self.authdate {
            let (t, o) = crate::timefmt::parse_date(d).ok_or_else(|| Error::new(format!("invalid date `{d}`")))?;
            author.time = t;
            author.offset = o;
        }
        Ok(())
    }

    pub fn apply_trailers(&self, repo: &Repo, msg: &str) -> Result<String> {
        let mut m = msg.to_string();
        if self.trailers.is_empty() {
            return Ok(m);
        }
        let default = || -> Result<String> { Ok(repo.committer()?.name_email()) };
        for (k, v) in &self.trailers {
            let val = match v {
                Some(v) => v.clone(),
                None => default()?,
            };
            m = add_trailer(&m, k, &val);
        }
        Ok(m)
    }
}

/// Run the commit-msg hook on a message, returning the possibly-modified message.
pub fn run_commit_msg_hook(repo: &Repo, msg: &str) -> Result<String> {
    let hooks_dir = match repo.config.get("core.hookspath") {
        Some(p) => {
            let pb = PathBuf::from(&p);
            if pb.is_absolute() {
                pb
            } else {
                repo.work_dir.clone().unwrap_or_else(|| repo.git_dir.clone()).join(pb)
            }
        }
        None => repo.common_dir.join("hooks"),
    };
    let hook = hooks_dir.join("commit-msg");
    let meta = match std::fs::metadata(&hook) {
        Ok(m) => m,
        Err(_) => return Ok(msg.to_string()),
    };
    use std::os::unix::fs::PermissionsExt;
    if meta.permissions().mode() & 0o111 == 0 {
        return Ok(msg.to_string());
    }
    let tmp = repo.git_dir.join("COMMIT_EDITMSG");
    std::fs::write(&tmp, msg)?;
    let mut cmd = std::process::Command::new(&hook);
    cmd.arg(&tmp);
    if let Some(w) = &repo.work_dir {
        cmd.current_dir(w);
    }
    let st = cmd.status().map_err(|e| Error::new(format!("{e}")))?;
    if !st.success() {
        return Err(Error::new("commit-msg hook failed"));
    }
    let data = std::fs::read(&tmp)?;
    Ok(String::from_utf8_lossy(&data).into_owned())
}
