use crate::error::{Error, Result};
use crate::git::Oid;
use crate::patchname;
use crate::repo::Repo;
use crate::stack::{InitPolicy, Stack};

fn caret_error(spec: &str, pos: usize) -> Error {
    Error::new(format!("invalid StGit revision `{spec}`: {spec}\n{}^\n", " ".repeat(pos)))
}

/// Syntax validation used by clap value parsers.
pub fn validate_syntax(spec: &str) -> std::result::Result<(), String> {
    if spec.starts_with(':') {
        return Err(caret_error(spec, 0).msg);
    }
    if let Some(i) = spec.find("..") {
        return Err(caret_error(spec, i).msg);
    }
    Ok(())
}

/// Split "[branch:]name[suffix]" where suffix starts at first '^' or '~'.
pub fn split_spec(spec: &str) -> (Option<&str>, &str, &str) {
    let (branch, rest) = match spec.find(':') {
        Some(i) if i > 0 => (Some(&spec[..i]), &spec[i + 1..]),
        _ => (None, spec),
    };
    let cut = rest.find(['^', '~']).unwrap_or(rest.len());
    (branch, &rest[..cut], &rest[cut..])
}

fn apply_suffix(repo: &Repo, oid: &str, suffix: &str, peel_commit: bool) -> Result<Oid> {
    if suffix.is_empty() {
        return Ok(oid.to_string());
    }
    let spec = format!("{oid}{suffix}");
    let r = if peel_commit { repo.rev_parse_commit(&spec) } else { repo.rev_parse(&spec) };
    r.ok_or_else(|| Error::new(format!("invalid StGit revision `{spec}`")))
}

/// Resolve a StGit revision to an object id.
pub fn resolve(repo: &Repo, spec: Option<&str>, branch: Option<&str>) -> Result<Oid> {
    resolve_inner(repo, spec, branch, false)
}

pub fn resolve_commit(repo: &Repo, spec: Option<&str>, branch: Option<&str>) -> Result<Oid> {
    resolve_inner(repo, spec, branch, true)
}

fn resolve_inner(repo: &Repo, spec: Option<&str>, branch: Option<&str>, peel: bool) -> Result<Oid> {
    let spec = match spec {
        None => {
            return match branch {
                Some(b) => {
                    let st = Stack::from_branch(repo, Some(b), InitPolicy::AllowUninitialized)?;
                    Ok(st.branch_head.clone())
                }
                None => repo.head_oid().ok_or_else(|| Error::new("HEAD does not point to a commit")),
            }
        }
        Some(s) => s,
    };
    let (sbranch, name, suffix) = split_spec(spec);
    if let Some(b) = sbranch {
        let st = Stack::from_branch(repo, Some(b), InitPolicy::AllowUninitialized)?;
        if name == "{base}" {
            return apply_suffix(repo, &st.base()?, suffix, peel);
        }
        if let Some(o) = st.patch_oid(name) {
            return apply_suffix(repo, o, suffix, peel);
        }
        return Err(Error::new(format!("patch `{name}` does not exist")));
    }
    // Try a patch in the given/current branch.
    let stack = match branch {
        Some(b) => Some(Stack::from_branch(repo, Some(b), InitPolicy::AllowUninitialized)?),
        None => Stack::from_branch(repo, None, InitPolicy::AllowUninitialized).ok(),
    };
    if let Some(st) = &stack {
        if name == "{base}" {
            return apply_suffix(repo, &st.base()?, suffix, peel);
        }
        if let Some(o) = st.patch_oid(name) {
            return apply_suffix(repo, o, suffix, peel);
        }
    }
    let r = if peel { repo.rev_parse_commit(spec) } else { repo.rev_parse(spec) };
    match r {
        Some(o) => Ok(o),
        None => {
            if suffix.is_empty() || !name.is_empty() {
                if let Some(st) = &stack {
                    let all: Vec<String> = st.state.all_patches().cloned().collect();
                    return Err(Error::new(patchname::not_found_msg(name, &all)));
                }
            }
            Err(Error::new(format!("patch `{name}` does not exist")))
        }
    }
}

/// Resolve patch name arguments and ranges ("a..b", "a..", "..b") against `order`.
/// `all` is the full list of known patches (for "does not exist" errors).
pub fn patch_ranges(args: &[String], order: &[String], all: &[String]) -> Result<Vec<String>> {
    let mut out: Vec<String> = Vec::new();
    for a in args {
        if let Some((lo, hi)) = a.split_once("..") {
            let start = if lo.is_empty() {
                0
            } else {
                match order.iter().position(|n| n == lo) {
                    Some(i) => i,
                    None => return Err(range_err(lo, all)),
                }
            };
            let end = if hi.is_empty() {
                order.len().saturating_sub(1)
            } else {
                match order.iter().position(|n| n == hi) {
                    Some(i) => i,
                    None => return Err(range_err(hi, all)),
                }
            };
            if order.is_empty() {
                continue;
            }
            if start <= end {
                for n in &order[start..=end] {
                    out.push(n.clone());
                }
            }
        } else {
            if !all.contains(a) {
                return Err(Error::new(patchname::not_found_msg(a, all)));
            }
            out.push(a.clone());
        }
    }
    Ok(out)
}

fn range_err(name: &str, all: &[String]) -> Error {
    Error::new(patchname::not_found_msg(name, all))
}
