use crate::repo::Repo;
use crate::stack::{InitPolicy, Stack};
use crate::trans::{check_worktree, TransOpts, Transaction};
use clap::ArgMatches;

pub fn name_len_limit(repo: &Repo) -> Option<usize> {
    match repo.config.get_i64("stgit.namelength") {
        Some(n) if n <= 0 => None,
        Some(n) => Some(n as usize),
        None => Some(30),
    }
}

pub fn run(m: &ArgMatches) -> Result<()> {
    let repo = Repo::open()?;
    let stack = Stack::from_branch(&repo, None, InitPolicy::AutoInitialize)?;
    let eo = EditOpts::from_matches(m);
    let name_arg = super::s(m, "patchname").or_else(|| super::s(m, "name"));
    let paths = super::many(m, "path");
    let refresh = super::flag(m, "refresh") || !paths.is_empty();

    stack.check_head_top()?;
    let opts = TransOpts { no_clean_check: true, ..Default::default() };
    let head_tree = repo.commit(&stack.branch_head)?.tree.clone();
    check_worktree(&repo, &head_tree, &opts)?;

    if let Some(n) = &name_arg {
        if stack.state.has_patch(n) {
            return Err(Error::new(format!("patch `{n}` already exists")));
        }
    }

    let mut author = repo.author()?;
    eo.apply_author(&mut author)?;
    let mut committer = repo.committer()?;

    let parent = stack.branch_head.clone();
    let tree = if refresh {
        let ro = super::refresh::RefreshTreeOpts {
            index: super::flag(m, "index"),
            force: super::flag(m, "force"),
            paths: paths.clone(),
            submodules: super::flag(m, "submodules"),
            update: false,
        };
        super::refresh::compute_refresh_tree(&repo, &stack, &ro, None)?
    } else {
        head_tree.clone()
    };

    let msg_given = eo.read_message()?;
    let mut message = match &msg_given {
        Some(msg) => edit::cleanup_message(msg, false),
        None => {
            let tmpl = repo.git_dir.join("patchdescr.tmpl");
            match std::fs::read(&tmpl) {
                Ok(d) => String::from_utf8_lossy(&d).into_owned(),
                Err(_) => String::new(),
            }
        }
    };
    message = eo.apply_trailers(&repo, &message)?;

    let mut name = name_arg.clone();
    if let Some(path) = &eo.save_template {
        let diff = if eo.diff { Some(Vec::new()) } else { None };
        let t = edit::make_template(name.as_deref().unwrap_or(""), &author, &message, diff.as_deref());
        if path == "-" {
            use std::io::Write;
            let _ = std::io::stdout().write_all(&t);
        } else {
            std::fs::write(path, &t)?;
        }
        return Ok(());
    }

    if msg_given.is_none() || eo.edit {
        let diff = if eo.diff { Some(Vec::new()) } else { None };
        let t = edit::make_template(name.as_deref().unwrap_or(""), &author, &message, diff.as_deref());
        let edited = edit::edit_text(&repo, &String::from_utf8_lossy(&t))?;
        let parsed = edit::parse_edited(&edited)?;
        if let Some(n) = parsed.name {
            if !n.is_empty() {
                let n = patchname::parse_user(&n).map_err(Error::new)?;
                name = Some(n);
            } else {
                name = None;
            }
        }
        if let Some((n, e)) = parsed.author_name_email {
            author.name = n;
            author.email = e;
            if let Some((t, o)) = parsed.date {
                author.time = t;
                author.offset = o;
            }
        }
        message = parsed.message;
        if message.trim().is_empty() {
            return Err(Error::new("aborting due to empty patch description"));
        }
    }

    if !eo.no_verify {
        message = edit::run_commit_msg_hook(&repo, &message)?;
    }

    if eo.committer_date_is_author_date {
        committer.time = author.time;
        committer.offset = author.offset;
    }

    let name = match name {
        Some(n) => {
            if stack.state.has_patch(&n) {
                return Err(Error::new(format!("patch `{n}` already exists")));
            }
            n
        }
        None => {
            let limit = name_len_limit(&repo);
            let st = &stack.state;
            patchname::make(&message, limit, &|n: &str| st.has_patch(n))
        }
    };

    let nc = NewCommit { tree, parents: vec![parent], author, committer, extra_headers: vec![], message: message.into_bytes() };
    let oid = repo.write_commit(&nc)?;
    let mut trans = Transaction::new(stack, TransOpts { no_clean_check: true, ..Default::default() })?;
    trans.new_applied(&name, &oid);
    trans.execute(&format!("new: {name}"))
}
EOF
