//! Semantic adjustments (value parsers, conflicts, actions) for the CLI definitions.

use clap::builder::{NonEmptyStringValueParser, PossibleValuesParser, TypedValueParser};
use clap::{Arg, ArgAction, Command};

fn patchname_parser() -> impl TypedValueParser<Value = String> {
    NonEmptyStringValueParser::new().try_map(|s: String| crate::patchname::parse_user(&s))
}

fn locator_parser() -> impl TypedValueParser<Value = String> {
    NonEmptyStringValueParser::new().try_map(|s: String| {
        if s.contains("..") || s.contains(':') && !s.starts_with("{base}") {
            Err(format!("invalid patch locator `{s}`"))
        } else {
            Ok(s)
        }
    })
}

fn revision_parser() -> impl TypedValueParser<Value = String> {
    NonEmptyStringValueParser::new().try_map(|s: String| crate::revspec::validate_syntax(&s).map(|_| s))
}

fn i64_parser() -> impl TypedValueParser<Value = i64> {
    NonEmptyStringValueParser::new().try_map(|s: String| s.parse::<i64>().map_err(|e| e.to_string()))
}

fn usize_parser() -> impl TypedValueParser<Value = usize> {
    NonEmptyStringValueParser::new().try_map(|s: String| s.parse::<usize>().map_err(|e| e.to_string()))
}

fn date_parser() -> impl TypedValueParser<Value = String> {
    NonEmptyStringValueParser::new().try_map(|s: String| {
        if crate::timefmt::parse_date(&s).is_some() {
            Ok(s)
        } else {
            Err(format!("invalid date `{s}`"))
        }
    })
}

fn name_email_parser() -> impl TypedValueParser<Value = String> {
    NonEmptyStringValueParser::new().try_map(|s: String| {
        if crate::edit::parse_name_email(&s).is_some() {
            Ok(s)
        } else {
            Err(format!("invalid name and email `{s}`"))
        }
    })
}

fn has(cmd: &Command, id: &str) -> bool {
    cmd.get_arguments().any(|a| a.get_id() == id)
}

fn m(cmd: Command, id: &str, f: impl FnOnce(Arg) -> Arg) -> Command {
    if has(&cmd, id) {
        cmd.mut_arg(id, f)
    } else {
        cmd
    }
}

fn conflicts_policy(cmd: Command) -> Command {
    m(cmd, "conflicts", |a| a.value_parser(PossibleValuesParser::new(["allow", "disallow"])).hide_possible_values(true).default_missing_value("allow"))
}

/// Patch-edit options shared by new, edit, refresh, squash, import.
fn edit_opts(cmd: Command) -> Command {
    let cmd = m(cmd, "message", |a| a.value_parser(NonEmptyStringValueParser::new()));
    let cmd = m(cmd, "file", |a| a.value_parser(NonEmptyStringValueParser::new()));
    let has_tmpl = has(&cmd, "save-template");
    let cmd = if has_tmpl {
        let cmd = m(cmd, "message", |a| a.conflicts_with_all(["file", "save-template"]));
        m(cmd, "file", |a| a.conflicts_with("save-template"))
    } else {
        m(cmd, "message", |a| a.conflicts_with("file"))
    };
    let cmd = m(cmd, "signoff", |a| a.action(ArgAction::Append));
    let cmd = m(cmd, "ack", |a| a.action(ArgAction::Append));
    let cmd = m(cmd, "review", |a| a.action(ArgAction::Append));
    let cmd = m(cmd, "author", |a| a.value_parser(name_email_parser()).conflicts_with_all(["authname", "authemail"]));
    let cmd = m(cmd, "authdate", |a| a.value_parser(date_parser()));
    cmd
}

fn refresh_opts(cmd: Command) -> Command {
    let cmd = m(cmd, "index", |a| a.conflicts_with("force"));
    m(cmd, "submodules", |a| a.conflicts_with("no-submodules"))
}

pub fn apply(cmd: Command) -> Command {
    let name = cmd.get_name().to_string();
    let cmd = match name.as_str() {
        "new" => {
            let cmd = edit_opts(refresh_opts(cmd));
            let cmd = m(cmd, "patchname", |a| a.value_parser(patchname_parser()));
            let cmd = m(cmd, "name", |a| a.value_parser(patchname_parser()).conflicts_with("patchname"));
            m(cmd, "path", |a| a.last(true))
        }
        "edit" => {
            let cmd = edit_opts(cmd);
            m(cmd, "patch", |a| a.value_parser(locator_parser()).allow_hyphen_values(true))
        }
        "refresh" => {
            let cmd = edit_opts(refresh_opts(cmd));
            let cmd = conflicts_policy(cmd);
            let cmd = m(cmd, "update", |a| a.conflicts_with("index"));
            let cmd = m(cmd, "index", |a| a.conflicts_with("path"));
            m(cmd, "patch", |a| a.value_parser(locator_parser()))
        }
        "series" => {
            let cmd = m(cmd, "patch", |a| a.allow_hyphen_values(true));
            let cmd = m(cmd, "all", |a| a.conflicts_with_all(["applied", "unapplied", "hidden", "patch", "short"]));
            let cmd = m(cmd, "short", |a| {
                a.value_parser(NonEmptyStringValueParser::new().try_map(|s: String| {
                    s.parse::<usize>().map_err(|_| format!("'{s}' is not a positive integer"))
                }))
                .conflicts_with_all(["patch", "applied", "unapplied", "hidden"])
            });
            let cmd = m(cmd, "applied", |a| a.conflicts_with("patch"));
            let cmd = m(cmd, "unapplied", |a| a.conflicts_with("patch"));
            let cmd = m(cmd, "hidden", |a| a.conflicts_with("patch"));
            let cmd = m(cmd, "count", |a| {
                a.conflicts_with_all(["description", "author", "commit-id", "empty", "no-prefix", "indices", "offsets", "reverse", "showbranch"])
            });
            m(cmd, "commit-id", |a| {
                a.value_parser(NonEmptyStringValueParser::new().try_map(|s: String| {
                    if s == "full" {
                        return Ok(s);
                    }
                    match s.parse::<usize>() {
                        Ok(n) if n >= 4 => Ok(s),
                        _ => Err("length must be \"full\" or an integer greater than or equal to 4".to_string()),
                    }
                }))
                .default_missing_value("full")
            })
        }
        "push" => {
            let cmd = conflicts_policy(cmd);
            let cmd = m(cmd, "all", |a| a.conflicts_with_all(["patch", "number"]));
            let cmd = m(cmd, "number", |a| a.value_parser(i64_parser()).allow_negative_numbers(true).conflicts_with("patch"));
            m(cmd, "noapply", |a| a.conflicts_with("set-tree"))
        }
        "pop" => {
            let cmd = m(cmd, "all", |a| a.conflicts_with_all(["patch"]));
            m(cmd, "number", |a| a.value_parser(i64_parser()).allow_negative_numbers(true).conflicts_with_all(["patch", "all"]))
        }
        "goto" => {
            let cmd = conflicts_policy(cmd);
            m(cmd, "patch", |a| a.value_parser(locator_parser()).allow_hyphen_values(true))
        }
        "delete" => {
            let cmd = conflicts_policy(cmd);
            let cmd = m(cmd, "patch", |a| a.allow_hyphen_values(true));
            let cmd = m(cmd, "all", |a| a.conflicts_with_all(["patch", "applied", "unapplied", "hidden", "top"]));
            m(cmd, "top", |a| a.conflicts_with_all(["patch", "applied", "unapplied", "hidden"]))
        }
        "id" | "name" | "files" => m(cmd, "revision", |a| a.value_parser(revision_parser()).allow_hyphen_values(true)),
        "rename" => {
            m(cmd, "patches", |a| a.allow_hyphen_values(true))
        }
        _ => cmd,
    };
    // Recurse into subcommands.
    let subs: Vec<String> = cmd.get_subcommands().map(|c| c.get_name().to_string()).collect();
    let mut cmd = cmd;
    for s in subs {
        cmd = cmd.mut_subcommand(s, apply);
    }
    let _ = usize_parser;
    cmd
}
