use crate::stack::{InitPolicy, Stack};
use clap::ArgMatches;

#[derive(Clone, Copy, PartialEq)]
enum Kind {
    Applied,
    Top,
    Unapplied,
    Hidden,
}

pub fn run(m: &ArgMatches) -> Result<()> {
    let repo = Repo::open()?;
    let branch = super::s(m, "branch");
    let stack = Stack::from_branch(&repo, branch.as_deref(), InitPolicy::AllowUninitialized)?;
    let applied = stack.applied().clone();
    let unapplied = stack.unapplied().clone();
    let hidden = stack.hidden().clone();
    let top = applied.last().cloned();

    let kind_of = |n: &str| -> Kind {
        if Some(n) == top.as_deref() {
            Kind::Top
        } else if applied.iter().any(|x| x == n) {
            Kind::Applied
        } else if unapplied.iter().any(|x| x == n) {
            Kind::Unapplied
        } else {
            Kind::Hidden
        }
    };

    let all: Vec<String> = applied.iter().chain(unapplied.iter()).chain(hidden.iter()).cloned().collect();
    let patch_args = super::many(m, "patch");
    let mut selected: Vec<String>;
    if let Some(other) = super::s(m, "missing") {
        let ostack = Stack::from_branch(&repo, Some(&other), InitPolicy::AllowUninitialized)?;
        let oall: Vec<String> = ostack.state.all_patches().cloned().collect();
        let base_sel: Vec<String> = if !patch_args.is_empty() {
            revspec::patch_ranges(&patch_args, &oall, &oall)?
        } else {
            let mut v: Vec<String> = ostack.applied().iter().chain(ostack.unapplied().iter()).cloned().collect();
            if super::flag(m, "all") {
                v.extend(ostack.hidden().iter().cloned());
            }
            v
        };
        selected = base_sel.into_iter().filter(|n| !all.contains(n)).collect();
        return print_series(&repo, &ostack, m, &selected, &|_n: &str| Kind::Unapplied, true);
    }
    if !patch_args.is_empty() {
        selected = revspec::patch_ranges(&patch_args, &all, &all)?;
    } else if super::flag(m, "all") {
        selected = all.clone();
    } else if present_short(m) {
        let n: usize = match m.get_one::<usize>("short") {
            Some(n) => *n,
            None => repo.config.get_i64("stgit.shortnr").map(|v| v.max(0) as usize).unwrap_or(5),
        };
        selected = Vec::new();
        if !applied.is_empty() {
            let start = applied.len().saturating_sub(n + 1);
            selected.extend(applied[start..].iter().cloned());
            selected.extend(unapplied.iter().take(n).cloned());
        } else {
            selected.extend(unapplied.iter().take(n).cloned());
        }
    } else {
        let (a, u, h) = (super::flag(m, "applied"), super::flag(m, "unapplied"), super::flag(m, "hidden"));
        selected = Vec::new();
        if !a && !u && !h {
            selected.extend(applied.iter().cloned());
            selected.extend(unapplied.iter().cloned());
        } else {
            if a {
                selected.extend(applied.iter().cloned());
            }
            if u {
                selected.extend(unapplied.iter().cloned());
            }
            if h {
                selected.extend(hidden.iter().cloned());
            }
        }
    }
    print_series(&repo, &stack, m, &selected, &kind_of, false)
}

fn present_short(m: &ArgMatches) -> bool {
    m.value_source("short") == Some(clap::parser::ValueSource::CommandLine)
}

fn print_series(repo: &Repo, stack: &Stack, m: &ArgMatches, selected: &[String], kind_of: &dyn Fn(&str) -> Kind, _missing: bool) -> Result<()> {
    if super::flag(m, "count") {
        println!("{}", selected.len());
        return Ok(());
    }
    let mut sel: Vec<String> = selected.to_vec();
    if super::flag(m, "reverse") {
        sel.reverse();
    }
    let applied = stack.applied();
    let all: Vec<String> = stack.state.all_patches().cloned().collect();
    let show_empty = super::flag(m, "empty");
    let no_prefix = super::flag(m, "no-prefix");
    let indices = super::flag(m, "indices");
    let offsets = super::flag(m, "offsets");
    let author = super::flag(m, "author");
    let descr = super::flag(m, "description");
    let showbranch = super::flag(m, "showbranch");
    let commit_id: Option<Option<usize>> = super::s(m, "commit-id").map(|v| if v == "full" { None } else { v.parse::<usize>().ok() });

    let idx_of = |n: &str| all.iter().position(|x| x == n).unwrap_or(0) as i64;
    let top_idx: i64 = applied.len() as i64 - 1;
    let offset_of = |n: &str| -> i64 {
        let i = idx_of(n);
        if applied.is_empty() {
            i + 1
        } else {
            i - top_idx
        }
    };
    let idx_width = sel.iter().map(|n| idx_of(n).to_string().len()).max().unwrap_or(1);
    let fmt_off = |o: i64| if o < 0 { format!("{o}") } else { format!("+{o}") };
    let off_width = sel.iter().map(|n| fmt_off(offset_of(n)).len()).max().unwrap_or(1);
    let display_name = |n: &str| if showbranch { format!("{}:{}", stack.branch, n) } else { n.to_string() };
    let name_width = sel.iter().map(|n| display_name(n).chars().count()).max().unwrap_or(0);

    let mut out = Out::stdout();
    for n in &sel {
        let kind = kind_of(n);
        let commit = stack.patch_commit(n)?;
        if show_empty {
            let parent_tree = match commit.parents.first() {
                Some(p) => repo.commit(p)?.tree.clone(),
                None => String::new(),
            };
            out.write(if parent_tree == commit.tree { "*" } else { " " });
        }
        if !no_prefix {
            let (mark, spec) = match kind {
                Kind::Top => ("> ", Spec::fg(Color::Blue)),
                Kind::Applied => ("+ ", Spec::fg(Color::Green)),
                Kind::Unapplied => ("- ", Spec::fg(Color::Magenta)),
                Kind::Hidden => ("! ", Spec::fg(Color::Red)),
            };
            out.colored(spec, mark);
        }
        if indices {
            out.write(&format!("{:>w$} ", idx_of(n), w = idx_width));
        }
        if offsets {
            out.write(&format!("{:>w$} ", fmt_off(offset_of(n)), w = off_width));
        }
        if let Some(len) = commit_id {
            let id = match len {
                Some(l) => commit.id[..l.min(commit.id.len())].to_string(),
                None => commit.id.clone(),
            };
            out.write(&format!("{id} "));
        }
        let name_spec = match kind {
            Kind::Top => Spec::plain().bold(),
            Kind::Applied => Spec::plain(),
            Kind::Unapplied => Spec::plain().dimmed(),
            Kind::Hidden => Spec::plain().dimmed().italic(),
        };
        let dn = display_name(n);
        let padded = if author || descr { format!("{:<w$}", dn, w = name_width) } else { dn };
        out.colored(name_spec, &padded);
        if author {
            out.write(&format!(" # {}", commit.author.name));
        }
        if descr {
            let d = commit.summary();
            if d.is_empty() {
                out.write(" #");
            } else {
                out.write(&format!(" # {d}"));
            }
        }
        out.write("\n");
    }
    out.flush();
    let _ = Error::new("");
    Ok(())
}
