pub fn commit_files(repo: &Repo, oid: &str) -> Result<Vec<String>> {
    let c = repo.commit(oid)?;
    let parent_tree = match c.parents.first() {
        Some(p) => repo.commit(p)?.tree.clone(),
        None => crate::git::EMPTY_TREE.to_string(),
    };
    let out = repo.git(["diff-tree", "-r", "--name-only", "-z", "--no-renames", &parent_tree, &c.tree]).run_ok()?;
    Ok(out.stdout.split(|&b| b == 0).filter(|s| !s.is_empty()).map(|s| String::from_utf8_lossy(s).into_owned()).collect())
}

/// Update the index from the worktree as requested and return the resulting tree.
pub fn compute_refresh_tree(repo: &Repo, stack: &Stack, o: &RefreshTreeOpts, patch: Option<&str>) -> Result<Oid> {
    if o.index {
        return repo.write_index_tree(None);
    }
    let head_tree = repo.commit(&stack.branch_head)?.tree.clone();
    repo.update_index_refresh();
    if o.paths.is_empty() && !o.force && !o.update {
        let index_dirty = repo.index_differs_from(&head_tree)?;
        let wt_dirty = repo.worktree_differs()?;
        if index_dirty && wt_dirty {
            return Err(Error::new("the index is dirty; consider using `--index` or `--force`"));
        }
    }
    let mut args: Vec<String> = vec!["add".into(), "-u".into()];
    if !o.submodules {
        args.push("--ignore-errors".into());
    }
    args.pop();
    if o.update {
        let files = match patch {
            Some(p) => {
                let oid = stack.patch_oid(p).cloned().unwrap_or_default();
                commit_files(repo, &oid)?
            }
            None => Vec::new(),
        };
        if files.is_empty() {
            return repo.write_index_tree(None);
        }
        args.push("--".into());
        args.extend(files);
        repo.git(&args).run_ok()?;
    } else if o.paths.is_empty() {
        repo.git(&args).run_ok()?;
    } else {
        args.push("--".into());
        args.extend(o.paths.iter().cloned());
        crate::git::git(&args).run_ok()?;
    }
    repo.write_index_tree(None)
}

pub fn run(m: &ArgMatches) -> Result<()> {
    let repo = Repo::open()?;
    let stack = Stack::from_branch(&repo, None, InitPolicy::AllowUninitialized)?;
    if stack.applied().is_empty() {
        return Err(Error::new("no patches applied"));
    }
    if !repo.conflicts()?.is_empty() {
        return Err(Error::new("resolve outstanding conflicts first"));
    }
    stack.check_head_top()?;
    let eo = EditOpts::from_matches(m);
    let target = match super::s(m, "patch") {
        Some(p) => {
            let name = super::goto::resolve_locator_name(&stack, &p)?;
            if !stack.applied().contains(&name) {
                return Err(Error::new(format!("patch `{name}` is not applied")));
            }
            name
        }
        None => stack.applied().last().unwrap().clone(),
    };
    let ro = RefreshTreeOpts {
        index: super::flag(m, "index"),
        force: super::flag(m, "force"),
        paths: super::many(m, "path"),
        submodules: super::flag(m, "submodules"),
        update: super::flag(m, "update"),
    };
    let tree = compute_refresh_tree(&repo, &stack, &ro, Some(&target))?;
    let annotate = super::s(m, "annotate");
    let allow_conflicts = super::allow_conflicts(&repo, m)?;

    // Transaction 1: create temporary patch.
    let temp_name = patchname::uniquify("refresh-temp", &|n: &str| stack.state.has_patch(n));
    let author = repo.author()?;
    let committer = repo.committer()?;
    let temp_commit = NewCommit {
        tree: tree.clone(),
        parents: vec![stack.branch_head.clone()],
        author,
        committer,
        extra_headers: vec![],
        message: format!("Refresh of {target}").into_bytes(),
    };
    let temp_oid = repo.write_commit(&temp_commit)?;
    let opts = TransOpts { no_clean_check: true, allow_conflicts, ..Default::default() };
    let mut trans = Transaction::new(stack, opts.clone())?;
    trans.set_current_tree(&tree);
    trans.new_applied(&temp_name, &temp_oid);
    let mut msg1 = format!("refresh {temp_name} (create temporary patch)");
    if let Some(a) = &annotate {
        msg1 = format!("{msg1}\n\n{a}");
    }
    trans.execute(&msg1)?;

    // Transaction 2: fold the temporary patch into the target.
    let stack = Stack::from_branch(&repo, None, InitPolicy::AllowUninitialized)?;
    let mut trans = Transaction::new(stack, opts)?;
    trans.set_current_tree(&tree);
    let applied = trans.applied.clone();
    let tpos = applied.iter().position(|n| *n == target).unwrap();
    let mut to_push: Vec<String> = Vec::new();
    if tpos + 2 != applied.len() {
        // target is not directly below the temp patch
        let above: Vec<String> = applied[tpos + 1..].to_vec();
        let first = above[0].clone();
        let popped = trans.pop_patches(|n| n == first);
        to_push = popped.into_iter().filter(|n| *n != temp_name).collect();
        trans.push_patch(&temp_name, false)?;
        if trans.halted {
            return trans.execute(&format!("refresh {target}"));
        }
