        let idx = all.len() as i64 - 1 - n;
        if idx < 0 || all.is_empty() {
            return Err(Error::new(format!("no patch at -{n} from last patch")));
        }
        (B::Idx(idx, all[idx as usize].clone()), r2)
    } else if spec.starts_with('-') && spec[1..].chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false) {
