        if applied.is_empty() {
            return Err(Error::new(format!("no patch at `-{n}` from topmost patch")));
        }
        let idx = applied.len() as i64 - 1 - n;
        if idx < 0 {
            return Err(Error::new(format!("no patch at `-{n}` from topmost patch")));
        }
        (B::Idx(idx, applied[idx as usize].clone()), r2)
    } else if spec.starts_with(|c: char| c.is_ascii_digit()) {
