            return Err(Error::new(format!("invalid patch index `{n}`")));
        }
        (B::Idx(n, format!("stack index `{n}`")), r2)
    } else if spec.starts_with(['~', '+']) {
        (B::Top, spec)
    } else {
        let cut = spec.find(['~', '+', '^']).unwrap_or(spec.len());
        let name = &spec[..cut];
        match all.iter().position(|n| n == name) {
            Some(i) => (B::Idx(i as i64, format!("`{name}`")), &spec[cut..]),
            None => return Err(Error::new(not_found_msg_all(spec, &all))),
