    let mut r = rest;
    let mut any = false;
    while !r.is_empty() {
        let c = r.chars().next().unwrap();
        let (n, r2) = parse_num_prefix(&r[1..]);
        match c {
            '+' => total += n.unwrap_or(1),
            '~' | '^' => total -= n.unwrap_or(1),
