use crate::error::{Error, Result};
use crate::repo::Repo;
use crate::revspec;
use crate::stack::{InitPolicy, Stack};
use crate::trans::{TransOpts, Transaction};
use clap::ArgMatches;

/// Push patches, checking whether each patch is already merged in the new base.
pub fn push_merged(trans: &mut Transaction, names: &[String]) -> Result<()> {
    // Determine which patches are already merged by reverse-applying them.
    let repo = trans.repo;
    let mut merged: Vec<String> = Vec::new();
    let top_tree = repo.commit(&trans.top_oid())?.tree.clone();
    let idx = repo.git_dir.join(format!("index.stg-merged-{}", std::process::id()));
    repo.read_tree_into(&top_tree, Some(&idx))?;
    for n in names.iter().rev() {
        let c = trans.patch_commit(n)?;
        let ptree = match c.parents.first() {
            Some(p) => repo.commit(p)?.tree.clone(),
            None => continue,
        };
        let diff = repo.git(["diff-tree", "--full-index", "--binary", "-p", &ptree, &c.tree, "--"]).run_ok()?;
        if diff.stdout.is_empty() {
            continue;
        }
        let out = repo.git(["apply", "--cached", "--reverse"]).index(Some(&idx)).stdin(&diff.stdout).run()?;
        if out.ok() {
            merged.push(n.clone());
        }
    }
    let _ = std::fs::remove_file(&idx);
    for n in names {
        if trans.halted {
            break;
        }
