            Some(t) => vec![t.clone()],
            None => return Err(Error::new("no patches applied")),
        }
    } else if super::flag(m, "applied") || super::flag(m, "unapplied") || super::flag(m, "hidden") {
        let mut v = Vec::new();
        if super::flag(m, "applied") {
            v.extend(applied.iter().cloned());
        }
        if super::flag(m, "unapplied") {
            v.extend(unapplied.iter().cloned());
        }
        if super::flag(m, "hidden") {
            v.extend(hidden.iter().cloned());
        }
        v
    } else {
        revspec::patch_ranges(&super::many(m, "patch"), &all, applied.len())?
    };
