pub struct Resolved {
    pub oid: Oid,
    pub branch: Option<String>,
}

/// Resolve a StGit revision to an object id.
pub fn resolve(repo: &Repo, spec: Option<&str>, branch: Option<&str>) -> Result<Oid> {
    Ok(resolve_full(repo, spec, branch, false)?.oid)
}

pub fn resolve_commit(repo: &Repo, spec: Option<&str>, branch: Option<&str>) -> Result<Oid> {
    Ok(resolve_full(repo, spec, branch, true)?.oid)
}

pub fn resolve_full(repo: &Repo, spec: Option<&str>, branch: Option<&str>, peel: bool) -> Result<Resolved> {
    let spec = match spec {
        None | Some("") => {
            return match branch {
                Some(b) => {
                    let st = Stack::from_branch(repo, Some(b), InitPolicy::AllowUninitialized)?;
                    Ok(Resolved { oid: st.branch_head.clone(), branch: Some(st.branch.clone()) })
                }
                None => {
                    let oid = repo.head_oid().ok_or_else(|| Error::new("HEAD does not point to a commit"))?;
                    Ok(Resolved { oid, branch: repo.head_branch() })
                }
            }
        }
        Some(s) => s,
    };
    let (prefix_branch, rest) = match spec.find(':') {
        Some(i) if i > 0 => (Some(&spec[..i]), &spec[i + 1..]),
        _ => (None, spec),
    };
    let stack = match prefix_branch.or(branch) {
        Some(b) => Some(Stack::from_branch(repo, Some(b), InitPolicy::AllowUninitialized)?),
        None => Stack::from_branch(repo, None, InitPolicy::AllowUninitialized).ok(),
    };
    let bname = stack.as_ref().map(|s| s.branch.clone());
    let finish = |oid: Oid, suffix: &str| -> Result<Resolved> {
        let oid = if suffix.is_empty() {
            if peel {
                repo.rev_parse_commit(&oid).unwrap_or(oid)
            } else {
                oid
            }
        } else {
            let sp = format!("{oid}{suffix}");
            let r = if peel { repo.rev_parse_commit(&sp) } else { repo.rev_parse(&sp) };
            r.ok_or_else(|| Error::new(format!("invalid StGit revision `{sp}`")))?
        };
        Ok(Resolved { oid, branch: bname.clone() })
    };
    let mut locate_err: Option<Error> = None;
