                commits.push(o.clone());
            } else {
                let oid = revspec::resolve(&repo, Some(sp), branch.as_deref())?;
                commits.push(oid);
            }
        }
    }
    let mut args: Vec<String> = vec!["show".into()];
    if color::use_color(1) {
        args.push("--color=always".into());
