        args.push("--stat".into());
        args.push("--summary".into());
    }
    args.extend(super::many(m, "diff-opt"));
    args.extend(commits);
    let paths = super::many(m, "path");
    args.push("--".into());
    args.extend(paths);
    let out = repo.git(&args).cwd(&repo.cwd).run()?;
    use std::io::Write;
