use crate::color;
use crate::error::{Error, Result};
use crate::repo::Repo;
use crate::revspec;
use crate::stack::{InitPolicy, Stack};
use clap::ArgMatches;

pub fn run(m: &ArgMatches) -> Result<()> {
    let repo = Repo::open()?;
    let branch = super::s(m, "branch");
    let stack = Stack::from_branch(&repo, branch.as_deref(), InitPolicy::AllowUninitialized)?;
    let all: Vec<String> = stack.state.all_patches().cloned().collect();
    let mut specs = super::many(m, "patch-or-rev");
    specs.extend(super::many(m, "patch"));
    let mut commits: Vec<String> = Vec::new();
    let (a, u, h) = (super::flag(m, "applied"), super::flag(m, "unapplied"), super::flag(m, "hidden"));
    if a || u || h {
        let mut names = Vec::new();
        if a {
            names.extend(stack.applied().iter().cloned());
        }
        if u {
            names.extend(stack.unapplied().iter().cloned());
        }
        if h {
            names.extend(stack.hidden().iter().cloned());
        }
        for n in names {
            commits.push(stack.patch_oid(&n).unwrap().clone());
        }
    } else if specs.is_empty() {
        commits.push(stack.branch_head.clone());
    } else {
        for sp in &specs {
            if sp.contains("..") {
                let names = revspec::patch_ranges(&[sp.clone()], &all, stack.applied().len())?;
                for n in names {
                    commits.push(stack.patch_oid(&n).unwrap().clone());
                }
            } else if let Some(o) = stack.patch_oid(sp) {
                commits.push(o.clone());
            } else {
                let oid = revspec::resolve(&repo, Some(sp), branch.as_deref())?;
                commits.push(oid);
            }
        }
    }
    let mut args: Vec<String> = vec!["show".into()];
    if color::use_color(1) {
        args.push("--color=always".into());
    }
    if super::flag(m, "stat") {
        args.push("--stat".into());
        args.push("--summary".into());
    }
    args.extend(super::many(m, "diff-opt"));
    args.extend(commits);
    let paths = super::many(m, "path");
    args.push("--".into());
    args.extend(paths);
    let out = repo.git(&args).cwd(&repo.cwd).run()?;
    use std::io::Write;
    let _ = std::io::stdout().write_all(&out.stdout);
    if !out.ok() {
        return Err(Error::new(format!("`git show`: {}", out.stderr_str().trim_end())));
    }
    Ok(())
}
