pub fn run(m: &ArgMatches) -> Result<()> {
    let repo = Repo::open()?;
    let mut revs: Vec<String> = Vec::new();
    if let Some(r) = super::s(m, "range") {
        match r.split_once("..") {
            Some((a, b)) => {
                if a.is_empty() {
                    let b_oid = revspec::resolve(&repo, Some(b), None)?;
                    let parent = format!("{b_oid}^");
                    let p = repo.rev_parse(&parent).ok_or_else(|| Error::new(format!("invalid StGit revision `{parent}`")))?;
                    revs.push(p);
                    revs.push(b_oid);
                } else {
                    revs.push(revspec::resolve(&repo, Some(a), None)?);
                    if b.is_empty() {
                        revs.push(revspec::resolve(&repo, Some("HEAD"), None)?);
                    } else {
                        revs.push(revspec::resolve(&repo, Some(b), None)?);
                    }
                }
            }
            None => revs.push(revspec::resolve(&repo, Some(&r), None)?),
        }
    } else {
        revs.push("HEAD".into());
    }
    let mut args: Vec<String> = vec!["diff".into()];
    if color::use_color(1) {
        args.push("--color=always".into());
    }
    if super::flag(m, "stat") {
        args.push("--stat".into());
        args.push("--summary".into());
    }
    args.extend(super::many(m, "diff-opt"));
    args.extend(revs);
    args.push("--".into());
    args.extend(super::many(m, "path"));
    let out = repo.git(&args).cwd(&repo.cwd).run()?;
    use std::io::Write;
    let _ = std::io::stdout().write_all(&out.stdout);
    if !out.ok() {
        return Err(Error::new(format!("`git diff`: {}", out.stderr_str().trim_end())));
    }
    Ok(())
}
