use crate::error::{Error, Result};
use crate::patchname;
use crate::repo::Repo;
use crate::stack::{InitPolicy, Stack};
use crate::trans::{TransOpts, Transaction};
use clap::ArgMatches;

pub fn usage_error(msg: &str, usage: &str) -> Error {
    eprint!("error: {msg}\n\nUsage: {usage}\n\nFor more information, try '--help'.\n");
    Error::silent(1)
}

pub fn run(m: &ArgMatches) -> Result<()> {
    let repo = Repo::open()?;
    let branch = super::s(m, "branch");
    let args = super::many(m, "patches");
    let usage = "stg rename [OPTIONS] [old-patch] <new-patch>";
    let (old_arg, new_arg) = if args.len() == 2 { (Some(args[0].clone()), args[1].clone()) } else { (None, args[0].clone()) };
    if let Some(o) = &old_arg {
        if patchname::check(o).is_err() && !o.starts_with(['~', '+', '^', '@']) && !o.chars().all(|c| c.is_ascii_digit()) {
            return Err(usage_error(&format!("invalid value '{o}' for '[<old-patch>]': invalid patch locator `{o}`"), usage));
        }
    }
    let new_name = match patchname::parse_user(&new_arg) {
        Ok(n) => n,
        Err(e) => return Err(usage_error(&format!("invalid value '{new_arg}' for '<new-patch>': {e}"), usage)),
    };
    let stack = Stack::from_branch(&repo, branch.as_deref(), InitPolicy::AllowUninitialized)?;
    let old = match old_arg {
        Some(o) => super::goto::resolve_locator_name(&stack, &o)?,
        None => match stack.applied().last() {
            Some(t) => t.clone(),
            None => return Err(Error::new("no patches applied")),
        },
    };
    if stack.state.has_patch(&new_name) {
        return Err(Error::new(format!("patch `{new_name}` already exists")));
    }
    let other_branch = branch.is_some() && repo.head_branch().as_deref() != branch.as_deref();
    let opts = TransOpts { no_checkout: true, allow_bad_head: other_branch, no_clean_check: true, ..Default::default() };
    let mut trans = Transaction::new(stack, opts)?;
    trans.rename_patch(&old, &new_name);
    println!("{old} => {new_name}");
    trans.execute(&format!("rename {old} {new_name}"))
}
