use crate::edit::{self, EditOpts};
use crate::error::{Error, Result};
use crate::git::NewCommit;
use crate::patchname;
use crate::repo::Repo;
use crate::revspec;
use crate::stack::{InitPolicy, Stack};
use crate::trans::{TransOpts, Transaction};
use clap::ArgMatches;

/// Diff of a commit against its parent, as shown in the edit template.
pub fn patch_diff(repo: &Repo, oid: &str) -> Result<Vec<u8>> {
    let c = repo.commit(oid)?;
    let parent_tree = match c.parents.first() {
        Some(p) => repo.commit(p)?.tree.clone(),
        None => crate::git::EMPTY_TREE.to_string(),
    };
    let out = repo.git(["diff-tree", "-p", "--full-index", "--binary", "--no-color", &parent_tree, &c.tree, "--"]).run_ok()?;
    Ok(out.stdout)
}

pub fn run(m: &ArgMatches) -> Result<()> {
    let repo = Repo::open()?;
    let stack = Stack::from_branch(&repo, None, InitPolicy::AllowUninitialized)?;
    let name = match super::s(m, "patch") {
        Some(p) => super::goto::resolve_locator_name(&stack, &p)?,
        None => match stack.applied().last() {
            Some(t) => t.clone(),
            None => return Err(Error::new("no patches applied")),
        },
    };
    let eo = EditOpts::from_matches(m);
    let set_tree = super::s(m, "set-tree");
    let commit = stack.patch_commit(&name)?;
    let mut author = commit.author.clone();
    eo.apply_author(&mut author)?;
    let mut message = commit.message_str();
    let mut tree = commit.tree.clone();
    if let Some(t) = &set_tree {
        let oid = revspec::resolve(&repo, Some(t), None)?;
        let spec = format!("{oid}^{{tree}}");
        tree = repo.rev_parse(&spec).ok_or_else(|| Error::new(format!("invalid treeish `{t}`")))?;
    }
    if let Some(msg) = eo.read_message()? {
        message = edit::cleanup_message(&msg, false);
    }
    message = eo.apply_trailers(&repo, &message)?;

    let any_opt = eo.message.is_some()
        || eo.file.is_some()
        || !eo.trailers.is_empty()
        || eo.author.is_some()
        || eo.authname.is_some()
        || eo.authemail.is_some()
        || eo.authdate.is_some()
        || set_tree.is_some()
        || eo.committer_date_is_author_date;
    let mut new_name = name.clone();
    if let Some(path) = &eo.save_template {
        let diff = if eo.diff { Some(patch_diff(&repo, &commit.id)?) } else { None };
        let t = edit::make_template(&name, &author, &message, diff.as_deref());
        if path == "-" {
            use std::io::Write;
            let _ = std::io::stdout().write_all(&t);
        } else {
            std::fs::write(path, &t)?;
        }
        return Ok(());
    }
    if eo.edit || !any_opt {
        let orig_diff = if eo.diff { Some(patch_diff(&repo, &commit.id)?) } else { None };
        let t = edit::make_template(&name, &author, &message, orig_diff.as_deref());
        let edited = edit::edit_text(&repo, &String::from_utf8_lossy(&t))?;
        let parsed = edit::parse_edited(&edited)?;
        if let Some(n) = parsed.name {
            if !n.is_empty() && n != name {
                new_name = patchname::parse_user(&n).map_err(Error::new)?;
            }
        }
        if let Some((n, e)) = parsed.author_name_email {
            if n != author.name || e != author.email || parsed.date.is_some() {
                author.name = n;
                author.email = e;
                match parsed.date {
                    Some((t, o)) => {
                        author.time = t;
                        author.offset = o;
                    }
                    None => {
                        let now = crate::timefmt::now();
                        author.time = now;
                        author.offset = crate::timefmt::local_offset(now);
                    }
                }
            }
        }
        if parsed.message.trim().is_empty() {
            return Err(Error::new("aborting due to empty patch description"));
        }
        message = parsed.message;
        if let (Some(od), Some(nd)) = (&orig_diff, &parsed.diff) {
            if od != nd {
                let parent_tree = match commit.parents.first() {
                    Some(p) => repo.commit(p)?.tree.clone(),
                    None => crate::git::EMPTY_TREE.to_string(),
                };
                let idx = repo.git_dir.join(format!("index.stg-edit-{}", std::process::id()));
                repo.read_tree_into(&parent_tree, Some(&idx))?;
                let out = repo.git(["apply", "--cached"]).index(Some(&idx)).stdin(nd).run()?;
                if !out.ok() {
                    let _ = std::fs::remove_file(&idx);
                    std::fs::write(".stgit-failed.patch", &edited)?;
                    return Err(Error::new(format!(
                        "{}\nedited patch saved to `.stgit-failed.patch`",
                        out.stderr_str().trim_end()
                    )));
                }
                tree = repo.write_index_tree(Some(&idx))?;
                let _ = std::fs::remove_file(&idx);
            }
