    if let Some(pos) = trans.applied.iter().position(|n| *n == name) {
        if pos + 1 < trans.applied.len() && changed {
            let first = trans.applied[pos + 1].clone();
            to_push = trans.pop_patches(|n| n == first);
        }
    }
    if changed {
        let nc = NewCommit {
            tree,
            parents: commit.parents.clone(),
            author,
            committer,
            extra_headers: vec![],
            message: message.into_bytes(),
        };
        let oid = repo.write_commit(&nc)?;
        trans.update_patch(&name, &oid);
    }
    trans.push_patches(&to_push, false)?;
    trans.execute(&format!("edit: {name}"))
}
