}

/// Find the state `steps` undo steps back (negative for redo).
pub fn find_undo_target(repo: &Repo, stack: &Stack, mut steps: i64) -> Result<Oid> {
    let mut cur = stack.state_oid.clone().ok_or_else(|| Error::new("not enough undo information available"))?;
    let mut state = stack.state.clone();
    while steps != 0 {
