use crate::error::{Error, Result};
use crate::repo::Repo;
use crate::stack::{InitPolicy, Stack, StackState};
use crate::trans::{TransOpts, Transaction};
use clap::ArgMatches;

/// Reset the stack to `target` (optionally only some patches).
pub fn reset_to(repo: &Repo, stack: Stack, target: &StackState, only: Option<&[String]>, hard: bool, msg: &str) -> Result<()> {
    if !hard && !repo.conflicts()?.is_empty() {
        return Err(Error::new("resolve outstanding conflicts first"));
    }
    let opts = TransOpts { discard_changes: hard, allow_bad_head: true, no_clean_check: true, allow_existing_conflicts: true, ..Default::default() };
    let mut trans = Transaction::new(stack, opts)?;
    match only {
        None => {
            trans.applied = target.applied.clone();
            trans.unapplied = target.unapplied.clone();
            trans.hidden = target.hidden.clone();
            trans.patches = target.patches.clone();
            trans.base = match target.applied.first() {
                Some(p) => {
                    let c = repo.commit(&target.patches[p])?;
                    c.parents.first().cloned().unwrap_or(c.id.clone())
                }
                None => target.head.clone(),
            };
        }
        Some(names) => {
            let orig_applied = trans.applied.clone();
            let to_reset: Vec<String> = names.iter().filter(|n| target.patches.contains_key(*n)).cloned().collect();
            let to_delete: Vec<String> = names.iter().filter(|n| !target.patches.contains_key(*n) && trans.has_patch(n)).cloned().collect();
            let names_v: Vec<String> = names.to_vec();
            trans.pop_patches(|n| names_v.iter().any(|x| x == n));
            let del = to_delete.clone();
            trans.delete_patches(|n| del.iter().any(|x| x == n))?;
            for pn in &to_reset {
                if !trans.has_patch(pn) {
                    if target.hidden.contains(pn) {
                        trans.hidden.push(pn.clone());
                    } else {
                        trans.unapplied.push(pn.clone());
                    }
                }
                trans.set_patch_commit(pn, &target.patches[pn]);
            }
            let pushable: Vec<String> = trans.unapplied.iter().chain(trans.hidden.iter()).cloned().collect();
            let to_push: Vec<String> = orig_applied.into_iter().filter(|p| pushable.contains(p)).collect();
            trans.push_patches(&to_push, false)?;
        }
    }
    trans.execute(msg)
}

pub fn run(m: &ArgMatches) -> Result<()> {
    let repo = Repo::open()?;
    let stack = Stack::from_branch(&repo, None, InitPolicy::AllowUninitialized)?;
    let hard = super::flag(m, "hard");
    let committish = super::s(m, "committish");
    match committish {
        None => {
            if hard {
                let head_tree = repo.commit(&stack.branch_head)?.tree.clone();
                repo.git(["read-tree", "--reset", "-u", &head_tree]).run_ok()?;
                return Ok(());
            }
            Err(Error::new("missing committish"))
        }
        Some(c) => {
            let oid = repo.rev_parse_commit(&c).ok_or_else(|| Error::new(format!("invalid revision `{c}`")))?;
            let target = super::undo::read_state(&repo, &oid)?;
            let patches = super::many(m, "patch");
            if patches.is_empty() {
                reset_to(&repo, stack, &target, None, hard, "reset")
            } else {
                let all: Vec<String> = stack.state.all_patches().cloned().chain(target.patches.keys().cloned()).collect();
                for p in &patches {
                    if !all.contains(p) {
                        return Err(Error::new(format!("patch `{p}` does not exist")));
                    }
                }
                reset_to(&repo, stack, &target, Some(&patches), hard, "reset")
            }
        }
    }
}
