use crate::edit::{self, EditOpts};
use crate::error::{Error, Result};
use crate::git::{NewCommit, Oid};
use crate::patchname;
use crate::repo::Repo;
use crate::revspec;
use crate::stack::{InitPolicy, Stack};
use crate::trans::{TransOpts, Transaction};
use clap::ArgMatches;

/// Try to compute the squashed tree of `patches` (in order) without conflicts.
fn squash_tree(repo: &Repo, trans: &Transaction, patches: &[String]) -> Result<Option<Oid>> {
    let first = trans.patch_commit(&patches[0])?;
    let mut tree = first.tree.clone();
    let idx = repo.git_dir.join(format!("index.stg-squash-{}", std::process::id()));
    let mut ok = true;
    for p in &patches[1..] {
        let c = trans.patch_commit(p)?;
        let base = match c.parents.first() {
            Some(par) => repo.commit(par)?.tree.clone(),
            None => crate::git::EMPTY_TREE.to_string(),
        };
        if base == tree {
            tree = c.tree.clone();
            continue;
        }
        if base == c.tree {
            continue;
        }
        repo.read_tree_into(&tree, Some(&idx))?;
        let diff = repo.git(["diff-tree", "--full-index", "--binary", "-p", &base, &c.tree, "--"]).run_ok()?;
        let out = repo.git(["apply", "--cached"]).index(Some(&idx)).stdin(&diff.stdout).run()?;
        if !out.ok() {
            ok = false;
            break;
        }
        tree = repo.write_index_tree(Some(&idx))?;
    }
    let _ = std::fs::remove_file(&idx);
    Ok(if ok { Some(tree) } else { None })
}

pub fn run(m: &ArgMatches) -> Result<()> {
    let repo = Repo::open()?;
    let stack = Stack::from_branch(&repo, None, InitPolicy::AllowUninitialized)?;
    let all: Vec<String> = stack.state.all_patches().cloned().collect();
    let patches = revspec::patch_ranges(&super::many(m, "patch"), &all, stack.applied().len())?;
    if patches.len() < 2 {
        return Err(Error::new("need at least two patches"));
    }
    let eo = EditOpts::from_matches(m);
    let name_arg = super::s(m, "name");
    if let Some(n) = &name_arg {
        if stack.state.has_patch(n) && !patches.contains(n) {
            return Err(Error::new(format!("patch `{n}` already exists")));
        }
    }
    let opts = TransOpts { committer_date_is_author_date: eo.committer_date_is_author_date, ..Default::default() };
    let mut trans = Transaction::new(stack, opts)?;
    trans.check_worktree()?;
    let any_applied = patches.iter().any(|p| trans.applied.contains(p));

    // Build message
    let first = trans.patch_commit(&patches[0])?;
    let mut author = first.author.clone();
    eo.apply_author(&mut author)?;
    let msg_given = eo.read_message()?;
    let mut message = match &msg_given {
        Some(m) => edit::cleanup_message(m, false),
        None => {
            let mut s = String::new();
            for (i, p) in patches.iter().enumerate() {
                let c = trans.patch_commit(p)?;
                if i > 0 {
                    s.push('\n');
                }
                s.push_str(&format!("# Commit message from patch #{}: {}\n", i + 1, p));
                s.push_str(c.message_str().trim_end_matches('\n'));
                s.push('\n');
            }
            s
        }
    };
    message = eo.apply_trailers(&repo, &message)?;
    let mut name = name_arg.clone();
    if let Some(path) = &eo.save_template {
        let t = edit::make_template(name.as_deref().unwrap_or(""), &author, &message, None);
        if path == "-" {
            use std::io::Write;
            let _ = std::io::stdout().write_all(&t);
        } else {
            std::fs::write(path, &t)?;
        }
        crate::color::info(&format!("patch template saved to `{path}`"));
        return Ok(());
    }
    if msg_given.is_none() || eo.edit {
        let t = edit::make_template(name.as_deref().unwrap_or(""), &author, &message, None);
        let edited = edit::edit_text(&repo, &String::from_utf8_lossy(&t))?;
        let parsed = edit::parse_edited(&edited)?;
        if let Some(n) = parsed.name {
            if !n.is_empty() {
                name = Some(patchname::parse_user(&n).map_err(Error::new)?);
            }
        }
        if let Some((n, e)) = parsed.author_name_email {
            author.name = n;
            author.email = e;
            if let Some((t, o)) = parsed.date {
                author.time = t;
                author.offset = o;
            }
        }
        message = parsed.message;
        if message.trim().is_empty() {
            return Err(Error::new("aborting due to empty patch description"));
        }
    }
    if !eo.no_verify {
        message = edit::run_commit_msg_hook(&repo, &message)?;
    }

    let mut to_push: Vec<String>;
    let tree = match squash_tree(&repo, &trans, &patches)? {
        Some(t) => {
            let p = patches.clone();
            to_push = trans.delete_patches(|n| p.iter().any(|x| x == n))?;
            t
        }
        None => {
            let p = patches.clone();
            to_push = trans.pop_patches(|n| p.iter().any(|x| x == n));
            trans.push_patches(&patches, false)?;
            if trans.halted {
                return trans.execute("squash");
            }
            let t = squash_tree(&repo, &trans, &patches)?.ok_or_else(|| Error::new("squash failed"))?;
            let p = patches.clone();
            let extra = trans.delete_patches(|n| p.iter().any(|x| x == n))?;
            to_push.extend(extra);
            t
        }
    };
    let parent = trans.patch_parent_after_delete(&first)?;
    let parent = parent.unwrap_or_else(|| trans.top_oid());
    let name = match name {
        Some(n) => n,
        None => {
            let limit = super::new::name_len_limit(&repo);
            let taken: Vec<String> = trans.all_patches();
            patchname::make(&message, limit, &|n: &str| taken.iter().any(|x| x == n))
        }
    };
    let mut committer = repo.committer()?;
    if eo.committer_date_is_author_date {
        committer.time = author.time;
        committer.offset = author.offset;
    }
    let nc = NewCommit { tree, parents: vec![parent], author, committer, extra_headers: vec![], message: message.into_bytes() };
    let oid = repo.write_commit(&nc)?;
    trans.new_unapplied(&name, &oid, 0);
    trans.print_unapplied_new(&name);
    if any_applied {
        trans.push_patch(&name, false)?;
    }
    trans.push_patches(&to_push, false)?;
    trans.execute("squash")
}
