fn branch_exists(repo: &Repo, b: &str) -> bool {
    repo.ref_exists(&format!("refs/heads/{b}"))
}

fn check_ref_format(name: &str) -> bool {
    git(["check-ref-format", "--branch", name]).run().map(|o| o.ok()).unwrap_or(false) && !name.starts_with('-')
}

fn require_clean(repo: &Repo) -> Result<()> {
    let head = repo.head_oid().unwrap_or_default();
    let tree = repo.commit(&head)?.tree.clone();
    check_worktree(repo, &tree, &TransOpts::default())
