fn checkout(repo: &Repo, branch: &str, merge: bool) -> Result<()> {
    let mut args = vec!["checkout", "-q"];
    if merge {
        args.push("-m");
    }
    args.push(branch);
    let out = repo.git(&args).run()?;
    if !out.ok() {
        return Err(Error::new(format!("`git checkout`: {}", out.stderr_str().trim_end())));
    }
    Ok(())
}

fn resolve_branch_arg(repo: &Repo, b: &str) -> Result<String> {
    let spec = if b == "-" { "@{-1}".to_string() } else { b.to_string() };
    if spec.starts_with("@{-") {
        let out = git(["rev-parse", "--symbolic-full-name", &spec]).run()?;
        let s = out.stdout_str().trim().to_string();
        match s.strip_prefix("refs/heads/") {
            Some(n) if out.ok() => return Ok(n.to_string()),
            _ => return Err(Error::new(format!("`{b}` does not refer to a local branch"))),
        }
    }
    Ok(spec)
}

fn stack_refs(repo: &Repo, branch: &str) -> Vec<(String, String)> {
    let mut v = repo.list_refs(&format!("refs/patches/{branch}/"));
    if let Some(o) = repo.resolve_ref(&stack_refname(branch)) {
        v.push((stack_refname(branch), o));
    }
    v
}

fn has_patches(repo: &Repo, branch: &str) -> Result<bool> {
    let st = Stack::load(repo, branch, InitPolicy::AllowUninitialized)?;
    Ok(st.state.patches.len() > 0)
}

fn delete_stack_refs(repo: &Repo, branch: &str) -> Result<()> {
    for (r, _) in stack_refs(repo, branch) {
        repo.delete_ref(&r)?;
    }
    Ok(())
}

pub fn run(m: &ArgMatches) -> Result<()> {
    let repo = Repo::open()?;
    if let Some((sub, sm)) = m.subcommand() {
        return match sub {
            "--list" => list(&repo),
            "--create" => create(&repo, sm),
            "--clone" => clone(&repo, sm),
            "--rename" => rename(&repo, sm),
            "--protect" => protect(&repo, sm, true),
            "--unprotect" => protect(&repo, sm, false),
            "--delete" => delete(&repo, sm, false),
            "--cleanup" => delete(&repo, sm, true),
            "--describe" => describe(&repo, sm),
            _ => Err(Error::new("unknown branch subcommand")),
        };
    }
    match super::s(m, "branch") {
        None => {
            let b = repo.head_branch().ok_or_else(|| Error::new("not on branch, HEAD is detached"))?;
            println!("{b}");
            Ok(())
        }
        Some(b) => {
            let target = resolve_branch_arg(&repo, &b)?;
            let cur = repo.head_branch();
            if cur.as_deref() == Some(target.as_str()) {
                return Err(Error::new(format!("{target} is already the current branch")));
            }
            if !branch_exists(&repo, &target) {
                return Err(Error::new(format!("branch `{target}` not found")));
            }
            let merge = super::flag(m, "merge");
            if !merge {
                require_clean(&repo)?;
            }
            checkout(&repo, &target, merge)
        }
    }
