fn list(repo: &Repo) -> Result<()> {
    let branches: Vec<String> = repo
        .list_refs("refs/heads/")
        .into_iter()
        .map(|(r, _)| r["refs/heads/".len()..].to_string())
        .collect();
    let cur = repo.head_branch();
    let width = branches.iter().map(|b| b.chars().count()).max().unwrap_or(0);
    let mut out = color::Out::stdout();
    for b in &branches {
        let is_cur = cur.as_deref() == Some(b.as_str());
        let has_stack = repo.ref_exists(&stack_refname(b));
        let protected = repo.config.get_bool(&format!("branch.{b}.stgit.protect")).unwrap_or(false);
        let desc = repo.config.get(&format!("branch.{b}.description")).unwrap_or_default();
        if is_cur {
            out.colored(color::Spec::fg(color::Color::Blue), ">");
        } else {
            out.write(" ");
        }
        out.write(" ");
        out.write(if has_stack { "s" } else { " " });
        out.write(if protected { "p" } else { " " });
        out.write("\t");
        let padded = format!("{:<w$}", b, w = width);
        if is_cur {
            out.colored(color::Spec::plain().bold(), &padded);
        } else {
            out.write(&padded);
        }
        let line = format!("  | {desc}");
        out.write(line.trim_end());
        out.write("\n");
    }
    out.flush();
    Ok(())
}

fn set_config(repo: &Repo, key: &str, val: &str) -> Result<()> {
    repo.git(["config", key, val]).run_ok()?;
    Ok(())
}

fn unset_config(repo: &Repo, key: &str) {
    let _ = repo.git(["config", "--unset", key]).run();
}

fn create(repo: &Repo, m: &ArgMatches) -> Result<()> {
    let name = super::s(m, "new-branch").unwrap();
    let committish = super::s(m, "committish");
    if branch_exists(repo, &name) {
        return Err(Error::new(format!("branch `{name}` already exists")));
    }
    let cur = repo.head_branch();
    // Determine parent branch information
    let mut parent_branch: Option<String> = None;
    let mut remote: Option<(String, String)> = None;
    match &committish {
        None => {
            if let Some(c) = &cur {
                color::info("Recording as a local branch");
                parent_branch = Some(c.clone());
            }
        }
        Some(c) => {
            if branch_exists(repo, c) {
                color::info(&format!("Recording `{c}` as parent branch"));
                color::info("Recording as a local branch");
                parent_branch = Some(c.clone());
            } else if repo.ref_exists(&format!("refs/remotes/{c}")) {
                color::info(&format!("Recording `{c}` as parent branch"));
                color::info(&format!("Using remote `{c}` to pull parent from"));
                parent_branch = Some(c.clone());
                if let Some((r, b)) = c.split_once('/') {
                    remote = Some((r.to_string(), format!("refs/heads/{b}")));
                }
            } else {
                color::info(&format!("Do not know how to determine parent branch from `{c}`"));
            }
        }
    }
    let start = match &committish {
        None => "HEAD".to_string(),
        Some(c) => {
            if repo.rev_parse_commit(c).is_some() {
                c.clone()
            } else {
                revspec::resolve_commit(repo, Some(c), None)?
            }
        }
    };
    let start_oid = repo.rev_parse_commit(&start).ok_or_else(|| Error::new(format!("invalid committish `{start}`")))?;
    let head = repo.head_oid().unwrap_or_default();
    if start_oid != head {
        require_clean(repo)?;
    }
    repo.git(["branch", &name, &start]).run_ok()?;
    if let Err(e) = checkout(repo, &name, false) {
        let _ = repo.git(["branch", "-D", &name]).run();
        return Err(e);
    }
    let repo2 = Repo::open()?;
    Stack::load(&repo2, &name, InitPolicy::MustNotExist)?;
    if let Some(p) = parent_branch {
        set_config(&repo2, &format!("branch.{name}.stgit.parentbranch"), &p)?;
    }
    if let Some((r, mref)) = remote {
        set_config(&repo2, &format!("branch.{name}.remote"), &r)?;
        set_config(&repo2, &format!("branch.{name}.merge"), &mref)?;
    }
    Ok(())
}

fn clone(repo: &Repo, m: &ArgMatches) -> Result<()> {
    let cur = repo.head_branch().ok_or_else(|| Error::new("not on branch, HEAD is detached"))?;
    let name = match super::s(m, "new-branch") {
        Some(n) => n,
        None => {
            let t = crate::timefmt::now();
            let b = crate::timefmt::broken_down(t, crate::timefmt::local_offset(t));
            format!("{cur}-{:04}{:02}{:02}-{:02}{:02}{:02}", b.year, b.month, b.day, b.hour, b.min, b.sec)
        }
    };
    if branch_exists(repo, &name) {
        return Err(Error::new(format!("branch `{name}` already exists")));
    }
    require_clean(repo)?;
    let stack = Stack::load(repo, &cur, InitPolicy::AllowUninitialized)?;
    stack.check_head_top()?;
    repo.git(["branch", "--copy", &cur, &name]).run_ok()?;
    for (r, oid) in stack_refs(repo, &cur) {
        let new_ref = if r == stack_refname(&cur) {
            stack_refname(&name)
        } else {
            let pname = &r[format!("refs/patches/{cur}/").len()..];
            patch_refname(&name, pname)
        };
        repo.update_ref_no_log(&new_ref, &oid)?;
    }
    if !stack.is_initialized() {
        let repo2 = Repo::open()?;
        Stack::load(&repo2, &name, InitPolicy::AutoInitialize)?;
    }
    set_config(repo, &format!("branch.{name}.stgit.parentbranch"), &cur)?;
    set_config(repo, &format!("branch.{name}.description"), &format!("clone of {cur}"))?;
    checkout(repo, &name, false)
}

fn rename(repo: &Repo, m: &ArgMatches) -> Result<()> {
    let args = super::many(m, "branch-any");
    let (old, new) = if args.len() == 2 {
        (args[0].clone(), args[1].clone())
    } else {
        (repo.head_branch().ok_or_else(|| Error::new("not on branch, HEAD is detached"))?, args[0].clone())
    };
    if !branch_exists(repo, &old) {
        return Err(Error::new(format!("branch `{old}` not found")));
    }
    if branch_exists(repo, &new) {
        return Err(Error::new(format!("branch `{new}` already exists")));
    }
    let refs = stack_refs(repo, &old);
    repo.git(["branch", "-m", &old, &new]).run_ok()?;
    for (r, oid) in refs {
        let new_ref = if r == stack_refname(&old) {
            stack_refname(&new)
        } else {
            let pname = &r[format!("refs/patches/{old}/").len()..];
            patch_refname(&new, pname)
        };
        repo.update_ref_no_log(&new_ref, &oid)?;
        repo.delete_ref(&r)?;
    }
    Ok(())
}

fn protect(repo: &Repo, m: &ArgMatches, on: bool) -> Result<()> {
    let b = match super::s(m, "branch") {
        Some(b) => b,
        None => repo.head_branch().ok_or_else(|| Error::new("not on branch, HEAD is detached"))?,
    };
    let st = Stack::load(repo, &b, InitPolicy::AllowUninitialized)?;
    if !st.is_initialized() {
        return Err(Error::new(format!("StGit stack not initialized for branch `{b}`")));
    }
    if on {
        set_config(repo, &format!("branch.{b}.stgit.protect"), "true")
    } else {
        unset_config(repo, &format!("branch.{b}.stgit.protect"));
        Ok(())
    }
}

fn describe(repo: &Repo, m: &ArgMatches) -> Result<()> {
    let desc = super::s(m, "description").unwrap_or_default();
    let b = match super::s(m, "branch") {
        Some(b) => b,
        None => repo.head_branch().ok_or_else(|| Error::new("not on branch, HEAD is detached"))?,
    };
    if !branch_exists(repo, &b) {
        return Err(Error::new(format!("branch `{b}` not found")));
    }
    if desc.is_empty() {
        unset_config(repo, &format!("branch.{b}.description"));
        Ok(())
    } else {
        set_config(repo, &format!("branch.{b}.description"), &desc)
    }
}

fn delete(repo: &Repo, m: &ArgMatches, cleanup_only: bool) -> Result<()> {
    let b = match super::s(m, "branch") {
        Some(b) => b,
        None => repo.head_branch().ok_or_else(|| Error::new("not on branch, HEAD is detached"))?,
    };
    if !branch_exists(repo, &b) {
        return Err(Error::new(format!("branch `{b}` not found")));
    }
    let force = super::flag(m, "force");
    if !force && has_patches(repo, &b)? {
        return Err(Error::new(if cleanup_only {
            "clean up not permitted: the series still contains patches (override with --force)"
        } else {
            "delete not permitted: the series still contains patches (override with --force)"
        }));
    }
    if cleanup_only {
        delete_stack_refs(repo, &b)?;
        unset_config(repo, &format!("branch.{b}.stgit.protect"));
        unset_config(repo, &format!("branch.{b}.stgit.parentbranch"));
        return Ok(());
    }
    let cur = repo.head_branch();
    if cur.as_deref() == Some(b.as_str()) {
        let parent = repo.config.get(&format!("branch.{b}.stgit.parentbranch"));
        match parent {
            Some(p) if branch_exists(repo, &p) => {
                checkout(repo, &p, false)?;
            }
            _ => return Err(Error::new("cannot delete the current branch without a known parent branch")),
        }
    }
    delete_stack_refs(repo, &b)?;
    repo.git(["branch", "-D", &b]).run_ok()?;
    let _ = repo.git(["config", "--remove-section", &format!("branch.{b}")]).run();
    Ok(())
}
