            let parent = repo
                .config
                .get(&format!("branch.{b}.stgit.parentbranch"))
                .ok_or_else(|| Error::new("no committish given and no parent branch configured"))?;
            repo.rev_parse_commit(&parent).ok_or_else(|| Error::new(format!("invalid parent branch `{parent}`")))?
        }
    };
