    stack.check_head_top()?;
    if target == base {
        color::info(&format!("Already based on `{target}`{}", ref_names_at(&repo, &target)));
        return Ok(());
    }
    let autostash = super::flag(m, "autostash");
    let head_tree = repo.commit(&stack.branch_head)?.tree.clone();
    let mut stashed = false;
    if autostash {
        if !repo.conflicts()?.is_empty() {
            return Err(Error::new("resolve outstanding conflicts first"));
        }
        repo.update_index_refresh();
        if repo.index_differs_from(&head_tree)? || repo.worktree_differs()? {
            repo.git(["stash", "push"]).inherit_stdout().run_ok()?;
            stashed = true;
        }
    } else {
        check_worktree(&repo, &head_tree, &TransOpts::default())?;
    }
    let opts = TransOpts {
        allow_conflicts: super::allow_conflicts(&repo, m)?,
        committer_date_is_author_date: super::flag(m, "committer-date-is-author-date"),
        no_clean_check: true,
        ..Default::default()
    };
    let mut trans = Transaction::new(stack, opts.clone())?;
    let applied = trans.applied.clone();
    if let Some(first) = applied.first().cloned() {
        trans.pop_patches(|n| n == first);
    }
    trans.execute("rebase (pop)")?;

    color::info(&format!("Rebasing to `{target}`{}", ref_names_at(&repo, &target)));
    repo.git(["reset", "--hard", &target]).inherit_stdout().run_ok()?;
    let repo = Repo::open()?;
    let mut stack = Stack::from_branch(&repo, None, InitPolicy::AllowUninitialized)?;
    let mut st = stack.state.clone();
    st.head = target.clone();
    stack.commit_state(st, "rebase")?;

    let mut trans = Transaction::new(stack, opts)?;
    if !super::flag(m, "nopush") {
        if super::flag(m, "merged") {
            super::push::push_merged(&mut trans, &applied)?;
        } else {
            trans.push_patches(&applied, false)?;
        }
    }
    let res = trans.execute("rebase (reapply)");
    if stashed {
        let out = repo.git(["stash", "pop"]).inherit_stdout().run()?;
        if !out.ok() {
            let _ = std::io::Write::write_all(&mut std::io::stderr(), &out.stderr);
        }
    }
    res
}
