use crate::color;
use crate::error::{Error, Result};
use crate::patchname;
use crate::repo::Repo;
use crate::stack::{InitPolicy, Stack};
use crate::trans::{TransOpts, Transaction};
use clap::ArgMatches;
use std::collections::HashMap;

pub fn run(_m: &ArgMatches) -> Result<()> {
    let repo = Repo::open()?;
    let stack = Stack::from_branch(&repo, None, InitPolicy::AutoInitialize)?;
    let by_commit: HashMap<String, String> = stack.state.patches.iter().map(|(n, o)| (o.clone(), n.clone())).collect();
    // Walk first-parent chain from HEAD.
    let out = repo.git(["rev-list", "--first-parent", "--parents", &stack.branch_head]).run_ok()?;
    let mut applied_commits: Vec<String> = Vec::new();
    let mut patchify: Vec<String> = Vec::new();
    let mut maybe: Vec<String> = Vec::new();
    for line in out.stdout_str().lines() {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() != 2 {
            break;
        }
        let c = parts[0].to_string();
        if by_commit.contains_key(&c) {
            applied_commits.push(c);
            patchify.extend(maybe.drain(..));
        } else {
            maybe.push(c);
        }
    }
    applied_commits.reverse();
    patchify.reverse();
    let applied_names: Vec<String> = applied_commits.iter().map(|c| by_commit[c].clone()).collect();
    let old_applied = stack.applied().clone();
    let old_unapplied = stack.unapplied().clone();
    let hidden = stack.hidden().clone();

    let mut trans = Transaction::new(stack, TransOpts { allow_bad_head: true, no_checkout: true, no_clean_check: true, allow_existing_conflicts: true, ..Default::default() })?;
    if !patchify.is_empty() {
        let n = patchify.len();
        color::info(&format!("Creating {n} new patch{}", if n == 1 { "" } else { "es" }));
    }
    for p in &old_applied {
        if !applied_names.contains(p) {
            color::info(&format!("`{p}` is now unapplied"));
        }
