        None => None,
    };
    for src in &sources {
        if let Some(os) = &other_stack {
            let all: Vec<String> = os.state.all_patches().cloned().collect();
            let names = revspec::patch_ranges(&[src.clone()], &all, os.applied().len())?;
            for n in names {
                resolved.push((os.patch_oid(&n).unwrap().clone(), Some(n)));
            }
        } else if let Some(o) = stack.patch_oid(src) {
            resolved.push((o.clone(), Some(src.clone())));
        } else {
