            let idx = repo.git_dir.join(format!("index.stg-pick-{}", std::process::id()));
            repo.read_tree_into(&top_tree, Some(&idx))?;
            let diff = repo.git(["diff-tree", "--full-index", "--binary", "-p", &ptree, &c.tree, "--"]).run_ok()?;
            let out = repo.git(["apply", "--cached", "-R"]).index(Some(&idx)).stdin(&diff.stdout).run()?;
            if !out.ok() {
                let _ = std::fs::remove_file(&idx);
                return Err(Error::new(format!("`git apply --cached -R`: {}", out.stderr_str().trim_end())));
            }
            let tree = repo.write_index_tree(Some(&idx))?;
            let _ = std::fs::remove_file(&idx);
            let msg = format!("Revert \"{}\"\n\nThis reverts commit {}.\n", c.summary(), c.id);
            repo.write_commit(&NewCommit { tree, parents: vec![top], author: c.author.clone(), committer, extra_headers: vec![], message: msg.into_bytes() })?
        } else {
            let mut msg = c.message_str();
            if expose {
                if !msg.ends_with('\n') {
                    msg.push('\n');
                }
                msg.push_str(&format!("\n(imported from commit {})\n", c.id));
            }
            repo.write_commit(&NewCommit { tree: c.tree.clone(), parents: vec![parent], author: c.author.clone(), committer, extra_headers: vec![], message: msg.into_bytes() })?
        };
        trans.new_unapplied(&name, &new_oid, i);
        trans.print_unapplied_new(&name);
        to_push.push(name);
    }
    if !noapply {
        trans.push_patches(&to_push, false)?;
    }
    trans.execute("pick")
}
