use crate::error::{Error, Result};
use crate::repo::Repo;
use crate::revspec;
use crate::stack::{InitPolicy, Stack};
use clap::ArgMatches;

pub const DEFAULT_TEMPLATE: &str = "%(shortdescr)s\n\nFrom: %(authname)s <%(authemail)s>\n\n%(longdescr)s\n---\n%(diffstat)s\n";

pub fn diffstat(repo: &Repo, diff: &[u8]) -> Result<String> {
    if diff.is_empty() {
        return Ok(String::new());
    }
    let out = repo.git(["apply", "--stat", "--summary"]).stdin(diff).run_ok()?;
    Ok(out.stdout_str())
}

pub fn find_template(repo: &Repo, name: &str) -> Option<String> {
    let p = repo.git_dir.join(name);
    if let Ok(s) = std::fs::read_to_string(&p) {
        return Some(s);
    }
    if let Ok(h) = std::env::var("HOME") {
        let p = std::path::Path::new(&h).join(".stgit").join("templates").join(name);
        if let Ok(s) = std::fs::read_to_string(&p) {
            return Some(s);
        }
    }
    None
}

pub fn expand_template(tmpl: &str, vars: &[(&str, String)]) -> String {
    let mut out = tmpl.to_string();
    for (k, v) in vars {
        out = out.replace(&format!("%({k})s"), v);
    }
    out
}

pub fn run(m: &ArgMatches) -> Result<()> {
    let repo = Repo::open()?;
    let branch = super::s(m, "branch");
