    let patches: Vec<String> = if args.is_empty() {
        if stack.applied().is_empty() {
            return Err(Error::new("no patches applied"));
        }
        stack.applied().clone()
    } else {
        revspec::patch_ranges(&args, &all, stack.applied().len())?
    };
    let tmpl = match super::s(m, "template") {
        Some(t) => std::fs::read_to_string(&t).map_err(|e| Error::new(format!("{t}: {e}")))?,
        None => find_template(&repo, "patchexport.tmpl").unwrap_or_else(|| DEFAULT_TEMPLATE.to_string()),
    };
    let diff_opts = super::many(m, "diff-opt");
    let to_stdout = super::flag(m, "stdout");
    let dir = super::s(m, "dir").unwrap_or_else(|| format!("patches-{}", stack.branch));
    let ext = if super::flag(m, "patch") { Some("patch".to_string()) } else { super::s(m, "extension") };
    let numbered = super::flag(m, "numbered");
    let num_width = std::cmp::max(2, patches.len().to_string().len());
    if !to_stdout {
