use crate::edit::{self, EditOpts};
use crate::error::{Error, Result};
use crate::git::NewCommit;
use crate::patchname;
use crate::repo::Repo;
use crate::stack::{InitPolicy, Stack};
use crate::trans::{TransOpts, Transaction};
use clap::ArgMatches;

pub struct ParsedPatch {
    pub message: String,
    pub author: Option<(String, String)>,
    pub date: Option<String>,
    pub diff: Vec<u8>,
    pub subject_for_name: String,
}

fn is_diff_start(line: &str) -> bool {
    line.starts_with("diff --git ") || line.starts_with("Index: ") || line.starts_with("diff -")
}

/// Split text into (description, diff).
fn split_descr_diff(text: &str) -> (String, String) {
    let lines: Vec<&str> = text.split_inclusive('\n').collect();
    let mut descr = String::new();
    let mut i = 0;
    let mut in_descr = true;
    while i < lines.len() {
        let l = lines[i].trim_end_matches('\n').trim_end_matches('\r');
        if is_diff_start(l) || (l.starts_with("--- ") && lines.get(i + 1).map(|n| n.starts_with("+++ ")).unwrap_or(false)) {
            break;
        }
        if in_descr && l == "---" {
            in_descr = false;
        } else if in_descr {
            descr.push_str(lines[i]);
        }
        i += 1;
    }
    let diff: String = lines[i..].concat();
    (descr, diff)
}

fn header_value<'a>(line: &'a str, key: &str) -> Option<&'a str> {
    let t = line.trim_start();
    if t.len() > key.len() && t[..key.len()].eq_ignore_ascii_case(key) && t.as_bytes()[key.len()] == b':' {
        let rest = &t[key.len() + 1..];
        if rest.starts_with(char::is_whitespace) {
            return Some(rest.trim());
        }
    }
    None
}

fn parse_name_email_loose(s: &str) -> Option<(String, String)> {
    if let Some(ne) = edit::parse_name_email(s) {
        return Some(ne);
    }
    let s = s.trim();
    if s.contains('@') && !s.contains(' ') {
        return Some((s.to_string(), s.to_string()));
    }
    None
}

/// Parse a description the way StGit does for plain diff files.
fn parse_description(descr: &str) -> (String, Option<(String, String)>, Option<String>) {
    let lines: Vec<String> = descr.split('\n').map(|l| l.trim_end().to_string()).collect();
    let mut subject = String::new();
    let mut author = None;
    let mut date = None;
    let mut lasthdr = 0;
    let mut strip = 0usize;
    for (pos, line) in lines.iter().enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        if let Some(v) = header_value(line, "from").or_else(|| header_value(line, "author")) {
            author = parse_name_email_loose(v);
            lasthdr = pos + 1;
            continue;
        }
        if let Some(v) = header_value(line, "date") {
            date = Some(v.to_string());
            lasthdr = pos + 1;
            continue;
        }
        if subject.is_empty() {
            if let Some(v) = header_value(line, "subject") {
                subject = v.to_string();
                lasthdr = pos + 1;
                continue;
            }
        }
        if !subject.is_empty() {
            break;
        }
        let l: String = line.chars().skip(strip).collect();
        subject = l.trim().to_string();
        let is_commit = subject.len() == 47 && subject.starts_with("commit ") && subject[7..].chars().all(|c| c.is_ascii_hexdigit());
        if is_commit {
            subject.clear();
            strip = 4;
        }
        lasthdr = pos + 1;
    }
    let mut body = String::new();
    if lasthdr < lines.len() {
        let rest: Vec<String> = lines[lasthdr..].iter().map(|l| l.chars().skip(strip.min(l.chars().take_while(|c| *c == ' ').count())).collect()).collect();
        body = format!("\n{}", rest.join("\n"));
    }
    (format!("{subject}{body}"), author, date)
}

fn decode_rfc2047(s: &str) -> String {
    // Minimal support for =?utf-8?q?...?= and =?utf-8?b?...?=
    let mut out = String::new();
    let mut rest = s;
    while let Some(start) = rest.find("=?") {
        out.push_str(&rest[..start]);
        let after = &rest[start + 2..];
        let parts: Vec<&str> = after.splitn(4, '?').collect();
        if parts.len() == 4 && parts[3].starts_with('=') {
            let enc = parts[1].to_ascii_lowercase();
            let text = parts[2];
            let bytes: Vec<u8> = if enc == "q" {
                let mut v = Vec::new();
                let b = text.as_bytes();
                let mut i = 0;
                while i < b.len() {
                    if b[i] == b'_' {
                        v.push(b' ');
                    } else if b[i] == b'=' && i + 2 < b.len() + 0 && i + 2 <= b.len() - 1 {
                        if let Ok(x) = u8::from_str_radix(&text[i + 1..i + 3], 16) {
                            v.push(x);
                            i += 3;
                            continue;
                        }
                        v.push(b[i]);
                    } else {
                        v.push(b[i]);
                    }
                    i += 1;
                }
                v
            } else {
                base64_decode(text)
            };
            out.push_str(&String::from_utf8_lossy(&bytes));
            rest = &parts[3][1..];
            rest = rest.trim_start_matches([' ', '\t']).strip_prefix("").unwrap_or(rest);
        } else {
            out.push_str("=?");
            rest = after;
        }
    }
    out.push_str(rest);
    out
}

fn base64_decode(s: &str) -> Vec<u8> {
    let tbl = |c: u8| -> Option<u32> {
        match c {
            b'A'..=b'Z' => Some((c - b'A') as u32),
            b'a'..=b'z' => Some((c - b'a' + 26) as u32),
            b'0'..=b'9' => Some((c - b'0' + 52) as u32),
            b'+' => Some(62),
            b'/' => Some(63),
            _ => None,
        }
    };
    let mut out = Vec::new();
    let mut buf = 0u32;
    let mut bits = 0;
    for &c in s.as_bytes() {
        if let Some(v) = tbl(c) {
            buf = (buf << 6) | v;
            bits += 6;
            if bits >= 8 {
                bits -= 8;
                out.push((buf >> bits) as u8 & 0xff);
            }
        }
    }
    out
}

pub fn strip_subject_prefixes(s: &str) -> String {
    let mut s = s.trim().to_string();
    loop {
        let t = s.trim_start();
        if t.starts_with('[') {
            if let Some(end) = t.find(']') {
                s = t[end + 1..].trim_start().to_string();
                continue;
            }
        }
        if t.len() >= 3 && t[..3].eq_ignore_ascii_case("re:") {
            s = t[3..].trim_start().to_string();
            continue;
        }
        break;
    }
    s
}

/// Parse an email message.
pub fn parse_mail(text: &str, strip_prefix: bool, keep_cr: bool, message_id: bool) -> ParsedPatch {
    let text = if keep_cr { text.to_string() } else { text.replace("\r\n", "\n") };
    let mut lines = text.split_inclusive('\n').peekable();
    // Skip mbox "From " line
    if let Some(l) = lines.peek() {
        if l.starts_with("From ") {
            lines.next();
        }
    }
    let mut headers: Vec<(String, String)> = Vec::new();
    for l in lines.by_ref() {
        let lt = l.trim_end_matches('\n');
        if lt.is_empty() {
            break;
        }
        if lt.starts_with(' ') || lt.starts_with('\t') {
            if let Some(last) = headers.last_mut() {
                last.1.push(' ');
                last.1.push_str(lt.trim());
            }
            continue;
        }
        if let Some((k, v)) = lt.split_once(':') {
            headers.push((k.trim().to_ascii_lowercase(), v.trim().to_string()));
        }
    }
    let body: String = lines.collect();
    let get = |k: &str| headers.iter().find(|(hk, _)| hk == k).map(|(_, v)| decode_rfc2047(v));
    let subject_raw = get("subject").unwrap_or_default();
    let subject = if strip_prefix { strip_subject_prefixes(&subject_raw) } else { subject_raw.trim().to_string() };
    let author = get("from").and_then(|f| parse_name_email_loose(&f));
    let date = get("date");
    let (descr, diff) = split_descr_diff(&body);
    let mut message = if descr.trim().is_empty() { subject.clone() } else { format!("{subject}\n\n{descr}") };
    if message_id {
        if let Some(mid) = get("message-id") {
            message = edit::cleanup_message(&message, false);
            message = edit::add_trailer(&message, "Message-ID", &mid);
        }
    }
    ParsedPatch { message, author, date, diff: diff.into_bytes(), subject_for_name: subject }
}

fn looks_like_mail(text: &str) -> bool {
    if text.starts_with("From ") {
        return true;
    }
    false
}

pub fn parse_patch_text(text: &str, mail: bool, keep_cr: bool, message_id: bool) -> ParsedPatch {
    if mail {
        return parse_mail(text, true, keep_cr, message_id);
    }
    if looks_like_mail(text) {
        return parse_mail(text, false, keep_cr, false);
    }
    let (descr, diff) = split_descr_diff(text);
    let (message, author, date) = parse_description(&descr);
    let subject_for_name = message.lines().next().unwrap_or("").to_string();
    ParsedPatch { message, author, date, diff: diff.into_bytes(), subject_for_name }
}

fn strip_name(name: &str) -> String {
    let mut n = name.to_string();
    // strip leading number and dash/underscore
    let digits = n.chars().take_while(|c| c.is_ascii_digit()).count();
    if digits > 0 {
        let rest = &n[digits..];
        if let Some(r) = rest.strip_prefix(['-', '_']) {
            n = r.to_string();
        }
    }
    if let Some(i) = n.rfind('.') {
        if i > 0 {
            n.truncate(i);
        }
    }
    n
}

pub struct ImportCtx<'a> {
    pub repo: &'a Repo,
    pub m: &'a ArgMatches,
}

fn apply_diff(repo: &Repo, m: &ArgMatches, diff: &[u8]) -> Result<()> {
    if diff.is_empty() {
        return Ok(());
    }
    let mut args: Vec<String> = vec!["apply".into(), "--index".into()];
    if let Some(p) = super::s(m, "strip") {
        args.push(format!("-p{p}"));
    }
    if let Some(d) = super::s(m, "directory") {
        args.push(format!("--directory={d}"));
    }
    if let Some(c) = super::s(m, "context") {
        args.push(format!("-C{c}"));
    }
    if super::flag(m, "3way") {
        args.push("--3way".into());
    }
    if super::flag(m, "reject") {
        args.push("--reject".into());
    }
    let label = args[..2].join(" ");
    let out = repo.git(&args).cwd(&repo.cwd).stdin(diff).run()?;
    if !out.ok() {
        return Err(Error::new(format!("`git {label}`: {}", out.stderr_str().trim_end())));
    }
    Ok(())
}

fn import_one(repo: &Repo, m: &ArgMatches, text: &str, file_name: Option<&str>, mail: bool) -> Result<()> {
    let eo = EditOpts::from_matches(m);
    let parsed = parse_patch_text(text, mail, super::flag(m, "keep-cr"), super::flag(m, "message-id") || repo.config.get_bool("stgit.import.message-id").unwrap_or(false));
    let stack = Stack::from_branch(repo, None, InitPolicy::AutoInitialize)?;
    stack.check_head_top()?;
    let limit = super::new::name_len_limit(repo);
    let base_name = match super::s(m, "name") {
        Some(n) => n,
        None => match file_name {
            Some(f) if !mail => {
                let b = std::path::Path::new(f).file_name().map(|s| s.to_string_lossy().into_owned()).unwrap_or_default();
                let b = if super::flag(m, "stripname") { strip_name(&b) } else { b };
                patchname::make_candidate(&b, None)
            }
            _ => patchname::make_candidate(&parsed.subject_for_name, limit),
        },
    };
    let name = if stack.state.has_patch(&base_name) {
        if super::flag(m, "replace") && stack.unapplied().contains(&base_name) {
            base_name.clone()
        } else {
            return Err(Error::new(format!("patch `{base_name}` already exists")));
        }
    } else {
        base_name
    };
    let head_tree = repo.commit(&stack.branch_head)?.tree.clone();
    crate::trans::check_worktree(repo, &head_tree, &TransOpts::default())?;
    apply_diff(repo, m, &parsed.diff)?;
    let tree = repo.write_index_tree(None)?;
    let mut author = repo.author()?;
    if let Some((n, e)) = &parsed.author {
        author.name = n.clone();
        author.email = e.clone();
    }
    if let Some(d) = &parsed.date {
        if let Some((t, o)) = crate::timefmt::parse_date(d) {
            author.time = t;
            author.offset = o;
        }
    }
    eo.apply_author(&mut author)?;
    let mut message = edit::cleanup_message(&parsed.message, false);
    message = eo.apply_trailers(repo, &message)?;
    if eo.edit {
        let t = edit::make_template(&name, &author, &message, None);
        let edited = edit::edit_text(repo, &String::from_utf8_lossy(&t))?;
        let p = edit::parse_edited(&edited)?;
        message = p.message;
    }
    let mut committer = repo.committer()?;
    if eo.committer_date_is_author_date {
        committer.time = author.time;
        committer.offset = author.offset;
    }
    let nc = NewCommit { tree: tree.clone(), parents: vec![stack.branch_head.clone()], author, committer, extra_headers: vec![], message: message.into_bytes() };
    let oid = repo.write_commit(&nc)?;
    let mut trans = Transaction::new(stack, TransOpts { no_clean_check: true, ..Default::default() })?;
    trans.set_current_tree(&tree);
    if trans.has_patch(&name) {
        trans.delete_patches(|n| n == name)?;
    }
    trans.new_applied(&name, &oid);
    trans.execute(&format!("import: {name}"))
}

fn read_source(src: Option<&str>) -> Result<String> {
    let data = match src {
        Some(f) => std::fs::read(f).map_err(|e| Error::new(format!("{f}: {e}")))?,
        None => {
            let mut v = Vec::new();
            use std::io::Read;
            std::io::stdin().read_to_end(&mut v)?;
            v
        }
    };
    Ok(String::from_utf8_lossy(&data).into_owned())
}

pub fn run(m: &ArgMatches) -> Result<()> {
    let repo = Repo::open()?;
    let src = super::s(m, "source");
    if super::flag(m, "url") {
        return super::not_implemented("import --url");
    }
    if super::flag(m, "series") {
        let text = read_source(src.as_deref())?;
        let dir = src.as_ref().and_then(|s| std::path::Path::new(s).parent().map(|p| p.to_path_buf())).unwrap_or_default();
        for line in text.lines() {
            let l = line.split('#').next().unwrap_or("").trim();
            if l.is_empty() {
                continue;
            }
            let path = dir.join(l);
            let pt = read_source(Some(&path.to_string_lossy()))?;
            import_one(&repo, m, &pt, Some(l), false)?;
        }
        return Ok(());
    }
    if super::flag(m, "mbox") {
        let text = read_source(src.as_deref())?;
        let mut msgs: Vec<String> = Vec::new();
        let mut cur = String::new();
        for l in text.split_inclusive('\n') {
            if l.starts_with("From ") && !cur.is_empty() {
                msgs.push(std::mem::take(&mut cur));
            }
            cur.push_str(l);
        }
        if !cur.is_empty() {
            msgs.push(cur);
        }
        for msg in msgs {
            import_one(&repo, m, &msg, None, true)?;
        }
        return Ok(());
    }
    let text = read_source(src.as_deref())?;
    import_one(&repo, m, &text, src.as_deref(), super::flag(m, "mail"))
}
