            use std::io::Read;
            std::io::stdin().read_to_end(&mut v)?;
            v
        }
    };
    let mut extra: Vec<String> = Vec::new();
    if let Some(p) = super::s(m, "strip") {
        extra.push(format!("-p{p}"));
    }
    if let Some(c) = super::s(m, "context") {
        extra.push(format!("-C{c}"));
    }
    if super::flag(m, "reject") {
        extra.push("--reject".into());
    }
    let base = if super::flag(m, "threeway") {
        let top = stack.applied().last().unwrap().clone();
        Some(stack.patch_commit(&top)?.parents[0].clone())
    } else {
        super::s(m, "base").map(|b| revspec::resolve_commit(&repo, Some(&b), None)).transpose()?
    };
    match base {
        None => {
            let mut args: Vec<String> = vec!["apply".into(), "--index".into()];
            args.extend(extra);
            let out = repo.git(&args).cwd(&repo.cwd).stdin(&data).run()?;
            if !out.ok() {
                return Err(Error::new(format!("`git apply --index`: {}", out.stderr_str().trim_end())));
            }
        }
        Some(b) => {
            // Apply onto the base in a temporary index, then merge with the current top.
            let base_tree = repo.commit(&b)?.tree.clone();
            let idx = repo.git_dir.join(format!("index.stg-fold-{}", std::process::id()));
            repo.read_tree_into(&base_tree, Some(&idx))?;
            let mut args: Vec<String> = vec!["apply".into(), "--cached".into()];
            args.extend(extra);
            let out = repo.git(&args).index(Some(&idx)).stdin(&data).run()?;
            if !out.ok() {
                let _ = std::fs::remove_file(&idx);
                return Err(Error::new(format!("`git apply --index`: {}", out.stderr_str().trim_end())));
            }
            let new_tree = repo.write_index_tree(Some(&idx))?;
            let _ = std::fs::remove_file(&idx);
            let head_tree = repo.commit(&stack.branch_head)?.tree.clone();
            let out = repo
                .git(["merge-recursive", &base_tree, "--", &head_tree, &new_tree])
                .env(&format!("GITHEAD_{head_tree}"), "current")
                .env(&format!("GITHEAD_{new_tree}"), "patched")
                .run()?;
            if !out.ok() {
                return Err(Error::new("merge conflicts"));
            }
        }
    }
    Ok(())
}
