use crate::error::{Error, Result};
use crate::git::NewCommit;
use crate::repo::Repo;
use crate::stack::{InitPolicy, Stack};
use crate::trans::{TransOpts, Transaction};
use clap::ArgMatches;

pub fn run(m: &ArgMatches) -> Result<()> {
    let repo = Repo::open()?;
    let stack = Stack::from_branch(&repo, None, InitPolicy::AllowUninitialized)?;
    let top = match stack.applied().last() {
        Some(t) => t.clone(),
        None => return Err(Error::new("no patches applied")),
    };
    stack.check_head_top()?;
    if !repo.conflicts()?.is_empty() {
        return Err(Error::new("resolve outstanding conflicts first"));
    }
    let c = stack.patch_commit(&top)?;
    let parent = c.parents.first().cloned().ok_or_else(|| Error::new("patch has no parent"))?;
    let parent_tree = repo.commit(&parent)?.tree.clone();
    let paths = super::many(m, "path");
    let new_tree = if paths.is_empty() {
        parent_tree.clone()
    } else {
        let idx = repo.git_dir.join(format!("index.stg-spill-{}", std::process::id()));
        repo.read_tree_into(&c.tree, Some(&idx))?;
        // Reset the given paths to the parent's version.
        let mut args: Vec<String> = vec!["reset".into(), "-q".into(), parent_tree.clone(), "--".into()];
        args.extend(paths.iter().cloned());
        let _ = crate::git::git(&args).index(Some(&idx)).run();
        let t = repo.write_index_tree(Some(&idx))?;
        let _ = std::fs::remove_file(&idx);
        t
    };
    let mut committer = repo.committer()?;
    if super::flag(m, "committer-date-is-author-date") {
        committer.time = c.author.time;
        committer.offset = c.author.offset;
    }
    let nc = NewCommit {
        tree: new_tree,
        parents: c.parents.clone(),
        author: c.author.clone(),
        committer,
        extra_headers: c.extra_headers.iter().filter(|(k, _)| k == "encoding").cloned().collect(),
        message: c.message.clone(),
    };
    let oid = repo.write_commit(&nc)?;
    let mut trans = Transaction::new(stack, TransOpts { no_checkout: true, no_clean_check: true, ..Default::default() })?;
    trans.set_patch_commit(&top, &oid);
    trans.print_updated(&top);
    let mut msg = format!("spill {top}");
    if let Some(a) = super::many(m, "annotate").first() {
        msg = format!("{msg}\n\n{a}");
    }
    trans.execute(&msg)?;
    if super::flag(m, "reset") {
        let head_tree = repo.commit(&oid)?.tree.clone();
        let mut args: Vec<String> = vec!["reset".into(), "-q".into(), head_tree, "--".into()];
        if !paths.is_empty() {
            args.extend(paths);
        }
        let _ = crate::git::git(&args).run();
    }
    Ok(())
}
