use crate::error::{Error, Result};
use crate::repo::Repo;
use crate::stack::{InitPolicy, Stack};
use clap::ArgMatches;

pub fn run(m: &ArgMatches) -> Result<()> {
    let repo = Repo::open()?;
    let branch = super::s(m, "branch");
    let stack = Stack::from_branch(&repo, branch.as_deref(), InitPolicy::AllowUninitialized)?;
    if stack.applied().is_empty() {
        return Err(Error::new("no patches applied"));
    }
    let mut paths = super::many(m, "path");
    if paths.is_empty() {
        let out = repo.git(["diff-index", "--name-only", "HEAD", "--"]).cwd(&repo.cwd).run_ok()?;
        paths = out.stdout_str().lines().map(|l| {
            // diff-index paths are relative to the top; convert relative to cwd
            l.to_string()
        }).collect();
        if paths.is_empty() {
            return Err(Error::new("no local changes and no paths specified"));
        }
        let top = repo.work_dir()?.to_path_buf();
        paths = paths.into_iter().map(|p| top.join(p).to_string_lossy().into_owned()).collect();
    }
    // Normalize paths relative to the top of the work tree.
    let mut args: Vec<String> = vec!["ls-files".into(), "--full-name".into(), "--with-tree=HEAD".into(), "--".into()];
    args.extend(paths.iter().cloned());
    let out = repo.git(&args).cwd(&repo.cwd).run()?;
    let mut rel: Vec<String> = out.stdout_str().lines().map(|s| s.to_string()).collect();
    if rel.is_empty() {
        let prefix = repo.prefix.clone();
        rel = paths.iter().map(|p| format!("{prefix}{p}")).collect();
    }
    let diff_opts = super::many(m, "diff-opt");
    let show_diff = super::flag(m, "diff");
    let mut out = Vec::new();
    for p in stack.applied() {
        let c = stack.patch_commit(p)?;
        let parent = c.parents.first().cloned().unwrap_or_default();
        let mut a: Vec<String> = vec!["diff-tree".into(), "-r".into(), "--name-only".into(), parent.clone(), c.id.clone(), "--".into()];
        a.extend(rel.iter().cloned());
        let o = repo.git(&a).run_ok()?;
        if o.stdout.is_empty() {
            continue;
        }
        if show_diff {
            let sep = "-".repeat(50);
            out.extend_from_slice(format!("{sep}\n{p}\n{sep}\n").as_bytes());
            out.extend_from_slice(&c.message);
            out.extend_from_slice(b"\n---\n");
            let mut d: Vec<String> = vec!["diff-tree".into(), "-p".into()];
            d.extend(diff_opts.iter().cloned());
            d.push(parent);
            d.push(c.id.clone());
            d.push("--".into());
            d.extend(rel.iter().cloned());
            out.extend_from_slice(&repo.git(&d).run_ok()?.stdout);
        } else {
            out.extend_from_slice(format!("{p}\n").as_bytes());
        }
    }
    use std::io::Write;
    let _ = std::io::stdout().write_all(&out);
    Ok(())
}
