use crate::error::{Error, Result};
use crate::repo::Repo;
use crate::revspec;
use crate::stack::{InitPolicy, Stack};
use clap::parser::ValueSource;
use clap::ArgMatches;

const SKIP: &[&str] = &["branch", "all", "git-opt", "source", "patch", "color"];

/// Forward options given on the command line to a git command.
fn forward(m: &ArgMatches, cmd: &clap::Command) -> Vec<String> {
    let mut v: Vec<(usize, String)> = Vec::new();
    for a in cmd.get_arguments() {
        let id = a.get_id().as_str();
        if SKIP.contains(&id) || a.is_positional() || id == "help" {
            continue;
        }
        if m.value_source(id) != Some(ValueSource::CommandLine) {
            continue;
        }
        let long = a.get_long().unwrap_or(id).to_string();
        let idxs: Vec<usize> = m.indices_of(id).map(|i| i.collect()).unwrap_or_default();
        if a.get_num_args().map(|n| n.takes_values()).unwrap_or(false) {
            if let Ok(Some(raw)) = m.try_get_raw_occurrences(id) {
                for (k, occ) in raw.enumerate() {
                    let vals: Vec<String> = occ.map(|s| s.to_string_lossy().into_owned()).collect();
                    let i = idxs.get(k).copied().unwrap_or(0);
                    if vals.is_empty() {
                        v.push((i, format!("--{long}")));
                    } else {
                        for val in vals {
                            v.push((i, format!("--{long}={val}")));
                        }
                    }
                }
            }
        } else {
            let i = idxs.first().copied().unwrap_or(0);
            v.push((i, format!("--{long}")));
        }
    }
    v.sort_by_key(|x| x.0);
    let mut out: Vec<String> = v.into_iter().map(|x| x.1).collect();
    out.extend(super::many(m, "git-opt"));
    out
}

fn patch_range(repo: &Repo, stack: &Stack, m: &ArgMatches, specs: &[String]) -> Result<String> {
    let all: Vec<String> = stack.state.all_patches().cloned().collect();
    let applied = stack.applied();
    let patches: Vec<String> = if super::flag(m, "all") {
        applied.clone()
    } else {
        let mut v: Vec<String> = Vec::new();
        for s in specs {
            let names = revspec::patch_ranges(&[s.clone()], &all, applied.len())?;
            if let Some(last) = v.last() {
                let li = applied.iter().position(|x| x == last);
                let fi = applied.iter().position(|x| *x == names[0]);
                match (li, fi) {
                    (Some(a), Some(b)) if b == a + 1 => {}
                    _ => return Err(Error::new(format!("`{}` not contiguous with preceding range `{}`", names[0], last))),
                }
            }
            v.extend(names);
        }
        v
    };
    if patches.is_empty() {
        return Err(Error::new("no patches applied"));
    }
    for p in &patches {
        if !applied.contains(p) {
            return Err(Error::new(format!("patch `{p}` is not applied")));
        }
    }
    let first = stack.patch_commit(&patches[0])?;
    let last = stack.patch_oid(patches.last().unwrap()).unwrap().clone();
    let base = first.parents.first().cloned().unwrap_or_default();
    let _ = repo;
    Ok(format!("{base}..{last}"))
}

pub fn run(m: &ArgMatches) -> Result<()> {
    let repo = Repo::open()?;
    let (sub, sm) = m.subcommand().ok_or_else(|| Error::new("missing subcommand"))?;
    let branch = super::s(sm, "branch");
    let cmd = match sub {
        "format" => crate::cli::cmd_email_format(),
        _ => crate::cli::cmd_email_send(),
    };
    let stack = Stack::from_branch(&repo, branch.as_deref(), InitPolicy::AllowUninitialized)?;
    let mut args: Vec<String> = Vec::new();
    if sub == "format" {
        args.push("format-patch".into());
        args.extend(forward(sm, &cmd));
        let specs = super::many(sm, "patch");
        args.push(patch_range(&repo, &stack, sm, &specs)?);
    } else {
        args.push("send-email".into());
        args.extend(forward(sm, &cmd));
        let sources = super::many(sm, "source");
        let mut patch_specs = Vec::new();
        for s in &sources {
            if std::path::Path::new(s).exists() {
                args.push(s.clone());
            } else {
                patch_specs.push(s.clone());
            }
        }
        if !patch_specs.is_empty() || super::flag(sm, "all") {
            args.push(patch_range(&repo, &stack, sm, &patch_specs)?);
        }
    }
    let out = repo.git(&args).cwd(&repo.cwd).inherit_stdout().inherit_stderr().run()?;
    if !out.ok() {
        return Err(Error::silent(out.status));
    }
    Ok(())
}
