new = '''/// Update the index from the worktree as requested and return the resulting tree.
pub fn compute_refresh_tree(repo: &Repo, stack: &Stack, o: &RefreshTreeOpts, patch: Option<&str>) -> Result<Oid> {
    if o.index {
        return repo.write_index_tree(None);
    }
    let head_tree = repo.commit(&stack.branch_head)?.tree.clone();
    repo.update_index_refresh();
    if o.paths.is_empty() && !o.force && !o.update {
        let index_dirty = repo.index_differs_from(&head_tree)?;
        let wt_dirty = repo.worktree_differs()?;
        if index_dirty && wt_dirty {
            return Err(Error::new("the index is dirty; consider using `--index` or `--force`"));
        }
    }
    // Files that differ between HEAD and the worktree (restricted to paths).
    let mut args: Vec<String> = vec!["diff-index".into(), "--name-only".into(), "-z".into(), "--no-renames".into(), head_tree.clone(), "--".into()];
    args.extend(o.paths.iter().cloned());
    let out = crate::git::git(&args).run_ok()?;
    let mut files: Vec<String> = out.stdout.split(|&b| b == 0).filter(|s| !s.is_empty()).map(|s| String::from_utf8_lossy(s).into_owned()).collect();
    if o.update {
        let pf = match patch.and_then(|p| stack.patch_oid(p).cloned()) {
            Some(oid) => commit_files(repo, &oid)?,
            None => Vec::new(),
        };
        files.retain(|f| pf.contains(f));
    }
    let idx = repo.git_dir.join(format!("index.stg-refresh-{}", std::process::id()));
    repo.read_tree_into(&head_tree, Some(&idx))?;
    if !files.is_empty() {
        let mut input = Vec::new();
        for f in &files {
            input.extend_from_slice(f.as_bytes());
            input.push(0);
        }
        repo.git(["update-index", "--add", "--remove", "-z", "--stdin"]).index(Some(&idx)).stdin(&input).run_ok()?;
        repo.git(["update-index", "--add", "--remove", "-z", "--stdin"]).stdin(&input).run_ok()?;
    }
    let tree = repo.write_index_tree(Some(&idx))?;
    let _ = std::fs::remove_file(&idx);
    Ok(tree)
}

