/// Resolve names and ranges against a single ordered list: "a.." extends to the
/// end of the list, "..b" from its start. Names must exist in `all`.
pub fn patch_ranges_list(args: &[String], list: &[String], all: &[String]) -> Result<Vec<String>> {
    let mut out = Vec::new();
    for a in args {
        if let Some((lo, hi)) = a.split_once("..") {
            let find = |n: &str| -> Result<usize> {
                match list.iter().position(|x| x == n) {
                    Some(i) => Ok(i),
                    None => {
                        if all.iter().any(|x| x == n) {
                            Err(Error::new(format!("patch `{n}` is hidden")))
                        } else {
                            Err(Error::new(patchname::not_found_msg(n, all)))
                        }
                    }
                }
            };
            if list.is_empty() {
                continue;
            }
            let start = if lo.is_empty() { 0 } else { find(lo)? };
            let end = if hi.is_empty() { list.len() - 1 } else { find(hi)? };
            if end < start {
                return Err(Error::new(format!("end patch `{hi}` is out of order with `{lo}`")));
            }
            out.extend(list[start..=end].iter().cloned());
        } else {
            if !all.contains(a) {
                return Err(Error::new(patchname::not_found_msg(a, all)));
            }
            out.push(a.clone());
        }
    }
    Ok(out)
}
